1	// Cyrus asset catalog v2: CatalogEntry v1, ONE metadata record per library asset (3D model, PBR texture set,
2	// texture, sprite, HDRI, decal, sound, music), whatever its source (CC0 packs, the owner's proprietary library,
3	// Cyrus originals, community contributions from Cyrus users). The record is what Cyrus reads to PICK an asset for a
4	// situation, so it carries: what the asset is (title, <=140-char description, controlled tags, one primary + up to
5	// 3 secondary categories, situations it is good for), how good it is (quality score + the checks behind it), where
6	// it fits (per-game fit derived from each game's AssetProfile), technical facts, licence, provenance, the legal class
7	// of lib/cyrus/assets3d/manifest.ts and the moderation status.
8	// Pure, client-safe, Zod-validated; `catalogEntryJsonSchema()` is the portable contract. HOST SEAM: no Nxeon imports.
9	import { z } from "zod";
10	import { LEGAL_CLASSES } from "../../assets3d/manifest";
11	import type { AssetKind } from "../../engine-core/spec";
12	import type { LibraryKind } from "../types";
13	
14	export const CATALOG_SCHEMA_VERSION = 1 as const;
15	
16	export const CATALOG_KINDS = ["model", "texture-set", "texture", "sprite", "hdri", "decal", "sound", "music"] as const;
17	export type CatalogKind = (typeof CATALOG_KINDS)[number];
18	
19	/** cc0 / cc-by: open licences; proprietary-nxeon: bought or owned by Nxeon (never redistributed as files); user-contributed: made in Cyrus by a customer (auto-contribution, owner decision 2026-10-10). */
20	export const LICENCE_TIERS = ["cc0", "cc-by", "proprietary-nxeon", "user-contributed"] as const;
21	export type LicenceTier = (typeof LICENCE_TIERS)[number];
22	
23	/** pending-checks -> published | held; held -> published | removed; published -> held | removed. */
24	export const CATALOG_STATUSES = ["pending-checks", "published", "held", "removed"] as const;
25	export type CatalogStatus = (typeof CATALOG_STATUSES)[number];
26	
27	export const FITS = ["good", "ok", "no"] as const;
28	export type Fit = (typeof FITS)[number];
29	
30	/** Which enrichment stage last wrote the descriptive fields (title, description, tags, categories, useFor). */
31	export const ENRICHED_BY = ["stage-a", "stage-b", "owner", "contributor"] as const;
32	export type EnrichedBy = (typeof ENRICHED_BY)[number];
33	
34	export const SHA256_HEX = /^[0-9a-f]{64}$/;
35	/** How a catalog asset is referenced everywhere outside the catalog (ModSpec asset slots, packs, logs). */
36	export const CATALOG_REF_RE = /^cat:[0-9a-f]{64}$/;
37	export const catalogRef = (id: string) => `cat:${id}`;
38	export const CATEGORY_ID_RE = /^[a-z0-9-]+\/[a-z0-9_-]+$/;
39	export const TAG_RE = /^[a-z0-9][a-z0-9-]{0,31}$/;
40	export const GAME_RE = /^[a-z][a-z0-9-]{1,31}$/;
41	
42	const tag = z.string().regex(TAG_RE);
43	const cat = z.string().regex(CATEGORY_ID_RE);
44	
45	export const QualityCheckZ = z.object({
46	  id: z.string().min(1).max(40),
47	  status: z.enum(["pass", "warn", "fail", "skip"]),
48	  weight: z.number().min(0).max(10),
49	  /** measured value or the reason it was skipped */
50	  detail: z.string().max(160),
51	}).strict();
52	export type QualityCheck = z.infer<typeof QualityCheckZ>;
53	
54	export const QualityZ = z.object({
55	  /** 0-100; see lib/cyrus/library/v2/quality.ts (version cq-1) */
56	  score: z.number().int().min(0).max(100),
57	  version: z.string().max(16),
58	  /** one line: how the score was computed (so an owner can audit it) */
59	  method: z.string().max(200),
60	  /** share of the check weight that was actually measured (0-1); unmeasured checks never count as passes */
61	  measured: z.number().min(0).max(1),
62	  checks: z.array(QualityCheckZ).max(30),
63	}).strict();
64	export type Quality = z.infer<typeof QualityZ>;
65	
66	export const GameFitZ = z.object({
67	  fit: z.enum(FITS),
68	  reason: z.string().max(200),
69	  /** budget notes from the game's AssetProfile (poly budget, texture res, formats, delivery) */
70	  notes: z.array(z.string().max(160)).max(6).default([]),
71	  /** what Cyrus must do before shipping it to this game (convert, downscale, transcode...) */
72	  transform: z.array(z.string().max(40)).max(6).default([]),
73	}).strict();
74	export type GameFit = z.infer<typeof GameFitZ>;
75	
76	const num = z.number().finite();
77	export const TechZ = z.object({
78	  format: z.string().max(32),
79	  bytes: z.number().int().min(0),
80	  // 3D
81	  triangles: z.number().int().min(0).nullable().optional(),
82	  vertices: z.number().int().min(0).nullable().optional(),
83	  meshes: z.number().int().min(0).nullable().optional(),
84	  materials: z.number().int().min(0).nullable().optional(),
85	  textures: z.number().int().min(0).nullable().optional(),
86	  /** axis-aligned size in glTF units (metres), [x, y, z] */
87	  bounds: z.tuple([num, num, num]).nullable().optional(),
88	  /** true when bounds look like real-world metres for the category (see vocab realWorldScale) */
89	  scaleOk: z.boolean().nullable().optional(),
90	  rigged: z.boolean().nullable().optional(),
91	  animations: z.number().int().min(0).nullable().optional(),
92	  // 2D / PBR / HDRI
93	  width: z.number().int().min(0).nullable().optional(),
94	  height: z.number().int().min(0).nullable().optional(),
95	  /** maps in a texture set (albedo, normal-gl, normal-dx, roughness, metallic, ao, height, opacity, emissive) */
96	  maps: z.array(z.string().max(16)).max(12).optional(),
97	  hasAlpha: z.boolean().nullable().optional(),
98	  tileable: z.boolean().nullable().optional(),
99	  /** physical size the texture covers (metres), when the source states it */
100	  physicalSizeM: z.number().positive().nullable().optional(),
101	  // audio
102	  durationS: z.number().min(0).nullable().optional(),
103	  sampleRate: z.number().int().min(0).nullable().optional(),
104	  channels: z.number().int().min(0).max(16).nullable().optional(),
105	  bitDepth: z.number().int().min(0).max(64).nullable().optional(),
106	  peakDb: num.nullable().optional(),
107	  truePeakDb: num.nullable().optional(),
108	  lufs: num.nullable().optional(),
109	  silenceRatio: z.number().min(0).max(1).nullable().optional(),
110	  /** HEURISTIC (start/end level match), never verified by ear */
111	  loopable: z.boolean().nullable().optional(),
112	  centroidHz: z.number().min(0).nullable().optional(),
113	  character: z.enum(["transient", "sustained"]).nullable().optional(),
114	}).strict();
115	export type Tech = z.infer<typeof TechZ>;
116	
117	export const LicenceZ = z.object({
118	  tier: z.enum(LICENCE_TIERS),
119	  /** SPDX id when one applies (CC0-1.0, CC-BY-4.0); null for proprietary / user-contributed */
120	  spdx: z.string().max(40).nullable(),
121	  sourceUrl: z.string().max(300).nullable(),
122	  /** required text for cc-by; null otherwise */
123	  attribution: z.string().max(300).nullable(),
124	  /** what the ledger has actually seen: "verified: licence page saved 2026-10-10", "unverified: owner to confirm" */
125	  status: z.string().max(200),
126	}).strict();
127	export type Licence = z.infer<typeof LicenceZ>;
128	
129	export const ProvenanceZ = z.object({
130	  source: z.string().max(40),
131	  pack: z.string().max(120).nullable(),
132	  /** path inside the staged/source library (never a customer path) */
133	  path: z.string().max(400).nullable(),
134	  retrievedAt: z.string().max(32).nullable(),
135	  /** upstream id / repo@sha the row came through */
136	  via: z.string().max(160).nullable(),
137	  /** content hashes this asset was derived from (a retexture lists its base) */
138	  derivedFrom: z.array(z.string().regex(SHA256_HEX)).max(16).default([]),
139	}).strict();
140	
141	export const CatalogEntryV1Z = z.object({
142	  schemaVersion: z.literal(CATALOG_SCHEMA_VERSION),
143	  /** sha256 of the asset bytes (a texture set / HDRI: of its primary file); also the dedupe key */
144	  id: z.string().regex(SHA256_HEX),
145	  kind: z.enum(CATALOG_KINDS),
146	  title: z.string().trim().min(2).max(80),
147	  shortDescription: z.string().trim().min(10).max(140),
148	  /** controlled vocabulary (vocab.json tags / styles / object words) */
149	  tags: z.array(tag).max(16),
150	  /** anything else that looked useful, max 8 */
151	  freeTags: z.array(tag).max(8).default([]),
152	  categories: z.object({ primary: cat, secondary: z.array(cat).max(3).default([]) }).strict(),
153	  /** situation ids from vocab.json useFor */
154	  useFor: z.array(z.string().regex(/^[a-z0-9-]{2,48}$/)).max(8).default([]),
155	  style: z.string().max(24).nullable(),
156	  quality: QualityZ,
157	  /** game id -> fit, only for games with an AssetProfile; missing game = unknown (never assumed good) */
158	  games: z.record(z.string().regex(GAME_RE), GameFitZ).default({}),
159	  tech: TechZ,
160	  licence: LicenceZ,
161	  provenance: ProvenanceZ,
162	  legalClass: z.enum(LEGAL_CLASSES),
163	  /** opaque contributor id (never an email or a Nxeon user id); null for packs */
164	  contributedBy: z.string().regex(/^[a-z0-9_-]{4,64}$/).nullable().default(null),
165	  status: z.enum(CATALOG_STATUSES),
166	  /** why the status is what it is (content-filter flags, owner note) */
167	  statusReason: z.string().max(300).nullable().default(null),
168	  /** content-filter flag ids (lib/cyrus/library/v2/filters.ts) */
169	  flags: z.array(z.string().max(48)).max(12).default([]),
170	  /** near-duplicate / variant group: same stem + sizes in other colours or numbering */
171	  group: z.string().max(120).nullable().default(null),
172	  /** sha256 of a better copy when this one is a near-duplicate */
173	  duplicateOf: z.string().regex(SHA256_HEX).nullable().default(null),
174	  thumbnail: z.string().max(400).nullable().default(null),
175	  enrichment: z.object({
176	    by: z.enum(ENRICHED_BY),
177	    /** 0-1: how sure the stage was that title/category/useFor are right */
178	    confidence: z.number().min(0).max(1),
179	    /** full = stage A described it well enough to pick; partial = category only; none = needs stage B */
180	    coverage: z.enum(["full", "partial", "none"]),
181	    /** stage-b model id, when stage B ran */
182	    model: z.string().max(60).nullable().default(null),
183	    at: z.string().max(32),
184	    /** what stage A could not decide (feeds the stage-B queue and the owner review) */
185	    gaps: z.array(z.string().max(80)).max(8).default([]),
186	  }).strict(),
187	}).strict();
188	
189	export type CatalogEntry = z.output<typeof CatalogEntryV1Z>;
190	export type CatalogEntryInput = z.input<typeof CatalogEntryV1Z>;
191	export type EntryIssue = { path: string; code: string; message: string };
192	
193	/** Structured validation (never throws) + cross-field rules. */
194	export function validateCatalogEntry(raw: unknown): { ok: true; entry: CatalogEntry } | { ok: false; errors: EntryIssue[] } {
195	  const r = CatalogEntryV1Z.safeParse(raw);
196	  if (!r.success) return { ok: false, errors: r.error.issues.map((i) => ({ path: i.path.join(".") || "entry", code: "invalid", message: i.message })) };
197	  const e = r.data;
198	  const errors: EntryIssue[] = [];
199	  const add = (path: string, code: string, message: string) => errors.push({ path, code, message });
200	  if (e.categories.secondary.includes(e.categories.primary)) add("categories.secondary", "duplicate_primary", "a secondary category repeats the primary");
201	  if (e.licence.tier === "cc-by" && !e.licence.attribution) add("licence.attribution", "attribution_required", "cc-by assets need their attribution text");
202	  if (e.licence.tier === "user-contributed" && !e.contributedBy) add("contributedBy", "contributor_required", "a user-contributed asset names its (opaque) contributor");
203	  if (e.licence.tier !== "user-contributed" && e.contributedBy) add("contributedBy", "contributor_only_for_user", "only user-contributed assets carry a contributor");
204	  if (e.legalClass === "game-derived" || e.legalClass === "third-party-licensed") add("legalClass", "not_library_class", `${e.legalClass} content never enters the catalog`);
205	  if (e.licence.tier === "user-contributed" && !["user-original", "ai-generated-for-user"].includes(e.legalClass)) add("legalClass", "contribution_class", "community contributions are user-original or ai-generated-for-user");
206	  if ((e.licence.tier === "cc0" || e.licence.tier === "cc-by" || e.licence.tier === "proprietary-nxeon") && e.legalClass !== "platform-library") add("legalClass", "library_class", "pack and Nxeon library assets are platform-library");
207	  if (e.status === "published" && e.flags.some((f) => f.startsWith("hold:"))) add("status", "published_with_hold", "an entry with a hold flag cannot be published");
208	  if (e.duplicateOf === e.id) add("duplicateOf", "self_duplicate", "an entry cannot duplicate itself");
209	  const audio = e.kind === "sound" || e.kind === "music";
210	  if (audio && e.tech.triangles != null) add("tech.triangles", "kind_mismatch", "audio has no triangles");
211	  return errors.length ? { ok: false, errors } : { ok: true, entry: e };
212	}
213	
214	/** JSON Schema (draft 2020-12) of CatalogEntry v1: the portable contract for the host's store and other tools. */
215	export function catalogEntryJsonSchema(): Record<string, unknown> {
216	  const s = z.toJSONSchema(CatalogEntryV1Z, { target: "draft-2020-12", io: "input" }) as Record<string, unknown>;
217	  return { $id: "https://nxeon.cloud/schemas/cyrus/catalog-entry.v1.json", title: "Cyrus CatalogEntry v1", ...s };
218	}
219	
220	/** The plan-gate kind (lib/cyrus/engine-core/asset-gate.ts) of a catalog kind: sounds follow the Sound Studio, everything visual the Texture Studio. */
221	export function gateKindOf(kind: CatalogKind): AssetKind {
222	  if (kind === "sound" || kind === "music") return "sound";
223	  if (kind === "model") return "model";
224	  return "texture";
225	}
226	/** The unified-library kind (lib/cyrus/library/types.ts) of a catalog kind. */
227	export const libraryKindOf = (kind: CatalogKind): LibraryKind => (kind === "sound" || kind === "music" ? "sound" : kind === "model" ? "model" : "texture");
228	// Catalog retrieval: a pluggable index (interface) + the in-memory implementation (pure; tests, single box, and
229	// the re-ranker every backend shares). ./sqlite-index.ts is the local FTS5 backend; a Postgres or vector backend
230	// later implements the same CatalogIndex.
231	//
232	// Ranking (one function, `rankHit`, used by every backend):
233	//   text   = sum over query words of (best field weight the word hits) x idf; fields: title 3.5, useFor ids 3, tags 2.5,
234	//            categories 2, free tags 1, description 1, situation labels 0.75. Query words go through BOTH taxonomies' synonym expansion
235	//            (lib/cyrus/library/search.ts expandTerm). A hit must match >= 50 % of the query words and is scaled by
236	//            (matched share)^2, so full matches win but "health potion" still finds potions.
237	//   rank   = textNorm x (0.6 + 0.4 x fitWeight) x (0.75 + 0.25 x quality/100)
238	//            fitWeight for the asked game: good 1, ok 0.6, unknown 0.35; fit "no" is EXCLUDED unless includeNoFit.
239	//   filters: status (default published only: held / removed / pending never reach a build), kind, licence tier
240	//            (by plan), minQuality, tags (all), category prefix, useFor; near-duplicates dropped; one row per
241	//            variant group (the best one, with the group size).
242	import { expandTerm, queryWords } from "../search";
243	import type { CatalogEntry, CatalogKind, CatalogStatus, LicenceTier } from "./entry";
244	import { canon, canonFor, CONTROLLED, useForLabel, words } from "./vocab";
245	
246	export type CatalogQuery = {
247	  text?: string;
248	  kinds?: readonly CatalogKind[];
249	  game?: string | null;
250	  minQuality?: number;
251	  tiers?: readonly LicenceTier[];
252	  tags?: readonly string[];
253	  useFor?: readonly string[];
254	  /** category id or a prefix ending in "/" */
255	  category?: string;
256	  statuses?: readonly CatalogStatus[];
257	  includeNoFit?: boolean;
258	  collapseGroups?: boolean;
259	  limit?: number;
260	  offset?: number;
261	};
262	export type CatalogHit = { entry: CatalogEntry; rank: number; text: number; groupSize: number };
263	export type CatalogSearchResult = { total: number; hits: CatalogHit[]; expanded: string[][] };
264	
265	export interface CatalogIndex {
266	  upsert(entries: readonly CatalogEntry[]): Promise<void>;
267	  remove(ids: readonly string[]): Promise<void>;
268	  /** full id or a unique hex prefix (>= 8 chars); null when unknown or ambiguous */
269	  get(idOrPrefix: string): Promise<CatalogEntry | null>;
270	  search(q: CatalogQuery): Promise<CatalogSearchResult>;
271	  /** the shortest unique id prefix (>= 12 hex) for a model-facing id */
272	  shortId(id: string): Promise<string>;
273	  size(): Promise<number>;
274	}
275	
276	export const FIELD_WEIGHTS = { title: 3.5, useFor: 3, tags: 2.5, categories: 2, freeTags: 1, description: 1, situation: 0.75 } as const;
277	type Field = keyof typeof FIELD_WEIGHTS;
278	export const FIT_WEIGHT = { good: 1, ok: 0.6, unknown: 0.35 } as const;
279	export const MIN_WORD_SHARE = 0.5;
280	/** words that only name the KIND of asset, not its content ("prop", "sound") */
281	const KIND_WORDS: Record<string, CatalogKind[]> = {
282	  sound: ["sound"], sounds: ["sound"], sfx: ["sound"], audio: ["sound", "music"], music: ["music"], song: ["music"],
283	  model: ["model"], mesh: ["model"], prop: ["model"], props: ["model"], "3d": ["model"],
284	  texture: ["texture-set", "texture"], material: ["texture-set"], pbr: ["texture-set"], hdri: ["hdri"], skybox: ["hdri"], sprite: ["sprite"], icon: ["sprite"], decal: ["decal"],
285	};
286	
287	export function docFields(e: CatalogEntry): Record<Field, string[]> {
288	  const cn = canonFor(e.kind === "sound" || e.kind === "music" ? "audio" : "visual");
289	  const w = (s: string) => words(s).map(cn);
290	  return {
291	    title: w(e.title),
292	    useFor: e.useFor.flatMap((u) => [u, ...w(u)]),
293	    tags: e.tags.flatMap((t) => [t, ...w(t)]),
294	    categories: [e.categories.primary, ...e.categories.secondary].flatMap((c) => [c, ...w(c)]),
295	    freeTags: e.freeTags.flatMap((t) => [t, ...w(t)]),
296	    // a stage-A description ends with "; for <situation label>. From <pack>." -- those words are not about the asset
297	    description: w(e.enrichment.by === "stage-a" ? e.shortDescription.replace(/; for .*$|\. From .*$/, "") : e.shortDescription),
298	    // the situation LABELS ("lamp / torch / light-source prop") list examples, not what this asset is: low weight
299	    situation: e.useFor.flatMap((u) => w(useForLabel(u))),
300	  };
301	}
302	
303	export type ParsedQuery = { terms: string[][]; kindHints: CatalogKind[] };
304	/** Kinds to search: the caller's allowed kinds, narrowed by kind words in the query ("... sound") when they overlap. */
305	export function effectiveKinds(allowed: readonly CatalogKind[] | undefined, hints: readonly CatalogKind[]): readonly CatalogKind[] | undefined {
306	  if (!hints.length) return allowed?.length ? allowed : undefined;
307	  if (!allowed?.length) return hints;
308	  const both = allowed.filter((k) => hints.includes(k));
309	  return both.length ? both : allowed;
310	}
311	
312	/** hyphenated controlled tags ("sci-fi", "low-poly", "pixel-art"): written "sci fi", "sci-fi" or "scifi", one query term */
313	const COMPOUNDS = [...CONTROLLED].filter((t) => t.includes("-")).map((t) => ({ t, re: new RegExp(`\\b${t.split("-").join("[-\\s]?")}\\b`, "g"), joined: t.replace(/-/g, "") }));
314	const JOINED = new Map(COMPOUNDS.map((c) => [c.joined, c.t]));
315	
316	export function parseQuery(text: string): ParsedQuery {
317	  const kindHints = new Set<CatalogKind>();
318	  const terms: string[][] = [];
319	  for (const c of COMPOUNDS) text = text.toLowerCase().replace(c.re, c.joined);
320	  // kind words are read before stop-word removal ("texture" is a texture-taxonomy stop word)
321	  for (const raw of text.toLowerCase().split(/[^a-z0-9]+/)) { const k = KIND_WORDS[canon(raw)]; if (k) for (const x of k) kindHints.add(x); }
322	  for (const raw of queryWords(text)) {
323	    const w = JOINED.get(raw) ?? canon(raw);
324	    if (KIND_WORDS[w]) { for (const k of KIND_WORDS[w]) kindHints.add(k); continue; }
325	    terms.push([...new Set([w, raw, ...expandTerm(w)])]);
326	  }
327	  return { terms, kindHints: [...kindHints] };
328	}
329	
330	export function passesFilters(e: CatalogEntry, q: CatalogQuery): boolean {
331	  const statuses = q.statuses ?? ["published"];
332	  if (!statuses.includes(e.status)) return false;
333	  if (e.duplicateOf) return false;
334	  if (q.kinds?.length && !q.kinds.includes(e.kind)) return false;
335	  if (q.tiers && !q.tiers.includes(e.licence.tier)) return false;
336	  if (q.minQuality != null && e.quality.score < q.minQuality) return false;
337	  if (q.tags?.length && !q.tags.every((t) => e.tags.includes(t) || e.freeTags.includes(t))) return false;
338	  if (q.useFor?.length && !q.useFor.some((u) => e.useFor.includes(u))) return false;
339	  if (q.category) {
340	    const cats = [e.categories.primary, ...e.categories.secondary];
341	    if (!cats.some((c) => (q.category!.endsWith("/") ? c.startsWith(q.category!) : c === q.category))) return false;
342	  }
343	  if (q.game && !q.includeNoFit && e.games[q.game]?.fit === "no") return false;
344	  return true;
345	}
346	
347	export function fitWeight(e: CatalogEntry, game: string | null | undefined): number {
348	  if (!game) return 1;
349	  const f = e.games[game]?.fit;
350	  return f === "good" ? FIT_WEIGHT.good : f === "ok" ? FIT_WEIGHT.ok : f === "no" ? 0 : FIT_WEIGHT.unknown;
351	}
352	export const rankHit = (textNorm: number, e: CatalogEntry, game: string | null | undefined) => textNorm * (0.6 + 0.4 * fitWeight(e, game)) * (0.75 + 0.25 * (e.quality.score / 100));
353	
354	export type FieldSets = Record<Field, Set<string>>;
355	export const fieldSets = (f: Record<Field, string[]>): FieldSets => Object.fromEntries(Object.entries(f).map(([k, v]) => [k, new Set(v)])) as FieldSets;
356	/** Text score of one entry: per query word the best field weight it hits (synonyms count), x idf. 0 = too few words matched. */
357	export function textScore(sets: FieldSets, terms: string[][], idf: (t: string) => number): number {
358	  if (!terms.length) return 1;
359	  let score = 0, hit = 0;
360	  for (const alts of terms) {
361	    let best = 0, bestTerm = alts[0];
362	    for (const [f, wgt] of Object.entries(FIELD_WEIGHTS) as [Field, number][]) {
363	      for (const t of alts) if (sets[f].has(t)) { const v = t === alts[0] ? wgt : wgt * 0.85; if (v > best) { best = v; bestTerm = t; } }
364	    }
365	    // idf of the word the user typed, not of the synonym that matched (a rare synonym must not outrank the word itself)
366	    if (best) { hit++; score += best * idf(alts[0]); void bestTerm; }
367	  }
368	  const share = hit / terms.length;
369	  return share >= MIN_WORD_SHARE ? score * share * share : 0;
370	}
371	
372	/** Group collapse + pagination over already-ranked hits (shared by every backend). */
373	export function finish(hits: CatalogHit[], q: CatalogQuery): CatalogHit[] {
374	  hits.sort((a, b) => b.rank - a.rank || b.entry.quality.score - a.entry.quality.score || (a.entry.id < b.entry.id ? -1 : 1));
375	  let out = hits;
376	  if (q.collapseGroups !== false) {
377	    const seen = new Map<string, CatalogHit>();
378	    out = [];
379	    for (const h of hits) {
380	      const g = h.entry.group;
381	      if (!g) { out.push(h); continue; }
382	      const first = seen.get(g);
383	      if (first) { first.groupSize++; continue; }
384	      seen.set(g, h); out.push(h);
385	    }
386	  }
387	  const off = Math.max(0, Math.floor(q.offset ?? 0)), lim = Math.min(50, Math.max(1, Math.floor(q.limit ?? 8)));
388	  return out.slice(off, off + lim);
389	}
390	
391	export function createMemoryCatalogIndex(initial: readonly CatalogEntry[] = []): CatalogIndex {
392	  const docs = new Map<string, { e: CatalogEntry; f: FieldSets }>();
393	  const df = new Map<string, number>();
394	  const bump = (f: FieldSets, d: number) => { const all = new Set<string>(); for (const s of Object.values(f)) for (const t of s) all.add(t); for (const t of all) df.set(t, (df.get(t) ?? 0) + d); };
395	  const put = (e: CatalogEntry) => { const old = docs.get(e.id); if (old) bump(old.f, -1); const f = fieldSets(docFields(e)); docs.set(e.id, { e, f }); bump(f, 1); };
396	  for (const e of initial) put(e);
397	  const idf = (t: string) => Math.log(1 + (docs.size + 1) / ((df.get(t) ?? 0) + 0.5));
398	  const byPrefix = (p: string) => { const out: CatalogEntry[] = []; for (const [id, d] of docs) if (id.startsWith(p)) { out.push(d.e); if (out.length > 1) break; } return out; };
399	  return {
400	    async upsert(es) { for (const e of es) put(e); },
401	    async remove(ids) { for (const id of ids) { const d = docs.get(id); if (d) { bump(d.f, -1); docs.delete(id); } } },
402	    async get(idOrPrefix) {
403	      const p = idOrPrefix.replace(/^(cat:|c:)/, "").toLowerCase();
404	      if (!/^[0-9a-f]{8,64}$/.test(p)) return null;
405	      if (p.length === 64) return docs.get(p)?.e ?? null;
406	      const m = byPrefix(p);
407	      return m.length === 1 ? m[0] : null;
408	    },
409	    async shortId(id) {
410	      for (let n = 12; n < 64; n += 2) if (byPrefix(id.slice(0, n)).length <= 1) return id.slice(0, n);
411	      return id;
412	    },
413	    async size() { return docs.size; },
414	    async search(q) {
415	      const parsed = parseQuery(q.text ?? "");
416	      const kinds = effectiveKinds(q.kinds, parsed.kindHints);
417	      const qq: CatalogQuery = { ...q, kinds };
418	      const hits: CatalogHit[] = [];
419	      let max = 0;
420	      const raw: { e: CatalogEntry; t: number }[] = [];
421	      for (const { e, f } of docs.values()) {
422	        if (!passesFilters(e, qq)) continue;
423	        const t = textScore(f, parsed.terms, idf);
424	        if (t <= 0) continue;
425	        raw.push({ e, t }); if (t > max) max = t;
426	      }
427	      for (const { e, t } of raw) { const n = max ? t / max : 1; hits.push({ entry: e, text: n, rank: rankHit(n, e, q.game), groupSize: 1 }); }
428	      const total = hits.length;
429	      return { total, hits: finish(hits, qq), expanded: parsed.terms };
430	    },
431	  };
432	}
433	// Local FTS5 backend of CatalogIndex (SERVER-ONLY: node:sqlite, Node >= 22.13; node-2 runs Node 24). One file or
434	// ":memory:" database, no extension, no network. FTS5 (porter + unicode61) retrieves candidates with weighted bm25
435	// over the same fields as the memory index; filters run in SQL; the final order uses the shared rankHit() so every
436	// backend ranks the same way. Entries are stored as JSON next to the FTS row (the catalog store of record is the
437	// host's DB; this file is a rebuildable search cache).
438	import type { CatalogEntry } from "./entry";
439	import { docFields, effectiveKinds, finish, parseQuery, passesFilters, rankHit, FIELD_WEIGHTS, MIN_WORD_SHARE, type CatalogHit, type CatalogIndex, type CatalogQuery } from "./retrieval";
440	
441	type Stmt = { run: (...a: unknown[]) => unknown; all: (...a: unknown[]) => unknown[]; get: (...a: unknown[]) => unknown };
442	type Db = { exec: (sql: string) => void; prepare: (sql: string) => Stmt; close: () => void };
443	
444	const CANDIDATES = 600;
445	const FTS_CANDIDATES = 4000;
446	const ftsQuote = (t: string) => `"${t.replace(/"/g, "")}"`;
447	
448	export async function createSqliteCatalogIndex(file = ":memory:"): Promise<CatalogIndex & { close(): void }> {
449	  const spec = "node:sqlite"; // a variable specifier: bundlers never pull it into client code, tsc needs no node:sqlite types
450	  const mod = (await import(/* webpackIgnore: true */ spec)) as unknown as { DatabaseSync: new (f: string) => Db };
451	  const db = new mod.DatabaseSync(file);
452	  db.exec(`
453	    CREATE TABLE IF NOT EXISTS entry (rid INTEGER PRIMARY KEY, id TEXT NOT NULL UNIQUE, kind TEXT, status TEXT, tier TEXT, quality INTEGER, dup TEXT, json TEXT NOT NULL);
454	    CREATE INDEX IF NOT EXISTS entry_kind ON entry(kind, status, tier, quality);
455	    CREATE VIRTUAL TABLE IF NOT EXISTS entry_fts USING fts5(title, usefor, tags, cats, free, descr, situ, tokenize='porter unicode61');
456	  `);
457	  // FTS rows share the entry's integer rowid, so a re-upsert deletes by rowid (an UNINDEXED id column would make
458	  // every delete a full scan: 54k upserts took 433 s that way, measured).
459	  const findRid = db.prepare("SELECT rid FROM entry WHERE id = ?");
460	  const insEntry = db.prepare("INSERT INTO entry (id, kind, status, tier, quality, dup, json) VALUES (?, ?, ?, ?, ?, ?, ?) RETURNING rid");
461	  const updEntry = db.prepare("UPDATE entry SET kind = ?, status = ?, tier = ?, quality = ?, dup = ?, json = ? WHERE rid = ?");
462	  const delFts = db.prepare("DELETE FROM entry_fts WHERE rowid = ?");
463	  const insFts = db.prepare("INSERT INTO entry_fts (rowid, title, usefor, tags, cats, free, descr, situ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)");
464	  const del = db.prepare("DELETE FROM entry WHERE rid = ?");
465	  const getOne = db.prepare("SELECT json FROM entry WHERE id = ?");
466	  const prefix = db.prepare("SELECT id, json FROM entry WHERE id >= ? AND id < ? LIMIT 2");
467	  const count = db.prepare("SELECT COUNT(*) AS n FROM entry");
468	  const w = FIELD_WEIGHTS;
469	  const bm = `bm25(entry_fts, ${w.title}, ${w.useFor}, ${w.tags}, ${w.categories}, ${w.freeTags}, ${w.description}, ${w.situation})`;
470	  const upper = (p: string) => p + "g"; // hex prefix range end ("g" sorts after every hex digit)
471	  const parse = (j: unknown) => JSON.parse(String((j as { json: string }).json)) as CatalogEntry;
472	
473	  const api: CatalogIndex & { close(): void } = {
474	    async upsert(es) {
475	      db.exec("BEGIN");
476	      try {
477	        for (const e of es) {
478	          const old = findRid.get(e.id) as { rid: number } | undefined;
479	          let rid: number;
480	          if (old) { rid = Number(old.rid); updEntry.run(e.kind, e.status, e.licence.tier, e.quality.score, e.duplicateOf, JSON.stringify(e), rid); delFts.run(rid); }
481	          else rid = Number((insEntry.get(e.id, e.kind, e.status, e.licence.tier, e.quality.score, e.duplicateOf, JSON.stringify(e)) as { rid: number }).rid);
482	          const f = docFields(e);
483	          insFts.run(rid, f.title.join(" "), f.useFor.join(" "), f.tags.join(" "), f.categories.join(" "), f.freeTags.join(" "), f.description.join(" "), f.situation.join(" "));
484	        }
485	        db.exec("COMMIT");
486	      } catch (err) { db.exec("ROLLBACK"); throw err; }
487	    },
488	    async remove(ids) { for (const id of ids) { const r = findRid.get(id) as { rid: number } | undefined; if (r) { del.run(r.rid); delFts.run(r.rid); } } },
489	    async get(idOrPrefix) {
490	      const p = idOrPrefix.replace(/^(cat:|c:)/, "").toLowerCase();
491	      if (!/^[0-9a-f]{8,64}$/.test(p)) return null;
492	      if (p.length === 64) { const r = getOne.get(p); return r ? parse(r) : null; }
493	      const rows = prefix.all(p, upper(p));
494	      return rows.length === 1 ? parse(rows[0]) : null;
495	    },
496	    async shortId(id) {
497	      for (let n = 12; n < 64; n += 2) if (prefix.all(id.slice(0, n), upper(id.slice(0, n))).length <= 1) return id.slice(0, n);
498	      return id;
499	    },
500	    async size() { return Number((count.get() as { n: number }).n); },
501	    async search(q: CatalogQuery) {
502	      const parsed = parseQuery(q.text ?? "");
503	      const kinds = effectiveKinds(q.kinds, parsed.kindHints);
504	      const qq: CatalogQuery = { ...q, kinds };
505	      const statuses = qq.statuses ?? ["published"];
506	      const where: string[] = [`e.status IN (${statuses.map(() => "?").join(",")})`, "e.dup IS NULL"];
507	      const args: unknown[] = [...statuses];
508	      if (kinds?.length) { where.push(`e.kind IN (${kinds.map(() => "?").join(",")})`); args.push(...kinds); }
509	      if (qq.tiers) { where.push(`e.tier IN (${qq.tiers.map(() => "?").join(",") || "''"})`); args.push(...qq.tiers); }
510	      if (qq.minQuality != null) { where.push("e.quality >= ?"); args.push(qq.minQuality); }
511	      let rows: { json: string; s: number }[] = [];
512	      if (parsed.terms.length) {
513	        // step 1: FTS alone (fast), step 2: fetch + SQL-filter the candidates by rowid (keeps the planner from
514	        // scanning entry first and running MATCH per row: that took 2-40 s per query at 54k rows, measured)
515	        const match = parsed.terms.map((alts) => `(${alts.map(ftsQuote).join(" OR ")})`).join(" OR ");
516	        const cands = db.prepare(`SELECT rowid AS rid, ${bm} AS s FROM entry_fts WHERE entry_fts MATCH ? ORDER BY s LIMIT ${FTS_CANDIDATES}`).all(match) as { rid: number; s: number }[];
517	        const score = new Map(cands.map((c) => [Number(c.rid), c.s]));
518	        for (let i = 0; i < cands.length; i += 400) {
519	          const chunk = cands.slice(i, i + 400).map((c) => Number(c.rid));
520	          const got = db.prepare(`SELECT e.rid AS rid, e.json AS json FROM entry e WHERE e.rid IN (${chunk.map(() => "?").join(",")}) AND ${where.join(" AND ")}`).all(...chunk, ...args) as { rid: number; json: string }[];
521	          for (const g of got) rows.push({ json: g.json, s: score.get(Number(g.rid)) ?? 0 });
522	        }
523	        rows.sort((a, b) => a.s - b.s);
524	        rows = rows.slice(0, CANDIDATES);
525	      } else {
526	        rows = db.prepare(`SELECT e.json AS json, 0 AS s FROM entry e WHERE ${where.join(" AND ")} ORDER BY e.quality DESC LIMIT ${CANDIDATES}`).all(...args) as { json: string; s: number }[];
527	      }
528	      // bm25 is negative-better; require the same word share as the memory index (FTS OR-matching is wider)
529	      const hits: CatalogHit[] = [];
530	      let best = 0;
531	      const cand: { e: CatalogEntry; t: number }[] = [];
532	      for (const r of rows) {
533	        const e = JSON.parse(r.json) as CatalogEntry;
534	        if (!passesFilters(e, qq)) continue;
535	        if (parsed.terms.length) {
536	          const f = docFields(e);
537	          const all = new Set(Object.values(f).flat());
538	          const share = parsed.terms.filter((alts) => alts.some((t) => all.has(t))).length / parsed.terms.length;
539	          if (share < MIN_WORD_SHARE) continue;
540	          const t = -r.s * share * share;
541	          cand.push({ e, t }); if (t > best) best = t;
542	        } else cand.push({ e, t: 1 });
543	      }
544	      for (const { e, t } of cand) { const n = best ? Math.max(0, t / best) : 1; hits.push({ entry: e, text: n, rank: rankHit(n, e, q.game), groupSize: 1 }); }
545	      return { total: hits.length, hits: finish(hits, qq), expanded: parsed.terms };
546	    },
547	    close() { db.close(); },
548	  };
549	  return api;
550	}
