1	// The MODEL-FACING tool contract of the catalog, for the build service (Claude picks assets by calling these):
2	//   catalog_search(query, kind?, game?, minQuality?, limit<=8) -> compact rows, hard-capped at ~1k tokens
3	//   catalog_get(id)                                            -> one entry's detail (~250-400 tokens) + its `ref`
4	// A picked asset goes into a ModSpec asset slot as { source: "library", libraryRef: "cat:<sha256>" }
5	// (lib/cyrus/engine-core/spec.ts); resolveLibrarySlot() is what the build service runs on every such slot.
6	// Gates (server-side, every call): the plan-tier asset gate (lib/cyrus/engine-core/asset-gate.ts canAsset(plan,
7	// kind, "create"): picking from a library creates content), the licence tiers the plan may use (PLAN_TIERS, owner
8	// decision), the proprietary-library clearance flag (same fail-closed rule as CYRUS_SOUND_LIBRARY_CLEARED), and
9	// status = published. HOST SEAM: the host passes plan + flags in ToolContext; nothing here reads Nxeon state.
10	import { canAsset, normalizePlan, type AssetPlan } from "../../engine-core/asset-gate";
11	import type { AssetSlot } from "../../engine-core/spec";
12	import { CATALOG_KINDS, CATALOG_REF_RE, catalogRef, gateKindOf, type CatalogEntry, type CatalogKind, type LicenceTier } from "./entry";
13	import type { CatalogIndex } from "./retrieval";
14	import { useForLabel } from "./vocab";
15	
16	export const SEARCH_LIMIT_MAX = 8;
17	/** hard ceiling for one tool result; ~4 chars per token for this JSON => ~1k tokens (measured: see test) */
18	export const RESULT_CHAR_BUDGET = 3800;
19	
20	/**
21	 * Licence tiers each plan may pick from (OWNER DECISION, defaults below). proprietary-nxeon additionally needs the
22	 * host's clearance flag, because the owner's bought libraries forbid redistribution and must be transformed.
23	 */
24	export const PLAN_TIERS: Readonly<Record<AssetPlan, readonly LicenceTier[]>> = {
25	  free: [], katara: [],
26	  saka: ["cc0", "cc-by", "user-contributed", "proprietary-nxeon"],
27	  all: ["cc0", "cc-by", "user-contributed", "proprietary-nxeon"],
28	};
29	
30	export type ToolContext = {
31	  index: CatalogIndex;
32	  /** raw plan from the host (any spelling asset-gate understands); unknown -> fail closed */
33	  plan: unknown;
34	  /** the project's game (default for `game`) */
35	  game: string | null;
36	  /** host flag: the owner cleared the proprietary library for customer builds */
37	  proprietaryCleared: boolean;
38	};
39	
40	export const CATALOG_TOOLS = [
41	  {
42	    name: "catalog_search",
43	    description: "Search Nxeon's asset catalog (3D models, PBR textures, sprites, HDRIs, decals, sounds, music) for an asset to use in this mod. Describe the situation, not a file name: e.g. 'weapon pickup sound', 'sci-fi crate prop', 'stone wall floor texture'. Results are ranked by fit for the game, quality and relevance; only assets your plan can use are returned. Use catalog_get on a result before putting it into an asset slot.",
44	    input_schema: {
45	      type: "object",
46	      additionalProperties: false,
47	      required: ["query"],
48	      properties: {
49	        query: { type: "string", minLength: 2, maxLength: 120, description: "what the asset is for, in plain words" },
50	        kind: { type: "string", enum: [...CATALOG_KINDS], description: "optional asset kind" },
51	        game: { type: "string", description: "game id; defaults to the project's game" },
52	        minQuality: { type: "integer", minimum: 0, maximum: 100, description: "minimum quality score (default 40)" },
53	        limit: { type: "integer", minimum: 1, maximum: SEARCH_LIMIT_MAX, description: "rows to return (default 6, max 8)" },
54	      },
55	    },
56	  },
57	  {
58	    name: "catalog_get",
59	    description: "Get one catalog asset by the id catalog_search returned: technical facts, game fit with budget notes, licence and the `ref` to put in a ModSpec asset slot as { source: \"library\", libraryRef: ref }.",
60	    input_schema: {
61	      type: "object",
62	      additionalProperties: false,
63	      required: ["id"],
64	      properties: { id: { type: "string", pattern: "^(c:|cat:)?[0-9a-f]{12,64}$", description: "id from catalog_search" } },
65	    },
66	  },
67	] as const;
68	
69	export type ToolResult = { ok: boolean; content: string; chars: number };
70	const out = (ok: boolean, body: unknown): ToolResult => { const content = JSON.stringify(body); return { ok, content, chars: content.length }; };
71	
72	/** Kinds this plan may use + the tiers it may pick from (both empty = nothing). */
73	export function access(plan: unknown, proprietaryCleared: boolean): { kinds: CatalogKind[]; tiers: LicenceTier[]; plan: AssetPlan | null } {
74	  const p = normalizePlan(plan);
75	  if (!p) return { kinds: [], tiers: [], plan: null };
76	  const kinds = CATALOG_KINDS.filter((k) => canAsset(p, gateKindOf(k), "create").ok);
77	  const tiers = PLAN_TIERS[p].filter((t) => t !== "proprietary-nxeon" || proprietaryCleared);
78	  return { kinds, tiers: [...tiers], plan: p };
79	}
80	
81	const keyFact = (e: CatalogEntry): Record<string, number> => {
82	  const t = e.tech;
83	  if (e.kind === "model" && t.triangles != null) return { tris: t.triangles };
84	  if ((e.kind === "sound" || e.kind === "music") && t.durationS != null) return { sec: Math.round(t.durationS * 10) / 10 };
85	  if (t.width) return { px: t.width };
86	  return {};
87	};
