89	/** One compact search row (~45-70 tokens). */
90	export async function compactRow(e: CatalogEntry, game: string | null, index: CatalogIndex, groupSize = 1): Promise<Record<string, unknown>> {
91	  const fit = game ? e.games[game]?.fit ?? "unknown" : undefined;
92	  return {
93	    id: `c:${await index.shortId(e.id)}`, t: e.title, d: e.shortDescription, k: e.kind,
94	    tags: e.tags.filter((x) => x !== e.style).slice(0, 5), ...(fit ? { fit } : {}), q: e.quality.score, ...keyFact(e),
95	    ...(groupSize > 1 ? { variants: groupSize } : {}),
96	  };
97	}
98	
99	export async function catalogSearch(input: { query?: unknown; kind?: unknown; game?: unknown; minQuality?: unknown; limit?: unknown }, ctx: ToolContext): Promise<ToolResult> {
100	  const query = typeof input.query === "string" ? input.query.trim().slice(0, 120) : "";
101	  if (query.length < 2) return out(false, { error: "query must be 2-120 characters" });
102	  const a = access(ctx.plan, ctx.proprietaryCleared);
103	  if (!a.plan) return out(false, { error: "plan_unknown: assets cannot be picked right now" });
104	  let kinds = a.kinds;
105	  if (input.kind != null) {
106	    if (!(CATALOG_KINDS as readonly unknown[]).includes(input.kind)) return out(false, { error: `unknown kind; use one of ${CATALOG_KINDS.join(", ")}` });
107	    const k = input.kind as CatalogKind;
108	    if (!kinds.includes(k)) { const d = canAsset(a.plan, gateKindOf(k), "create"); return out(false, { error: "asset_locked", needs: d.ok ? null : d.needs ?? null }); }
109	    kinds = [k];
110	  }
111	  if (!kinds.length || !a.tiers.length) return out(false, { error: "asset_locked: this plan cannot use library assets" });
112	  const game = typeof input.game === "string" && /^[a-z][a-z0-9-]{1,31}$/.test(input.game) ? input.game : ctx.game;
113	  const minQuality = Number.isInteger(input.minQuality) ? Math.max(0, Math.min(100, input.minQuality as number)) : 40;
114	  const limit = Number.isInteger(input.limit) ? Math.max(1, Math.min(SEARCH_LIMIT_MAX, input.limit as number)) : 6;
115	  const r = await ctx.index.search({ text: query, kinds, game, minQuality, tiers: a.tiers, limit: limit * 2, statuses: ["published"] });
116	  // one row per (kind, title): identical-looking assets (same name in two packs, HDRI resolutions) count as variants
117	  const rows: Record<string, unknown>[] = [];
118	  const seenTitle = new Map<string, Record<string, unknown>>();
119	  for (const h of r.hits) {
120	    const k = `${h.entry.kind}|${h.entry.title.toLowerCase()}`;
121	    const prev = seenTitle.get(k);
122	    if (prev) { prev.variants = (Number(prev.variants) || 1) + h.groupSize; continue; }
123	    const row = await compactRow(h.entry, game, ctx.index, h.groupSize);
124	    seenTitle.set(k, row); rows.push(row);
125	  }
126	  // hard budget: drop descriptions, then rows, until the result fits
127	  let body: Record<string, unknown> = { n: r.total, game, rows: rows.slice(0, limit) };
128	  if (JSON.stringify(body).length > RESULT_CHAR_BUDGET) body = { ...body, rows: rows.slice(0, limit).map(({ d: _d, ...x }) => x) };
129	  while (JSON.stringify(body).length > RESULT_CHAR_BUDGET && (body.rows as unknown[]).length > 1) body = { ...body, rows: (body.rows as unknown[]).slice(0, -1) };
130	  if (!rows.length) body.hint = "no match: try other words for the situation, another kind, or a lower minQuality";
131	  return out(true, body);
132	}
