134	export async function catalogGet(input: { id?: unknown }, ctx: ToolContext): Promise<ToolResult> {
135	  const id = typeof input.id === "string" ? input.id : "";
136	  const e = await ctx.index.get(id);
137	  const a = access(ctx.plan, ctx.proprietaryCleared);
138	  // an entry the caller may not use is reported as not found (no metadata leak across gates)
139	  if (!e || e.status !== "published" || !a.kinds.includes(e.kind) || !a.tiers.includes(e.licence.tier)) return out(false, { error: "not_found" });
140	  const t = e.tech;
141	  const tech = Object.fromEntries(Object.entries({
142	    format: t.format, tris: t.triangles, bounds_m: t.bounds, rigged: t.rigged, anims: t.animations, materials: t.materials,
143	    px: t.width && t.height ? `${t.width}x${t.height}` : null, maps: t.maps, tileable: t.tileable, sec: t.durationS, hz: t.sampleRate, ch: t.channels, lufs: t.lufs, loop: t.loopable,
144	  }).filter(([, v]) => v != null && !(Array.isArray(v) && !v.length)));
145	  const fit = ctx.game ? e.games[ctx.game] ?? null : null;
146	  return out(true, {
147	    ref: catalogRef(e.id), t: e.title, d: e.shortDescription, k: e.kind, cat: e.categories.primary, style: e.style,
148	    tags: e.tags.slice(0, 10), useFor: e.useFor.map(useForLabel).slice(0, 4), q: e.quality.score,
149	    fails: e.quality.checks.filter((c) => c.status === "fail").map((c) => c.id),
150	    ...(fit ? { fit: { game: ctx.game, fit: fit.fit, why: fit.reason, notes: fit.notes, transform: fit.transform } } : { fit: { game: ctx.game, fit: "unknown" } }),
151	    tech, licence: { tier: e.licence.tier, spdx: e.licence.spdx, attribution: e.licence.attribution },
152	    ...(e.licence.tier === "proprietary-nxeon" ? { rule: "proprietary library: ship transformed (pitch/edit), never the original file" } : {}),
153	  });
154	}
