156	export async function handleCatalogTool(name: string, input: unknown, ctx: ToolContext): Promise<ToolResult> {
157	  const i = (input && typeof input === "object" ? input : {}) as Record<string, unknown>;
158	  if (name === "catalog_search") return catalogSearch(i, ctx);
159	  if (name === "catalog_get") return catalogGet(i, ctx);
160	  return out(false, { error: `unknown tool ${name}` });
161	}
