163	export type SlotDecision = { ok: true; entry: CatalogEntry; transform: string[] } | { ok: false; code: "not_library" | "bad_ref" | "not_found" | "not_published" | "kind_mismatch" | "asset_locked" | "tier_locked" | "no_fit"; reason: string };
