165	/** What the build service runs for a ModSpec asset slot with source "library" (after gateSpecAssets). */
166	export async function resolveLibrarySlot(slot: Pick<AssetSlot, "id" | "kind" | "source"> & { libraryRef?: string }, ctx: ToolContext): Promise<SlotDecision> {
167	  if (slot.source !== "library") return { ok: false, code: "not_library", reason: `slot ${slot.id} is not a library slot` };
168	  if (!slot.libraryRef || !CATALOG_REF_RE.test(slot.libraryRef)) return { ok: false, code: "bad_ref", reason: `slot ${slot.id} needs libraryRef cat:<sha256>` };
169	  const e = await ctx.index.get(slot.libraryRef.slice(4));
170	  if (!e) return { ok: false, code: "not_found", reason: `${slot.libraryRef} is not in the catalog` };
171	  if (e.status !== "published") return { ok: false, code: "not_published", reason: `${slot.libraryRef} is ${e.status}` };
172	  const want = gateKindOf(e.kind);
173	  if (!(want === slot.kind || (slot.kind === "ui" && want === "texture"))) return { ok: false, code: "kind_mismatch", reason: `slot ${slot.id} is ${slot.kind}, the asset is a ${e.kind}` };
174	  const d = canAsset(ctx.plan, slot.kind, "create");
175	  if (!d.ok) return { ok: false, code: "asset_locked", reason: d.reason };
176	  const a = access(ctx.plan, ctx.proprietaryCleared);
177	  if (!a.tiers.includes(e.licence.tier)) return { ok: false, code: "tier_locked", reason: `${e.licence.tier} assets are not available on this plan${e.licence.tier === "proprietary-nxeon" && !ctx.proprietaryCleared ? " (library not cleared)" : ""}` };
178	  const fit = ctx.game ? e.games[ctx.game] : undefined;
179	  if (fit?.fit === "no") return { ok: false, code: "no_fit", reason: fit.reason };
180	  return { ok: true, entry: e, transform: fit?.transform ?? [] };
181	}
182	// Content-filter hooks for the AUTOMATIC community library (owner decision 2026-10-10: assets made in Cyrus are
183	// contributed automatically). A new entry is `pending-checks`; runContentFilters() moves it to `published` or
184	// `held` (or `removed` on a reject), never straight from held to published (only the owner does that).
185	// The interface is async so a host can plug in an image/audio classifier later; the shipped ruleset is
186	// deterministic, local and free (filter-rules.json): real-weapon model names, a trademark STUB list, adult terms,
187	// extremist symbols, mature violence (flag only), plus structural rules (eligibility of the legal class).
188	// No external service is called. Pure apart from what an injected filter does.
189	import rules from "./filter-rules.json";
190	import { libraryEligible } from "../../assets3d/manifest";
191	import type { CatalogEntry, CatalogStatus } from "./entry";
192	import { words } from "./vocab";
193	
194	export type FilterSeverity = "flag" | "hold" | "reject";
195	export type FilterFlag = { rule: string; severity: FilterSeverity; field: string; match: string; message: string };
196	export type FilterContext = {
197	  /** community contributions are checked strictly; Nxeon's own / CC0 pack assets only get flags */
198	  strict: boolean;
199	  /** derivedFrom of the source manifest (libraryEligible needs it); [] for packs */
200	  derivedFrom?: readonly string[];
201	  provenanceSource?: "user" | "ai" | "library" | "import" | "upload" | "template";
202	};
203	export interface ContentFilter {
204	  readonly id: string;
205	  check(entry: CatalogEntry, ctx: FilterContext): Promise<FilterFlag[]> | FilterFlag[];
206	}
207	export type FilterDecision = { status: CatalogStatus; flags: FilterFlag[]; reason: string | null };
208	
209	type Rules = typeof rules;
210	const R: Rules = rules;
211	const norm = (s: string) => words(s).join(" ");
212	
213	function fieldsOf(e: CatalogEntry): [string, string][] {
214	  return [["title", e.title], ["shortDescription", e.shortDescription], ["tags", e.tags.join(" ")], ["freeTags", e.freeTags.join(" ")], ["path", e.provenance.path ?? ""], ["pack", e.provenance.pack ?? ""]];
215	}
216	/** whole-word / hyphen-word match on the normalised text ("ak-47" matches "ak 47") */
217	function find(list: readonly string[], text: string): string | null {
218	  const t = ` ${norm(text)} `;
219	  for (const term of list) { const n = norm(term); if (n && t.includes(` ${n} `)) return term; }
220	  return null;
221	}
222	
223	export const wordListFilter = (id: string, list: readonly string[], severity: (e: CatalogEntry, ctx: FilterContext) => FilterSeverity, message: string, fields?: readonly string[]): ContentFilter => ({
224	  id,
225	  check(e, ctx) {
226	    const out: FilterFlag[] = [];
227	    for (const [field, text] of fieldsOf(e)) {
228	      if (fields && !fields.includes(field)) continue;
229	      const m = find(list, text);
230	      if (m) { out.push({ rule: id, severity: severity(e, ctx), field, match: m, message }); break; }
231	    }
232	    return out;
233	  },
234	});
235	
236	/** The first deterministic ruleset. Order does not matter: the strictest severity wins. */
237	export function defaultFilters(): ContentFilter[] {
238	  return [
239	    {
240	      id: "eligibility",
241	      check(e, ctx) {
242	        if (e.licence.tier !== "user-contributed") return [];
243	        const ok = libraryEligible({ legalClass: e.legalClass, provenance: { source: ctx.provenanceSource ?? "user", derivedFrom: [...(ctx.derivedFrom ?? [])] } });
244	        return ok ? [] : [{ rule: "eligibility", severity: "reject", field: "legalClass", match: e.legalClass, message: "not eligible for the community library (imported, uploaded, template or derived content)" }];
245	      },
246	    },
247	    {
248	      id: "not-an-asset",
249	      check: (e) => (e.enrichment.gaps.includes("pack preview image") ? [{ rule: "not-an-asset", severity: "reject" as const, field: "path", match: e.provenance.path ?? "", message: "pack cover / preview image, not an asset" }] : []),
250	    },
251	    wordListFilter("adult", R.adult, () => "reject", "adult content terms"),
252	    wordListFilter("extremist", R.extremist, (_e, ctx) => (ctx.strict ? "reject" : "hold"), "extremist symbol terms"),
253	    wordListFilter("real-weapon", R.realWeapons, (_e, ctx) => (ctx.strict ? "hold" : "flag"), "named after a real firearm model (trademark): owner review", ["title", "shortDescription", "tags", "freeTags", "path"]),
254	    wordListFilter("trademark", R.trademarks, (e, ctx) => {
255	      const prompts = e.categories.primary === "ui/input-prompts";
256	      return prompts || !ctx.strict ? "flag" : "hold";
257	    }, "names a trademark or a game's own content (stub list): owner review"),
258	    wordListFilter("mature-violence", R.matureViolence, () => "flag", "gore / blood (mature-violence flag; plan or audience filters may hide it)"),
259	    wordListFilter("drugs", R.drugs, (_e, ctx) => (ctx.strict ? "hold" : "flag"), "drug references"),
260	  ];
261	}
262	
263	const RANK: Record<FilterSeverity, number> = { flag: 0, hold: 1, reject: 2 };
264	
265	/** pending-checks -> published | held | removed. Entries already held/removed are never auto-published. */
266	export async function runContentFilters(e: CatalogEntry, ctx: FilterContext, filters: readonly ContentFilter[] = defaultFilters()): Promise<FilterDecision> {
267	  const flags: FilterFlag[] = [];
268	  for (const f of filters) {
269	    try { flags.push(...(await f.check(e, ctx))); }
270	    catch (err) { flags.push({ rule: f.id, severity: "hold", field: "-", match: "-", message: `filter error: ${String((err as Error)?.message ?? err).slice(0, 80)}` }); } // fail closed
271	  }
272	  const worst = flags.reduce<FilterSeverity | null>((w, f) => (w == null || RANK[f.severity] > RANK[w] ? f.severity : w), null);
273	  if (e.status === "removed") return { status: "removed", flags, reason: e.statusReason };
274	  if (worst === "reject") return { status: "removed", flags, reason: flags.filter((f) => f.severity === "reject").map((f) => f.message).join("; ").slice(0, 300) };
275	  if (worst === "hold") return { status: "held", flags, reason: flags.filter((f) => f.severity === "hold").map((f) => `${f.rule}: ${f.match}`).join("; ").slice(0, 300) };
276	  if (e.status === "held") return { status: "held", flags, reason: e.statusReason ?? "held by the owner" };
277	  // quality gate: a hard-failed asset (score capped at 20) is never auto-published
278	  if (e.quality.score <= 20) return { status: "held", flags, reason: "quality hard fail (see quality checks)" };
279	  return { status: "published", flags, reason: null };
280	}
