282	/** Write a decision onto an entry: flag ids are `<severity>:<rule>`. */
283	export function applyDecision(e: CatalogEntry, d: FilterDecision): CatalogEntry {
284	  return { ...e, status: d.status, statusReason: d.reason, flags: [...new Set(d.flags.map((f) => `${f.severity}:${f.rule}`))].slice(0, 12) };
285	}
286	// Dedupe + variant grouping, zero tokens.
287	//   exact      : same id (sha256 of the bytes) -> one entry; the extra rows are reported, not stored
288	//   near-dup   : same kind + same normalised stem + same size class (+- 1 % bytes, same triangles / pixel size /
289	//                duration within 10 ms) in a DIFFERENT pack (the same pack ingested twice through two routes)
290	//                -> duplicateOf the best-quality copy; inside one pack, look-alikes are variants, never duplicates
291	//   variants   : same kind + same stem once colour words and take numbers are removed, in the same pack
292	//                ("playerBlue_duck" / "playerRed_duck", "tile_0001".."tile_0099") -> one `group` id, so ranking can
293	//                return ONE representative and stage B can tag a whole group from one contact sheet
294	// Pure.
295	import type { CatalogEntry } from "./entry";
296	import { VOCAB, words, stripExt } from "./vocab";
297	
298	const COLOURS = new Set([...(VOCAB.tags.color ?? []), "gray", "dark", "light", "colored", "coloured", "colour", "color", "alt", "monochrome", "mono", "greyscale", "grayscale", "transparent", "inverted", "silver", "gold", "golden"]);
299	const fileStem = (p: string | null) => stripExt((p ?? "").split("/").pop() ?? "");
300	
301	const SCALE = new Set(["2x", "x2", "hd", "retina", "double", "default", "size", "large", "small", "big", "tiny", "png", "vector", "sprites", "tiles", "x", "1x", "4x", "2", "1", "4", "px", "outline", "outlined", "shaded", "flat", "variants"]);
302	/**
303	 * Variant-family key: folder + file words with colour and scale/rendition words removed, NUMBERS KEPT.
304	 * "Tiles (White)/tile_0532" and "Tiles (Black)/tile_0532" are one family (same glyph, two colours);
305	 * tile_0532 and tile_0533 are different assets. "playerBlue_duck" / "playerRed_duck" are one family.
306	 */
307	export function familyStem(path: string | null, packDepth = 2): string {
308	  const segs = (path ?? "").split("/").filter(Boolean);
309	  const folders = segs.slice(packDepth, -1).flatMap((s) => words(s)).filter((w) => !COLOURS.has(w) && !SCALE.has(w));
310	  const file = words(fileStem(path)).filter((w) => !COLOURS.has(w));
311	  return [...folders, "~", ...file].join("-") || "n";
312	}
313	const exactStem = (path: string | null) => words(fileStem(path)).filter((w) => !/^(copy|final|new)$/.test(w)).join("-");
314	
315	function sizeClass(e: CatalogEntry): string {
316	  const t = e.tech;
317	  if (e.kind === "model") return `t${t.triangles ?? "?"}`;
318	  if (e.kind === "sound" || e.kind === "music") return `d${t.durationS != null ? Math.round(t.durationS * 100) : "?"}`;
319	  return `p${t.width ?? "?"}x${t.height ?? "?"}`;
320	}
321	
322	export type DedupeReport = { exactDuplicates: number; nearDuplicates: number; groups: number; groupedEntries: number };
323	
324	export function dedupe(entries: readonly CatalogEntry[]): { entries: CatalogEntry[]; report: DedupeReport } {
325	  const byId = new Map<string, CatalogEntry>();
326	  let exact = 0;
327	  for (const e of entries) { if (byId.has(e.id)) { exact++; continue; } byId.set(e.id, { ...e }); }
328	  const list = [...byId.values()];
329	
330	  // near duplicates across packs/paths
331	  const near = new Map<string, CatalogEntry[]>();
332	  for (const e of list) {
333	    const k = `${e.kind}|${exactStem(e.provenance.path)}|${sizeClass(e)}`;
334	    if (!k.includes("?")) { const a = near.get(k) ?? []; a.push(e); near.set(k, a); }
335	  }
336	  let nearN = 0;
337	  for (const g of near.values()) {
338	    if (g.length < 2) continue;
339	    g.sort((a, b) => b.quality.score - a.quality.score || (a.id < b.id ? -1 : 1));
340	    const best = g[0];
341	    for (const e of g.slice(1)) {
342	      const sameBytes = best.tech.bytes && Math.abs(e.tech.bytes - best.tech.bytes) <= best.tech.bytes * 0.01;
343	      if (sameBytes && e.provenance.pack !== best.provenance.pack) { e.duplicateOf = best.id; nearN++; }
344	    }
345	  }
346	
347	  // variant families inside one pack (a family whose members all share one stem is no family: skip size-1)
348	  const fam = new Map<string, CatalogEntry[]>();
349	  for (const e of list) {
350	    const k = `${e.kind}|${e.provenance.source}|${e.provenance.pack}|${familyStem(e.provenance.path)}`;
351	    const a = fam.get(k) ?? []; a.push(e); fam.set(k, a);
352	  }
353	  let groups = 0, grouped = 0;
354	  for (const [k, g] of fam) {
355	    if (g.length < 2) continue;
356	    groups++; grouped += g.length;
357	    const id = `g:${k.split("|").slice(0, 4).join(":")}`.slice(0, 120);
358	    for (const e of g) e.group = id;
359	  }
360	  return { entries: list, report: { exactDuplicates: exact, nearDuplicates: nearN, groups, groupedEntries: grouped } };
361	}
362	// Catalog v2 pipeline + host seams.
363	//   CatalogStore     : the store of record (host implements it on the Cyrus-prefixed tables of the migration
364	//                      prisma/manual-migrations/2026-10-10-cyrus-catalog-v2.sql); memory version for tests.
365	//   ingestRows()     : raw rows -> stage A -> dedupe/variant groups -> content filters -> status -> store + index.
366	//   contribute()     : a Cyrus user's generated/authored asset -> pending-checks -> strict filters -> published/held.
367	//   builtinEntries() : the existing libraries (owner sound library manifest, Cyrus texture templates) as entries,
368	//                      so EVERY library flows through one catalog.
369	//   catalogProvider(): a LibraryProvider (lib/cyrus/library/types.ts) over the index, so browseLibrary() and the
370	//                      studios' search keep working unchanged on top of the v2 catalog.
371	// HOST SEAM: no Nxeon imports; ids are content hashes, contributors opaque.
372	import type { AssetProfile } from "../../adapters/asset-profile";
373	import { librarySounds, type LibrarySound } from "../../sound/library";
374	import { libraryTextures } from "../../texture-library/library";
375	import { assetRef, type LibraryAsset, type LibraryProvider } from "../types";
376	import type { CatalogEntry, CatalogStatus } from "./entry";
377	import { libraryKindOf } from "./entry";
378	import { dedupe, type DedupeReport } from "./dedupe";
379	import { applyDecision, runContentFilters, type ContentFilter, type FilterContext } from "./filters";
380	import type { CatalogIndex } from "./retrieval";
