383	export interface CatalogStore {
384	  upsertMany(entries: readonly CatalogEntry[]): Promise<void>;
385	  getMany(ids: readonly string[]): Promise<CatalogEntry[]>;
386	  /** page through one status (cursor = last id) */
387	  listByStatus(status: CatalogStatus, cursor: string | null, limit: number): Promise<CatalogEntry[]>;
388	  setStatus(id: string, status: CatalogStatus, reason: string | null, by: string): Promise<CatalogEntry | null>;
389	}
390	export function createMemoryCatalogStore(): CatalogStore & { all(): CatalogEntry[] } {
391	  const m = new Map<string, CatalogEntry>();
392	  return {
393	    async upsertMany(es) { for (const e of es) m.set(e.id, e); },
394	    async getMany(ids) { return ids.map((i) => m.get(i)).filter((x): x is CatalogEntry => !!x); },
395	    async listByStatus(status, cursor, limit) { return [...m.values()].filter((e) => e.status === status && (!cursor || e.id > cursor)).sort((a, b) => (a.id < b.id ? -1 : 1)).slice(0, limit); },
396	    async setStatus(id, status, reason) { const e = m.get(id); if (!e) return null; const n = { ...e, status, statusReason: reason }; m.set(id, n); return n; },
397	    all: () => [...m.values()],
398	  };
399	}
