401	export type IngestInput = { raw: RawAsset; side?: SideMeta; measured?: Measured };
402	export type IngestReport = {
403	  rows: number; entries: number; invalid: number; coverage: Record<"full" | "partial" | "none", number>;
404	  byKind: Record<string, { rows: number; full: number; partial: number; none: number }>;
405	  status: Record<string, number>; flags: Record<string, number>; gaps: Record<string, number>; dedupe: DedupeReport; errors: { id: string; error: string }[];
406	};
407	
408	export async function ingestRows(rows: readonly IngestInput[], ctx: { profiles: readonly AssetProfile[]; packs?: Readonly<Record<string, PackInfo>>; now: string; filters?: readonly ContentFilter[]; store?: CatalogStore; index?: CatalogIndex }): Promise<{ entries: CatalogEntry[]; report: IngestReport }> {
409	  const results: StageAResult[] = [];
410	  const errors: { id: string; error: string }[] = [];
411	  for (const r of rows) {
412	    const a = enrichStageA(r.raw, { profiles: ctx.profiles, packs: ctx.packs, now: ctx.now }, r.side, r.measured);
413	    results.push(a);
414	    if (!a.entry && errors.length < 50) errors.push({ id: r.raw.id, error: a.errors.map((e) => `${e.path}: ${e.message}`).join("; ").slice(0, 300) });
415	  }
416	  const valid = results.map((r) => r.entry).filter((e): e is CatalogEntry => !!e);
417	  const d = dedupe(valid);
418	  const out: CatalogEntry[] = [];
419	  for (const e of d.entries) {
420	    const fctx: FilterContext = { strict: e.licence.tier === "user-contributed" };
421	    out.push(applyDecision(e, await runContentFilters(e, fctx, ctx.filters)));
422	  }
423	  if (ctx.store) await ctx.store.upsertMany(out);
424	  if (ctx.index) await ctx.index.upsert(out);
425	  const report: IngestReport = { rows: rows.length, entries: out.length, invalid: results.filter((r) => !r.entry).length, coverage: { full: 0, partial: 0, none: 0 }, byKind: {}, status: {}, flags: {}, gaps: {}, dedupe: d.report, errors };
426	  for (const r of results) {
427	    report.coverage[r.coverage]++;
428	    const k = r.entry?.kind ?? "invalid";
429	    const b = (report.byKind[k] ??= { rows: 0, full: 0, partial: 0, none: 0 });
430	    b.rows++; b[r.coverage]++;
431	    for (const g of r.gaps) report.gaps[g] = (report.gaps[g] ?? 0) + 1;
432	  }
433	  for (const e of out) { report.status[e.status] = (report.status[e.status] ?? 0) + 1; for (const f of e.flags) report.flags[f] = (report.flags[f] ?? 0) + 1; }
434	  return { entries: out, report };
435	}
