437	/** A Cyrus user's asset joins the community library: always pending-checks first, strict filters, then published/held/removed. */
438	export async function contribute(input: { raw: RawAsset; side?: SideMeta; measured?: Measured; contributorId: string; provenanceSource: "user" | "ai"; derivedFrom: readonly string[]; legalClass: "user-original" | "ai-generated-for-user" }, ctx: { profiles: readonly AssetProfile[]; now: string; filters?: readonly ContentFilter[]; store?: CatalogStore; index?: CatalogIndex }): Promise<{ entry: CatalogEntry | null; errors: string[] }> {
439	  const a = enrichStageA({ ...input.raw, tier: "user-contributed" }, { profiles: ctx.profiles, now: ctx.now, legalClass: input.legalClass, contributedBy: input.contributorId, licenceStatus: "user-contributed under the Cyrus terms (auto-contribution, owner decision 2026-10-10)" }, input.side, input.measured);
440	  if (!a.entry) return { entry: null, errors: a.errors.map((e) => `${e.path}: ${e.message}`) };
441	  const pending: CatalogEntry = { ...a.entry, status: "pending-checks", provenance: { ...a.entry.provenance, derivedFrom: [...input.derivedFrom] } };
442	  const decided = applyDecision(pending, await runContentFilters(pending, { strict: true, derivedFrom: input.derivedFrom, provenanceSource: input.provenanceSource }, ctx.filters));
443	  if (ctx.store) await ctx.store.upsertMany([decided]);
444	  if (ctx.index) await ctx.index.upsert([decided]);
445	  return { entry: decided, errors: [] };
446	}
