// Cyrus pack hosting (MASTER-PLAN 4.5): content-addressed, immutable resource-pack objects.
// An object is named by the SHA-1 of its bytes (the hash Minecraft checks), at `p/<sha1>.zip`, and never changes.
// Customers only ever see the configured public base domain; the storage provider is never named to them.

export const SHA1_RE = /^[0-9a-f]{40}$/;
/** One year + immutable: the URL is the content hash, so a cached copy can never be stale. */
export const IMMUTABLE_CACHE_CONTROL = "public, max-age=31536000, immutable";
export const PACK_CONTENT_TYPE = "application/zip";
/**
 * Default hard cap per pack: 100 MB. Configurable (CYRUS_PACK_MAX_BYTES). Minecraft's own client-side download
 * limit is UNVERIFIED here (commonly quoted as 250 MB for recent versions; that code is in the client jar, which
 * was not inspected). Keep ours well below it either way: a big pack is a slow join for every player.
 */
export const DEFAULT_MAX_PACK_BYTES = 100 * 1024 * 1024;

export type PackObject = { sha1: string; size: number; lastModified: Date };
export type PutResult = { sha1: string; key: string; size: number; created: boolean };

/** Storage for pack objects. Every method takes the sha1; keys are derived, never caller-chosen. */
export interface PackStore {
  readonly kind: "local" | "s3";
  /** Store bytes under their sha1. Refuses bytes whose sha1 differs. Idempotent: an existing object is left alone. */
  put(sha1: string, bytes: Buffer): Promise<PutResult>;
  exists(sha1: string): Promise<boolean>;
  /** Public URL a Minecraft client downloads from (on the configured base domain). */
  urlFor(sha1: string): string;
  delete(sha1: string): Promise<boolean>;
  list(): Promise<PackObject[]>;
}

export const packKey = (sha1: string): string => {
  if (!SHA1_RE.test(sha1)) throw new Error(`not a sha1: ${sha1}`);
  return `p/${sha1}.zip`;
};

/** `https://packs.example.com` + sha1 -> `https://packs.example.com/p/<sha1>.zip`. Base must be http(s), no query/hash. */
export function publicPackUrl(base: string, sha1: string): string {
  let u: URL;
  try { u = new URL(base); } catch { throw new Error(`pack public base is not a URL: ${base}`); }
  if (u.protocol !== "https:" && u.protocol !== "http:") throw new Error("pack public base must be http(s)");
  if (u.search || u.hash || u.username || u.password) throw new Error("pack public base must not carry a query, fragment or credentials");
  return `${u.origin}${u.pathname.replace(/\/+$/, "")}/${packKey(sha1)}`;
}

/** Parse `<sha1>.zip` (the route's last path segment). */
export function parsePackFile(file: string): string | null {
  const m = /^([0-9a-f]{40})\.zip$/.exec(file);
  return m ? m[1] : null;
}
// S3-compatible pack store (any S3 API: e.g. an R2 bucket, MinIO, AWS S3). Path-style requests
// (<endpoint>/<bucket>/p/<sha1>.zip), SigV4 header auth from ./sigv4, fetch injectable for tests.
// Config comes from env via ./config; nothing is hardcoded. Customers only see `publicBase` URLs.
import { createHash } from "node:crypto";
import { signV4, sha256Hex, uriEncode, type SigV4Credentials } from "./sigv4";
import { IMMUTABLE_CACHE_CONTROL, PACK_CONTENT_TYPE, packKey, publicPackUrl, type PackObject, type PackStore, type PutResult } from "./types";

export type S3StoreConfig = {
  /** e.g. https://<account>.r2.cloudflarestorage.com or https://s3.<region>.amazonaws.com */
  endpoint: string;
  bucket: string;
  /** "auto" for R2; the bucket region for AWS. */
  region: string;
  credentials: SigV4Credentials;
  /** Public base the client downloads from (an Nxeon domain in front of the bucket). */
  publicBase: string;
  /** Optional key prefix inside the bucket (no leading/trailing slash). */
  prefix?: string;
  fetch?: typeof fetch;
  now?: () => Date;
  timeoutMs?: number;
};

export class S3Error extends Error {
  constructor(message: string, readonly status: number | null, readonly body?: string) { super(message); }
}

export class S3Store implements PackStore {
  readonly kind = "s3" as const;
  private readonly f: typeof fetch;
  constructor(readonly cfg: S3StoreConfig) {
    const e = new URL(cfg.endpoint);
    if (e.protocol !== "https:" && !/^(127\.0\.0\.1|localhost)$/.test(e.hostname)) throw new Error("S3 endpoint must be https (http only for localhost)");
    if (!/^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$/.test(cfg.bucket)) throw new Error("bad bucket name");
    if (cfg.prefix && !/^[A-Za-z0-9_.\-/]+$/.test(cfg.prefix)) throw new Error("bad key prefix");
    if (!cfg.credentials.accessKeyId || !cfg.credentials.secretAccessKey) throw new Error("S3 credentials missing");
    publicPackUrl(cfg.publicBase, "0".repeat(40));
    this.f = cfg.fetch ?? fetch;
  }
  private objectKey(sha1: string) {
    const k = packKey(sha1);
    return this.cfg.prefix ? `${this.cfg.prefix.replace(/^\/+|\/+$/g, "")}/${k}` : k;
  }
  private url(key: string, query = "") {
    const base = this.cfg.endpoint.replace(/\/+$/, "");
    return `${base}/${uriEncode(this.cfg.bucket)}/${uriEncode(key, true)}${query ? "?" + query : ""}`;
  }
  private async send(method: string, url: string, body?: Buffer, headers: Record<string, string> = {}) {
    const payloadHash = body ? sha256Hex(body) : undefined;
    const s = signV4({ method, url, headers, payloadHash, region: this.cfg.region, service: "s3", date: this.cfg.now?.() }, this.cfg.credentials);
    const { host: _host, ...send } = s.headers; // fetch sets Host itself
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), this.cfg.timeoutMs ?? 60000);
    try {
      return await this.f(url, { method, headers: send, body: body ? new Uint8Array(body) : undefined, signal: ctl.signal });
    } finally { clearTimeout(t); }
  }
  async exists(sha1: string): Promise<boolean> {
    const r = await this.send("HEAD", this.url(this.objectKey(sha1)));
    if (r.status === 200) return true;
    if (r.status === 404) return false;
    throw new S3Error(`HEAD failed: HTTP ${r.status}`, r.status);
  }
  async put(sha1: string, bytes: Buffer): Promise<PutResult> {
    const key = packKey(sha1);
    const got = createHash("sha1").update(bytes).digest("hex");
    if (got !== sha1) throw new Error(`content sha1 ${got} does not match ${sha1}`);
    if (await this.exists(sha1)) return { sha1, key, size: bytes.length, created: false };
    const r = await this.send("PUT", this.url(this.objectKey(sha1)), bytes, {
      "content-type": PACK_CONTENT_TYPE,
      "cache-control": IMMUTABLE_CACHE_CONTROL,
      "content-length": String(bytes.length),
      "x-amz-meta-sha1": sha1,
    });
    if (r.status !== 200) throw new S3Error(`PUT failed: HTTP ${r.status}`, r.status, (await r.text().catch(() => "")).slice(0, 500));
    return { sha1, key, size: bytes.length, created: true };
  }
  urlFor(sha1: string): string {
    return publicPackUrl(this.cfg.publicBase, sha1);
  }
  async delete(sha1: string): Promise<boolean> {
    const r = await this.send("DELETE", this.url(this.objectKey(sha1)));
    if (r.status === 204 || r.status === 200) return true;
    if (r.status === 404) return false;
    throw new S3Error(`DELETE failed: HTTP ${r.status}`, r.status);
  }
  async list(): Promise<PackObject[]> {
    const prefix = this.objectKey("0".repeat(40)).replace(/0{40}\.zip$/, "");
    const out: PackObject[] = [];
    let token: string | null = null;
    for (let page = 0; page < 1000; page++) {
      const q: string[] = ["list-type=2", `prefix=${uriEncode(prefix)}`];
      if (token) q.push(`continuation-token=${uriEncode(token)}`);
      const r = await this.send("GET", `${this.cfg.endpoint.replace(/\/+$/, "")}/${uriEncode(this.cfg.bucket)}?${q.join("&")}`);
      if (r.status !== 200) throw new S3Error(`LIST failed: HTTP ${r.status}`, r.status);
      const xml = await r.text();
      out.push(...parseListObjects(xml, prefix));
      const truncated = /<IsTruncated>true<\/IsTruncated>/.test(xml);
      token = truncated ? (/<NextContinuationToken>([^<]+)<\/NextContinuationToken>/.exec(xml)?.[1] ?? null) : null;
      if (!token) break;
    }
    return out;
  }
}

const xmlText = (s: string) => s.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, "&");

/** ListObjectsV2 XML -> pack objects (keys that are not `<prefix><sha1>.zip` are ignored). */
export function parseListObjects(xml: string, prefix: string): PackObject[] {
  const out: PackObject[] = [];
  for (const m of xml.matchAll(/<Contents>([\s\S]*?)<\/Contents>/g)) {
    const key = xmlText(/<Key>([^<]*)<\/Key>/.exec(m[1])?.[1] ?? "");
    if (!key.startsWith(prefix)) continue;
    const sm = /^([0-9a-f]{40})\.zip$/.exec(key.slice(prefix.length));
    if (!sm) continue;
    const size = Number(/<Size>(\d+)<\/Size>/.exec(m[1])?.[1] ?? NaN);
    const lm = new Date(/<LastModified>([^<]+)<\/LastModified>/.exec(m[1])?.[1] ?? "");
    if (!Number.isFinite(size) || Number.isNaN(lm.getTime())) continue;
    out.push({ sha1: sm[1], size, lastModified: lm });
  }
  return out;
}
// LocalDiskStore: packs on local disk at <root>/p/<sha1>.zip. For dev, tests and a safe fallback.
// Served in dev by app/p/[file]/route.ts (inert unless this store is the selected one).
import { createHash, randomBytes } from "node:crypto";
import { promises as fsp } from "node:fs";
import path from "node:path";
import { packKey, publicPackUrl, SHA1_RE, type PackObject, type PackStore, type PutResult } from "./types";

export class LocalDiskStore implements PackStore {
  readonly kind = "local" as const;
  constructor(readonly root: string, readonly publicBase: string) {
    if (!path.isAbsolute(root)) throw new Error("LocalDiskStore root must be an absolute path");
    publicPackUrl(publicBase, "0".repeat(40)); // validate the base once
  }
  pathFor(sha1: string): string {
    return path.join(this.root, packKey(sha1));
  }
  async put(sha1: string, bytes: Buffer): Promise<PutResult> {
    const key = packKey(sha1);
    const got = createHash("sha1").update(bytes).digest("hex");
    if (got !== sha1) throw new Error(`content sha1 ${got} does not match ${sha1}`);
    const dest = this.pathFor(sha1);
    if (await this.exists(sha1)) return { sha1, key, size: bytes.length, created: false };
    await fsp.mkdir(path.dirname(dest), { recursive: true });
    const tmp = `${dest}.part-${randomBytes(4).toString("hex")}`;
    await fsp.writeFile(tmp, bytes, { flag: "wx" });
    await fsp.rename(tmp, dest);
    return { sha1, key, size: bytes.length, created: true };
  }
  async exists(sha1: string): Promise<boolean> {
    try { return (await fsp.stat(this.pathFor(sha1))).isFile(); } catch { return false; }
  }
  urlFor(sha1: string): string {
    return publicPackUrl(this.publicBase, sha1);
  }
  async read(sha1: string): Promise<Buffer | null> {
    try { return await fsp.readFile(this.pathFor(sha1)); } catch { return null; }
  }
  async delete(sha1: string): Promise<boolean> {
    try { await fsp.unlink(this.pathFor(sha1)); return true; } catch { return false; }
  }
  async list(): Promise<PackObject[]> {
    const dir = path.join(this.root, "p");
    let names: string[];
    try { names = await fsp.readdir(dir); } catch { return []; }
    const out: PackObject[] = [];
    for (const n of names.sort()) {
      const m = /^([0-9a-f]{40})\.zip$/.exec(n);
      if (!m || !SHA1_RE.test(m[1])) continue;
      const st = await fsp.stat(path.join(dir, n));
      if (st.isFile()) out.push({ sha1: m[1], size: st.size, lastModified: st.mtime });
    }
    return out;
  }
}
// Minimal AWS Signature Version 4 (header auth) with node:crypto. Enough for S3-compatible object storage
// (path-style requests). Tested against AWS's published test vectors (test/cyrus-packhost.test.ts).
import { createHash, createHmac } from "node:crypto";

export type SigV4Credentials = { accessKeyId: string; secretAccessKey: string; sessionToken?: string };
export type SigV4Request = {
  method: string;
  url: string;
  /** Headers to sign (host is added from the URL when missing). Names are case-insensitive. */
  headers?: Record<string, string>;
  /** Hex sha256 of the body, or "UNSIGNED-PAYLOAD". Defaults to the hash of an empty body. */
  payloadHash?: string;
  region: string;
  service: string;
  /** Signing time (defaults to now). */
  date?: Date;
};

export const EMPTY_SHA256 = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
export const sha256Hex = (data: Buffer | string) => createHash("sha256").update(data).digest("hex");
const hmac = (key: Buffer | string, data: string) => createHmac("sha256", key).update(data, "utf8").digest();

/** RFC 3986 encoding as SigV4 wants it (unreserved: A-Z a-z 0-9 - _ . ~). */
export function uriEncode(s: string, keepSlash = false): string {
  let out = "";
  for (const ch of Buffer.from(s, "utf8")) {
    const c = String.fromCharCode(ch);
    if (/[A-Za-z0-9\-_.~]/.test(c) || (keepSlash && c === "/")) out += c;
    else out += "%" + ch.toString(16).toUpperCase().padStart(2, "0");
  }
  return out;
}

export const amzDate = (d: Date) => d.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");

export function signingKey(secret: string, day: string, region: string, service: string): Buffer {
  return hmac(hmac(hmac(hmac(`AWS4${secret}`, day), region), service), "aws4_request");
}

function canonicalQuery(u: URL): string {
  const pairs: [string, string][] = [];
  // URLSearchParams decodes '+' as space; S3 keys never contain a raw '+', and we encode everything we build.
  for (const [k, v] of u.searchParams) pairs.push([uriEncode(k), uriEncode(v)]);
  pairs.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));
  return pairs.map(([k, v]) => `${k}=${v}`).join("&");
}

/** The canonical path: each segment decoded then RFC 3986 encoded once (S3 rule: no double encoding, no normalising). */
function canonicalPath(u: URL): string {
  const p = u.pathname || "/";
  return p.split("/").map((seg) => uriEncode(decodeURIComponent(seg))).join("/") || "/";
}

export type Signed = { headers: Record<string, string>; canonicalRequest: string; stringToSign: string; signature: string; authorization: string };

/** Sign a request. Returns the headers to send (lower-case names), including Authorization and x-amz-date. */
export function signV4(req: SigV4Request, creds: SigV4Credentials): Signed {
  const u = new URL(req.url);
  const date = req.date ?? new Date();
  const stamp = amzDate(date);
  const day = stamp.slice(0, 8);
  const payloadHash = req.payloadHash ?? EMPTY_SHA256;
  const h: Record<string, string> = {};
  for (const [k, v] of Object.entries(req.headers ?? {})) h[k.toLowerCase()] = v;
  if (!h.host) h.host = u.host;
  h["x-amz-date"] = stamp;
  if (req.service === "s3" && !h["x-amz-content-sha256"]) h["x-amz-content-sha256"] = payloadHash;
  if (creds.sessionToken) h["x-amz-security-token"] = creds.sessionToken;
  const names = Object.keys(h).sort();
  const canonHeaders = names.map((n) => `${n}:${h[n].trim().replace(/\s+/g, " ")}\n`).join("");
  const signedHeaders = names.join(";");
  const canonicalRequest = [req.method.toUpperCase(), canonicalPath(u), canonicalQuery(u), canonHeaders, signedHeaders, payloadHash].join("\n");
  const scope = `${day}/${req.region}/${req.service}/aws4_request`;
  const stringToSign = ["AWS4-HMAC-SHA256", stamp, scope, sha256Hex(canonicalRequest)].join("\n");
  const signature = createHmac("sha256", signingKey(creds.secretAccessKey, day, req.region, req.service)).update(stringToSign, "utf8").digest("hex");
  const authorization = `AWS4-HMAC-SHA256 Credential=${creds.accessKeyId}/${scope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;
  return { headers: { ...h, authorization }, canonicalRequest, stringToSign, signature, authorization };
}
// Which pack store to use, from env only. Fail closed: production with nothing configured has NO store
// (pack delivery is off), never a silent fallback to the app server's disk.
//
//   CYRUS_PACK_STORE          local | s3 | off   (default: local outside production, off in production)
//   CYRUS_PACK_PUBLIC_BASE    public base URL clients download from, e.g. https://packs.<nxeon domain>
//                             (default for local: http://localhost:3000, served by app/p/[file]/route.ts)
//   CYRUS_PACK_MAX_BYTES      hard cap per pack (default 100 MB)
//   CYRUS_PACK_LOCAL_DIR      local store root (absolute; default <cwd>/.data/cyrus-packs)
//   CYRUS_PACK_S3_ENDPOINT, CYRUS_PACK_S3_BUCKET, CYRUS_PACK_S3_REGION (default "auto"),
//   CYRUS_PACK_S3_ACCESS_KEY_ID, CYRUS_PACK_S3_SECRET_ACCESS_KEY, CYRUS_PACK_S3_PREFIX (optional)
import path from "node:path";
import { LocalDiskStore } from "./local";
import { S3Store } from "./s3";
import { DEFAULT_MAX_PACK_BYTES, type PackStore } from "./types";

type Env = Record<string, string | undefined>;
export type StoreSelection = { ok: true; store: PackStore; maxBytes: number } | { ok: false; reason: string };

export function maxPackBytes(env: Env = process.env): number {
  const v = env.CYRUS_PACK_MAX_BYTES;
  if (v == null || v === "") return DEFAULT_MAX_PACK_BYTES;
  const n = Number(v);
  if (!Number.isInteger(n) || n < 1024 || n > 1024 * 1024 * 1024) throw new Error("CYRUS_PACK_MAX_BYTES must be an integer between 1 KB and 1 GB");
  return n;
}

export function selectPackStore(env: Env = process.env, opts: { fetch?: typeof fetch } = {}): StoreSelection {
  const prod = env.NODE_ENV === "production";
  const kind = (env.CYRUS_PACK_STORE || (prod ? "off" : "local")).toLowerCase();
  try {
    const maxBytes = maxPackBytes(env);
    if (kind === "off") return { ok: false, reason: "pack hosting is off (CYRUS_PACK_STORE unset or off)" };
    if (kind === "local") {
      const root = env.CYRUS_PACK_LOCAL_DIR || path.join(process.cwd(), ".data/cyrus-packs");
      return { ok: true, store: new LocalDiskStore(root, env.CYRUS_PACK_PUBLIC_BASE || "http://localhost:3000"), maxBytes };
    }
    if (kind === "s3") {
      const need = ["CYRUS_PACK_S3_ENDPOINT", "CYRUS_PACK_S3_BUCKET", "CYRUS_PACK_S3_ACCESS_KEY_ID", "CYRUS_PACK_S3_SECRET_ACCESS_KEY", "CYRUS_PACK_PUBLIC_BASE"].filter((k) => !env[k]);
      if (need.length) return { ok: false, reason: `s3 pack store is missing ${need.join(", ")}` };
      return {
        ok: true,
        maxBytes,
        store: new S3Store({
          endpoint: env.CYRUS_PACK_S3_ENDPOINT!, bucket: env.CYRUS_PACK_S3_BUCKET!, region: env.CYRUS_PACK_S3_REGION || "auto",
          credentials: { accessKeyId: env.CYRUS_PACK_S3_ACCESS_KEY_ID!, secretAccessKey: env.CYRUS_PACK_S3_SECRET_ACCESS_KEY! },
          publicBase: env.CYRUS_PACK_PUBLIC_BASE!, prefix: env.CYRUS_PACK_S3_PREFIX || undefined, fetch: opts.fetch,
        }),
      };
    }
    return { ok: false, reason: `unknown CYRUS_PACK_STORE ${kind}` };
  } catch (e) {
    return { ok: false, reason: (e as Error).message };
  }
}

// The Cyrus HOST SEAM: everything Cyrus needs from the platform it runs inside, as small interfaces.
// Inside Nxeon the implementation is lib/cyrus/host/nxeon.ts (the ONLY file under lib/cyrus allowed to import Nxeon
// internals, enforced by test/cyrus-host-seam.test.ts). Standalone Cyrus supplies its own implementation of this
// interface (or an adapter that calls the Nxeon API). Add a method here when Cyrus needs a new platform service,
// never import the platform directly. Pure types: client-safe, no imports.

import type { PrismaClient } from "@prisma/client";

/** Cyrus' OWN tables (the 27 Cyrus* models plus ModBuild, which has no relations to platform tables) and raw SQL, nothing else.
 *  Nxeon's tables (User, Server, ServerMod, GameMod, Job, Setting, Notification...) are deliberately absent: Cyrus reaches
 *  them only through the methods of CyrusHost, so a standalone Cyrus needs just its own database. */
export type CyrusDb = Pick<PrismaClient,
  | "modBuild" | "cyrusProject" | "cyrusRevision" | "cyrusProjectAsset"
  | "cyrusModelDraft" | "cyrusIdentifier" | "cyrusManagedPlugin" | "cyrusServerManagedPlugin"
  | "cyrusTokenAccount" | "cyrusTokenLot" | "cyrusTokenLedger" | "cyrusTokenReservation"
  | "cyrusPlan" | "cyrusModPage" | "cyrusModPost" | "cyrusModReport"
  | "cyrusFork" | "cyrusModListing" | "cyrusModMedia" | "cyrusRemix"
  | "cyrusModStar" | "cyrusModRating" | "cyrusLibraryItem" | "cyrusCreator"
  | "cyrusCollection" | "cyrusCollectionItem" | "cyrusCommunityReport" | "cyrusModSignal"
  | "cyrusCreatorAlert" | "cyrusCatalogEntry" | "cyrusCatalogReview" | "cyrusCatalogEnrichmentRun"
  | "$transaction" | "$queryRaw" | "$executeRaw" | "$queryRawUnsafe" | "$executeRawUnsafe">;

export type HostRateLimit = { ok: boolean; retryAfterSec: number; remaining: number };

/** The signed-in person as Cyrus sees them. The platform's own user record is a superset of this. */
export type HostUser = { id: string; email: string | null; role: string; name?: string | null };
/** A permission area of the host's admin ("billing", "support"...). Opaque to Cyrus; each host defines its own. */
export type HostArea = string;
/** Private-preview feature keys Cyrus may ask about. */
export type HostPreviewFeature = "modbuilder";

/** A game server's filesystem as installers see it (absolute guest paths). Structurally identical to the platform's GuestFs. */
export interface HostGuestFs {
  readonly kind: "ssh" | "local";
  stat(p: string): Promise<{ type: "file" | "dir"; size: number } | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  /** Creates parent directories. */
  writeFile(p: string, data: Buffer): Promise<void>;
  mkdirp(p: string): Promise<void>;
  /** Move, overwriting a file at `to`. Creates the destination's parent. */
  rename(from: string, to: string): Promise<void>;
  /** File or directory (recursive). Missing is not an error. */
  remove(p: string): Promise<void>;
  /** Entry names; [] when missing. */
  list(dir: string): Promise<string[]>;
  /** Best-effort: give `paths` the owner/group of `ref` (real guests only). */
  chownLike(ref: string, paths: string[]): Promise<void>;
  copy(from: string, to: string): Promise<void>;
}
/** What the host knows about a game server (the guest itself is asked separately). */
export type HostServerFacts = { id: string; family: string; variant: string | null; pinnedVersion: string | null; config: Record<string, unknown> | null };
/** What the host's catalogue knows about a mod; Cyrus mints these for its own sources ("cyrus", managed plugins, mod packs). */
export type HostModFacts = {
  id: string; gameFamily: string; slug: string; name: string; source: string; sourceId: string | null; url: string | null; category: string;
  appliesToVariant: string | null; loaders: string[]; gameVersions: string[]; serverSide: string | null; targetVersionId?: string | null;
};
export type HostResolvedPackage = {
  key: string; name: string; version: string; versionId?: string | null;
  file: { url: string; filename: string; size: number | null; hashes: { sha1?: string | null; sha256?: string | null; sha512?: string | null } };
  /** "plugin-jar" | "datapack" for Minecraft. */
  placement: string;
  requires: string[]; incompatible: { key: string; name: string }[];
  /** The bytes, already fetched and verified by Cyrus: the host never downloads for Cyrus. */
  prefetched?: Buffer;
  root: boolean;
};
export type HostResolution = { packages: HostResolvedPackage[]; notes: string[]; alsoBackupDirs?: string[] };
export type HostInstallResult =
  | { ok: true; version?: string; versionId?: string | null; fileName?: string | null; restartRequired: boolean; changed: string[]; notes: string[] }
  | { ok: false; error: string };

/** A game server row as Cyrus reads it. The platform's own row is a superset. */
export type HostServerRow = {
  id: string; status: string; label?: string | null; hostname: string; gameVariant: string | null; gameConfig: unknown;
  osTemplate?: { family: string } | null;
};
/** One mod installed on one server (the platform's install record). */
export type HostInstallRow = {
  serverId: string; modId: string; versionId: string | null; status: string; error: string | null; updatedAt: Date; autoUpdate: string | null;
  mod: { source: string; sourceId: string | null; name: string };
};

export interface CyrusHost {
  /** Cyrus' own database (see CyrusDb). Use through lib/cyrus/db.ts (cyrusDb), not directly. */
  db: CyrusDb;
  /** Who is signed in. Sessions, cookies and impersonation stay entirely the host's business. */
  auth: {
    /** The acting user (impersonation applied), or null when signed out. */
    currentUser(): Promise<HostUser | null>;
    /** The really signed-in user, ignoring impersonation, or null. */
    realUser(): Promise<HostUser | null>;
    /** Page guard for an admin area: returns the real staff user, or ends the request (redirect/404) by the host's rule. */
    requireArea(area: HostArea): Promise<HostUser>;
  };
  /** Permission checks. Fail CLOSED: unknown role/area/feature is false. */
  access: {
    canAccess(role: string, area: HostArea): boolean;
    isPreviewUser(user: { email?: string | null } | null | undefined, feature: HostPreviewFeature): Promise<boolean>;
  };
  /** Key/value settings and feature flags (Nxeon: the Setting table). Values are strings; missing keys use the fallback. */
  settings: {
    get(key: string, fallback?: string): Promise<string>;
    getBool(key: string, fallback?: boolean): Promise<boolean>;
    getInt(key: string, fallback?: number): Promise<number>;
    getAll(): Promise<Record<string, string>>;
    set(key: string, value: string): Promise<void>;
    /** Values exactly as stored (no defaults, no cache): for admin editors that must tell "unset" from "default". */
    readStored(keys: string[]): Promise<Record<string, string>>;
    readStoredPrefix(prefix: string): Promise<Record<string, string>>;
    writeStored(key: string, value: string): Promise<void>;
    clearStored(key: string): Promise<void>;
  };
  /** Fixed-window rate limiter keyed by an opaque string. Synchronous, in-process. */
  rateLimit: {
    check(key: string, opts: { max: number; windowMs: number }): HostRateLimit;
  };
  /** Platform-side background work Cyrus's scheduler (lib/cyrus/worker/schedule.ts) drives but does not own. Each call is one sweep pass. */
  worker: {
    /** Installed-mod lifecycle on customer servers: Broken signals, crash-loop auto-disable, opt-in auto-updates. */
    modLifecycleSweep(): Promise<unknown>;
    /** Creator warnings about game versions the mod no longer fits. */
    modCompatWatchSweep(): Promise<unknown>;
    /** Advance in-flight AI mod builds from the build service. */
    syncModBuilds(): Promise<unknown>;
  };
  /** Accounts, by id. Billing identity is the host's; Cyrus only reads the basics and stores the payment customer id it creates. */
  users: {
    get(id: string): Promise<{ id: string; email: string } | null>;
    emails(ids: string[]): Promise<{ id: string; email: string }[]>;
    /** By email (case-insensitive) when `query` contains "@", otherwise by id. */
    find(query: string): Promise<{ id: string; email: string } | null>;
    setBillingCustomerId(userId: string, customerId: string): Promise<void>;
  };
  /** Background jobs the host queues (read side only). */
  jobs: {
    /** The newest finished job of one of `types` on a server, or null. */
    lastDone(serverId: string, types: string[]): Promise<{ updatedAt: Date; payload: unknown } | null>;
  };
  /** The host's game servers. */
  servers: {
    get(serverId: string): Promise<HostServerRow | null>;
    /** The user's servers that are not being deleted, oldest first. */
    listForUser(userId: string): Promise<HostServerRow[]>;
    /** Which game a server row is (e.g. "minecraft"), or null when it cannot be told. */
    familyOf(server: HostServerRow): string | null;
    /** The game family of the plan a server was bought on, or null. */
    planFamily(serverId: string): Promise<string | null>;
    /** How many paid (not free) game servers the user has. */
    paidCount(userId: string): Promise<number>;
    /** The newest "health" mod-update run on a server (log-read verdicts), or null. */
    lastHealthRun(serverId: string): Promise<{ startedAt: Date; plan: unknown } | null>;
    /** File access to ONE of this user's servers (null when it is not theirs, gone, or being deleted); `base` is the game folder on it. */
    openFiles(userId: string, serverId: string): Promise<{ fs: HostGuestFs; base: string; close?: () => void } | null>;
    /** The game version pinned in a server's config, when it names a real one. */
    pinnedVersion(config: unknown): string | null;
  };
  /** What the host has recorded as installed (its ServerMod/GameMod records). */
  records: {
    /** Installs on one server whose catalogue source is `source`. */
    onServer(serverId: string, source: string): Promise<HostInstallRow[]>;
    /** Which of `serverIds` have at least one install from `source` (each id once). */
    serversWithSource(serverIds: string[], source: string): Promise<string[]>;
    /** The catalogue entry id for a source's item, or null. */
    catalogId(source: string, sourceId: string): Promise<string | null>;
    /** Installs of one catalogue entry on any of `serverIds`. */
    ofMod(modId: string, serverIds: string[]): Promise<Omit<HostInstallRow, "mod">[]>;
  };
  /** Putting Cyrus' files on a server through the host's install engine (which keeps the host's own record of what it placed). */
  installs: {
    /** The engine's state file on the server; a pack install snapshots it so a failed install also undoes the bookkeeping. */
    readonly statePath: string;
    /** Place the prefetched package(s) of `resolution` for `mod`. Never downloads: a download attempt fails with `noDownloadMessage`. */
    install(a: { fs: HostGuestFs; server: HostServerFacts; mod: HostModFacts; resolution: HostResolution; mode: "install" | "update"; noDownloadMessage: string }): Promise<HostInstallResult>;
    /** Remove what the engine recorded for `mod` (and dependencies nothing else needs). */
    uninstall(a: { fs: HostGuestFs; server: HostServerFacts; mod: HostModFacts; noDownloadMessage: string }): Promise<HostInstallResult>;
  };
  /** Append-only audit trail; attribution to the acting admin is the host's job. */
  audit: {
    record(userId: string | null, action: string, detail?: string): Promise<void>;
    /** A plain row exactly as given (no impersonation attribution, no request IP): Cyrus' own admin trail. */
    append(row: { userId: string | null; action: string; detail?: string; category?: string; target?: string }): Promise<void>;
  };
}

/** Settings stored as "true"/"on"/"1" are true. Same rule as the platform's own coercion. */
export function isTrue(v: string | undefined | null): boolean {
  return v === "true" || v === "on" || v === "1";
}
// Host registry: Cyrus code asks for the host here, never for the platform. SERVER ONLY (the default loads the
