    const mb = profile.meshBudget;
    const b = h.triBudget ?? (mb ? { prop: mb.maxTriangles, character: mb.maxTriangles, vehicle: mb.maxTriangles } : undefined);
    const tris = s.tech.triangles;
    if (!b) return { fit: mode === "native" ? "ok" : "no", reason: "no triangle budget declared for this game", notes, transform: [] };
    const budget = charLike(s) ? b.character : vehicleLike(s) ? b.vehicle : b.prop;
    notes.push(`tri budget ${budget} (${charLike(s) ? "character" : vehicleLike(s) ? "vehicle" : "prop"})`);
    if (charLike(s) && s.tech.rigged === false && s.tags.includes("animated")) notes.push("animated but no skin");
    if (tris == null) return { fit: "ok", reason: "triangle count not measured", notes, transform: mode === "convert" ? ["mesh-convert"] : [] };
    if (tris > budget * 4) return { fit: "no", reason: `${tris} tris is over 4x the ${budget} budget (no LOD tool yet)`, notes, transform: [] };
    const over = tris > budget;
    return { fit: over || !styleOk ? "ok" : "good", reason: over ? `${tris} tris, over the ${budget} budget` : styleOk ? `${tris} tris, within budget` : `within budget but ${s.style ?? "unstyled"} is off-style`, notes, transform: mode === "convert" ? ["mesh-convert"] : [] };
  }

