// Benchmark the catalog indexes on a READ-ONLY copy of the real catalog entries (no model calls, no network).
//   npx tsx scripts/cyrus/library-bench.ts --entries entries2-staged-cc0.jsonl [--sqlite-file /tmp/x.db] [--reps 3] [--out bench.json]
// Builds the in-memory index and the SQLite index (":memory:" unless --sqlite-file), runs the situation queries plus
// deliberately BROAD ones (the 17 s case was a broad synonym OR-query) through the model-facing catalog_search tool
// and through index.search directly, and prints build time + median / max per query and backend.
// Also checks that both backends return the same top-8 ids (the SQLite index uses the memory ranking exactly).
import { readFileSync, writeFileSync } from "node:fs";
import { validateCatalogEntry, type CatalogEntry } from "../../lib/cyrus/library/v2/entry";
import { createMemoryCatalogIndex, type CatalogIndex } from "../../lib/cyrus/library/v2/retrieval";
import { createSqliteCatalogIndex } from "../../lib/cyrus/library/v2/sqlite-index";
import { catalogSearch } from "../../lib/cyrus/library/v2/tools";

export const SITUATION_QUERIES = ["weapon pickup sound", "sci-fi crate prop", "stone wall floor texture", "medieval torch", "zombie character", "wooden door", "ui click", "explosion sound", "grass ground texture", "treasure chest", "car", "health potion", "crosshair", "night sky", "footstep"];
/** broad: single very common words, colour words, multi-word synonym-heavy queries, the empty browse */
export const BROAD_QUERIES = ["wood", "stone", "tile", "metal", "blue", "green tile", "wooden door", "old wooden house door", "medieval sword weapon", "rock ground floor wall texture", "sound effect", "character"];

const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
const median = (a: number[]) => { const s = [...a].sort((x, y) => x - y); return s[Math.floor(s.length / 2)]; };
const ms = (t: bigint) => Number(process.hrtime.bigint() - t) / 1e6;

async function timeQuery(ix: CatalogIndex, q: string, reps: number) {
  const tool: number[] = [], raw: number[] = [];
  let top: string[] = [], n = 0;
  for (let i = 0; i < reps; i++) {
    let t = process.hrtime.bigint();
    await catalogSearch({ query: q.length >= 2 ? q : "any", limit: 8 }, { index: ix, plan: "all", game: null, proprietaryCleared: true });
    tool.push(ms(t));
    t = process.hrtime.bigint();
    const r = await ix.search({ text: q, limit: 8, statuses: ["published"] });
    raw.push(ms(t));
    top = r.hits.map((h) => h.entry.id); n = r.total;
  }
  return { tool: { median: +median(tool).toFixed(1), max: +Math.max(...tool).toFixed(1) }, raw: { median: +median(raw).toFixed(1), max: +Math.max(...raw).toFixed(1) }, top, n };
}

async function main() {
  const file = arg("--entries");
  if (!file) { console.error("usage: library-bench.ts --entries entries.jsonl [--sqlite-file f.db] [--reps 3] [--out bench.json]"); process.exit(2); }
  const reps = Number(arg("--reps") ?? 3);
  const t0 = process.hrtime.bigint();
  const entries: CatalogEntry[] = [];
  let invalid = 0;
  for (const l of readFileSync(file, "utf8").split("\n")) { if (!l) continue; const v = validateCatalogEntry(JSON.parse(l)); if (v.ok) entries.push(v.entry); else invalid++; }
  const loadMs = ms(t0);
  let t = process.hrtime.bigint();
  const mem = createMemoryCatalogIndex(entries);
  const memMs = ms(t);
  t = process.hrtime.bigint();
  const sql = await createSqliteCatalogIndex(arg("--sqlite-file") ?? ":memory:");
  if ((await sql.size()) !== entries.length) await sql.upsert(entries);
  const sqlMs = ms(t);
  const rows: Record<string, unknown>[] = [];
  let agree = 0, total = 0;
  for (const [set, qs] of [["situation", SITUATION_QUERIES], ["broad", BROAD_QUERIES], ["browse", [""]]] as const) {
    for (const q of qs) {
      const m = await timeQuery(mem, q, reps);
      const s = await timeQuery(sql, q, reps);
      const same = m.top.join() === s.top.join();
      total++; if (same) agree++;
      rows.push({ set, q, memory: { tool: m.tool, raw: m.raw, n: m.n }, sqlite: { tool: s.tool, raw: s.raw, n: s.n }, sameTop8: same });
      console.log(`${set.padEnd(9)} ${JSON.stringify(q).padEnd(34)} memory tool ${String(m.tool.median).padStart(7)} ms (max ${m.tool.max})  sqlite tool ${String(s.tool.median).padStart(7)} ms (max ${s.tool.max})  n ${m.n}/${s.n} sameTop8 ${same}`);
    }
  }
  sql.close();
  const sqlTimes = rows.map((r) => (r.sqlite as { tool: { max: number } }).tool.max);
  const out = { entries: entries.length, invalid, loadMs: Math.round(loadMs), build: { memoryMs: Math.round(memMs), sqliteMs: Math.round(sqlMs) }, sqliteWorstToolMs: Math.max(...sqlTimes), agreeTop8: `${agree}/${total}`, rows, node: process.version, at: new Date().toISOString() };
  console.log(JSON.stringify({ entries: out.entries, invalid, build: out.build, sqliteWorstToolMs: out.sqliteWorstToolMs, agreeTop8: out.agreeTop8 }));
  if (arg("--out")) writeFileSync(arg("--out")!, JSON.stringify(out, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });

