// Local SQLite backend of CatalogIndex (SERVER-ONLY: node:sqlite, Node >= 22.13; node-2 runs Node 24). One file or
// ":memory:" database, no extension, no network. A rebuildable search cache: the store of record is the host's DB.
//
// Index v2 (r26, 2026-10-10): a POSTING-LIST index that ranks EXACTLY like the memory index (retrieval.ts):
//   posting(term, rid, w)  one row per (term, entry), w = the best field weight the term has in that entry
//                          (the same docFields() the memory index uses), so per query word
//                          best = max over its synonyms of (w, or w x 0.85 for a synonym) and idf = log(1 + (N+1)/(df+0.5))
//                          with df = the typed word's posting count: identical to textScore().
// The whole query (term scores, >= 50 % word share, share^2, filters, fit/quality rank, group collapse, total,
// pagination) runs as ONE SQL statement with window functions; only the page's JSON rows are read back.
// Why: v1 (FTS5 + bm25 ORDER BY ... LIMIT 4000) scored every match before the LIMIT and parsed up to 4,000 JSON rows
// in JS: broad synonym queries took up to 17 s on 54k entries (measured, r14). Numbers for v2: docs "Cyrus asset
// library backend".
// A file written by v1 (FTS5 tables) is detected (PRAGMA user_version) and dropped: size() is 0 and the caller re-imports.
import type { CatalogEntry } from "./entry";
import { docFields, effectiveKinds, parseQuery, FIELD_WEIGHTS, FIT_WEIGHT, MIN_WORD_SHARE, type CatalogHit, type CatalogIndex, type CatalogQuery } from "./retrieval";

type Stmt = { run: (...a: unknown[]) => unknown; all: (...a: unknown[]) => unknown[]; get: (...a: unknown[]) => unknown };
type Db = { exec: (sql: string) => void; prepare: (sql: string) => Stmt; close: () => void };

export const SQLITE_INDEX_VERSION = 2;
const SYNONYM_FACTOR = 0.85;
/** sqlite's default SQLITE_MAX_VARIABLE_NUMBER is 32766; one query uses a few per term, far below */
const MAX_TERMS = 24;

/** term -> best field weight in this entry (what one posting row stores) */
export function postingsOf(e: CatalogEntry): Map<string, number> {
  const out = new Map<string, number>();
  for (const [f, ts] of Object.entries(docFields(e)) as [keyof typeof FIELD_WEIGHTS, string[]][]) {
    const w = FIELD_WEIGHTS[f];
    for (const t of ts) if (t && (out.get(t) ?? 0) < w) out.set(t, w);
  }
  return out;
}

const spaced = (xs: readonly string[]) => ` ${xs.join(" ")} `;
const gamesOf = (e: CatalogEntry) => JSON.stringify(Object.fromEntries(Object.entries(e.games).map(([g, f]) => [g, f.fit])));

export async function createSqliteCatalogIndex(file = ":memory:"): Promise<CatalogIndex & { close(): void }> {
  const spec = "node:sqlite"; // a variable specifier: bundlers never pull it into client code, tsc needs no node:sqlite types
  const mod = (await import(/* webpackIgnore: true */ spec)) as unknown as { DatabaseSync: new (f: string) => Db };
  const db = new mod.DatabaseSync(file);
  const ver = Number((db.prepare("PRAGMA user_version").get() as { user_version: number }).user_version);
  if (ver !== SQLITE_INDEX_VERSION) {
    // v1 cache (FTS5) or a fresh file: drop whatever is there, the caller rebuilds from the store of record
    db.exec("DROP TABLE IF EXISTS entry_fts; DROP TABLE IF EXISTS posting; DROP TABLE IF EXISTS entry;");
  }
  db.exec(`
    PRAGMA journal_mode = ${file === ":memory:" ? "MEMORY" : "WAL"};
    PRAGMA synchronous = NORMAL;
    PRAGMA temp_store = MEMORY;
    CREATE TABLE IF NOT EXISTS entry (
      rid INTEGER PRIMARY KEY, id TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, status TEXT NOT NULL, tier TEXT NOT NULL,
      quality INTEGER NOT NULL, dup TEXT, grp TEXT, games TEXT NOT NULL, tags TEXT NOT NULL, usefor TEXT NOT NULL, cats TEXT NOT NULL, json TEXT NOT NULL);
    CREATE INDEX IF NOT EXISTS entry_filter ON entry(status, kind, tier, quality);
    CREATE TABLE IF NOT EXISTS posting (term TEXT NOT NULL, rid INTEGER NOT NULL, w REAL NOT NULL, PRIMARY KEY (term, rid)) WITHOUT ROWID;
    CREATE INDEX IF NOT EXISTS posting_rid ON posting(rid);
    PRAGMA user_version = ${SQLITE_INDEX_VERSION};
  `);
  const findRid = db.prepare("SELECT rid FROM entry WHERE id = ?");
  const insEntry = db.prepare("INSERT INTO entry (id, kind, status, tier, quality, dup, grp, games, tags, usefor, cats, json) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING rid");
  const updEntry = db.prepare("UPDATE entry SET kind = ?, status = ?, tier = ?, quality = ?, dup = ?, grp = ?, games = ?, tags = ?, usefor = ?, cats = ?, json = ? WHERE rid = ?");
  const delPost = db.prepare("DELETE FROM posting WHERE rid = ?");
  const insPost = db.prepare("INSERT INTO posting (term, rid, w) VALUES (?, ?, ?)");
  const delEntry = db.prepare("DELETE FROM entry WHERE rid = ?");
  const getOne = db.prepare("SELECT json FROM entry WHERE id = ?");
  const prefix = db.prepare("SELECT id, json FROM entry WHERE id >= ? AND id < ? LIMIT 2");
  const count = db.prepare("SELECT COUNT(*) AS n FROM entry");
  const dfStmt = db.prepare("SELECT COUNT(*) AS n FROM posting WHERE term = ?");
  const upper = (p: string) => p + "g"; // hex prefix range end ("g" sorts after every hex digit)
  const parse = (j: unknown) => JSON.parse(String((j as { json: string }).json)) as CatalogEntry;
  // df / N cache, cleared on every write (a query never sees stale idf)
  const dfCache = new Map<string, number>();
  let nCache: number | null = null;
  const invalidate = () => { dfCache.clear(); nCache = null; };
  const N = () => (nCache ??= Number((count.get() as { n: number }).n));
  const df = (t: string) => { let v = dfCache.get(t); if (v == null) { v = Number((dfStmt.get(t) as { n: number }).n); dfCache.set(t, v); } return v; };
  const idf = (t: string) => Math.log(1 + (N() + 1) / (df(t) + 0.5));

  const writeOne = (e: CatalogEntry) => {
    const old = findRid.get(e.id) as { rid: number } | undefined;
    const cols = [e.kind, e.status, e.licence.tier, e.quality.score, e.duplicateOf, e.group, gamesOf(e), spaced([...e.tags, ...e.freeTags]), spaced(e.useFor), spaced([e.categories.primary, ...e.categories.secondary]), JSON.stringify(e)];
    let rid: number;
    if (old) { rid = Number(old.rid); updEntry.run(...cols, rid); delPost.run(rid); }
    else rid = Number((insEntry.get(e.id, ...cols) as { rid: number }).rid);
    for (const [t, w] of postingsOf(e)) insPost.run(t, rid, w);
  };

  const api: CatalogIndex & { close(): void } = {
    async upsert(es) {
      invalidate();
      db.exec("BEGIN");
      try { for (const e of es) writeOne(e); db.exec("COMMIT"); }
      catch (err) { db.exec("ROLLBACK"); throw err; }
    },
    async remove(ids) {
      invalidate();
      db.exec("BEGIN");
      try { for (const id of ids) { const r = findRid.get(id) as { rid: number } | undefined; if (r) { delPost.run(r.rid); delEntry.run(r.rid); } } db.exec("COMMIT"); }
      catch (err) { db.exec("ROLLBACK"); throw err; }
    },
    async get(idOrPrefix) {
      const p = idOrPrefix.replace(/^(cat:|c:)/, "").toLowerCase();
      if (!/^[0-9a-f]{8,64}$/.test(p)) return null;
      if (p.length === 64) { const r = getOne.get(p); return r ? parse(r) : null; }
      const rows = prefix.all(p, upper(p));
      return rows.length === 1 ? parse(rows[0]) : null;
    },
    async shortId(id) {
      for (let n = 12; n < 64; n += 2) if (prefix.all(id.slice(0, n), upper(id.slice(0, n))).length <= 1) return id.slice(0, n);
      return id;
    },
    async size() { return N(); },
    async search(q: CatalogQuery) {
      const parsed = parseQuery(q.text ?? "");
      const kinds = effectiveKinds(q.kinds, parsed.kindHints);
      const terms = parsed.terms.slice(0, MAX_TERMS);
      const args: unknown[] = [];
      const ctes: string[] = [];
      // 1. one CTE per query word: best weight per entry over the word and its synonyms, times the typed word's idf
      if (terms.length) {
        const parts = terms.map((alts, i) => {
          args.push(alts[0], SYNONYM_FACTOR, idf(alts[0]), ...alts);
          return `SELECT rid, MAX(CASE WHEN term = ? THEN w ELSE w * ? END) * ? AS s FROM posting WHERE term IN (${alts.map(() => "?").join(",")}) GROUP BY rid`;
          void i;
        });
