/** term -> best field weight in this entry (what one posting row stores) */
export function postingsOf(e: CatalogEntry): Map<string, number> {
  const out = new Map<string, number>();
  for (const [f, ts] of Object.entries(docFields(e)) as [keyof typeof FIELD_WEIGHTS, string[]][]) {
    const w = FIELD_WEIGHTS[f];
    for (const t of ts) if (t && (out.get(t) ?? 0) < w) out.set(t, w);
  }
  return out;
}

const spaced = (xs: readonly string[]) => ` ${xs.join(" ")} `;
const gamesOf = (e: CatalogEntry) => JSON.stringify(Object.fromEntries(Object.entries(e.games).map(([g, f]) => [g, f.fit])));

