// Cyrus asset library backend (r26): switches, from env only. Everything is OFF unless set; fail closed.
//   CYRUS_LIBRARY_BACKEND=1        master switch: the library routes answer (otherwise 404 as if they did not exist)
//   CYRUS_LIBRARY_CONTRIBUTE=1     automatic community contribution writes (owner decision 2026-10-10: contribution
//                                  is automatic; this flag only decides whether the backend is live yet)
//   CYRUS_LIBRARY_STORE            off | local | s3   (default off: no object store, nothing served)
//   CYRUS_LIBRARY_LOCAL_DIR        local store root (absolute), e.g. /tank/cyrus-library-store
//   CYRUS_LIBRARY_STAGING_DIR      READ-ONLY source of the staged originals, e.g. /tank/cyrus-library-staging
//   CYRUS_LIBRARY_S3_ENDPOINT, _BUCKET, _REGION (default auto), _ACCESS_KEY_ID, _SECRET_ACCESS_KEY, _PREFIX (optional)
//   CYRUS_LIBRARY_URL_SECRET       HMAC key for signed file URLs (>= 32 chars); missing = no URL can be signed
//   CYRUS_LIBRARY_FFMPEG, CYRUS_LIBRARY_PYTHON, CYRUS_LIBRARY_GLTF_TRANSFORM   tool paths for derivative recipes
//   CYRUS_SOUND_LIBRARY_CLEARED=1  (existing) the owner's proprietary SFX library may reach customers (as previews
//                                  and transformed builds only; never as raw files)
// HOST SEAM: pure (env in, plain object out).
export type Env = Record<string, string | undefined>;

export type LibraryFlags = {
  enabled: boolean;
  contribute: boolean;
  store: "off" | "local" | "s3";
  localDir: string | null;
  stagingDir: string | null;
  urlSecret: string | null;
  proprietaryCleared: boolean;
  tools: { ffmpeg: string | null; python: string | null; gltfTransform: string | null };
};

const abs = (p: string | undefined) => (p && p.startsWith("/") && !p.includes("\0") ? p.replace(/\/+$/, "") || "/" : null);

export function libraryFlags(env: Env = process.env): LibraryFlags {
  const s = (env.CYRUS_LIBRARY_STORE ?? "off").toLowerCase();
  const secret = env.CYRUS_LIBRARY_URL_SECRET ?? "";
  return {
    enabled: env.CYRUS_LIBRARY_BACKEND === "1",
    contribute: env.CYRUS_LIBRARY_BACKEND === "1" && env.CYRUS_LIBRARY_CONTRIBUTE === "1",
    store: s === "local" || s === "s3" ? s : "off",
    localDir: abs(env.CYRUS_LIBRARY_LOCAL_DIR),
    stagingDir: abs(env.CYRUS_LIBRARY_STAGING_DIR),
    urlSecret: secret.length >= 32 ? secret : null,
    proprietaryCleared: env.CYRUS_SOUND_LIBRARY_CLEARED === "1",
    tools: { ffmpeg: abs(env.CYRUS_LIBRARY_FFMPEG), python: abs(env.CYRUS_LIBRARY_PYTHON), gltfTransform: abs(env.CYRUS_LIBRARY_GLTF_TRANSFORM) },
  };
}

