// Library object storage on the ObjectStore contract of lib/cyrus/jobs/asset-jobs.ts: content-addressed keys
// `sha256/<hex>` (identical bytes = one object, keys are never caller-chosen), bytes verified on every read.
//   LocalObjectStore  disk, sharded <root>/sha256/<2 hex>/<64 hex>, atomic write (tmp + rename)
//   S3ObjectStore     any S3 API (path-style, SigV4 from ../../packhost/sigv4), PRIVATE objects: never a public URL;
//                     customers only ever get signed, expiring URLs of the Nxeon route (./signed-url.ts)
//   StagingSource     READ-ONLY view of the staged library (/tank/cyrus-library-staging): an entry's original is read
//                     from <root>/<provenance.path>, path-confined (no "..", no symlink escape) and sha256-checked.
//                     It never writes, moves or deletes anything there.
// SERVER ONLY (node:fs, node:crypto). HOST SEAM: no Nxeon imports.
import { createHash, randomBytes } from "node:crypto";
import { promises as fsp } from "node:fs";
import path from "node:path";
import { contentKey, sha256Hex, type ObjectStore } from "../../jobs/asset-jobs";
import { signV4, uriEncode, sha256Hex as sigSha, type SigV4Credentials } from "../../packhost/sigv4";

export const OBJECT_KEY_RE = /^sha256\/[0-9a-f]{64}$/;
export const keyOf = (sha: string) => { if (!/^[0-9a-f]{64}$/.test(sha)) throw new Error(`not a sha256: ${sha}`); return `sha256/${sha}`; };
export const shaOfKey = (key: string) => { if (!OBJECT_KEY_RE.test(key)) throw new Error(`not an object key: ${key}`); return key.slice(7); };

export type StoredObject = { key: string; size: number; modifiedAt: Date };
export interface LibraryObjectStore extends ObjectStore {
  readonly kind: "memory" | "local" | "s3";
  size(key: string): Promise<number | null>;
  list(): AsyncIterable<StoredObject>;
}

export function createMemoryLibraryObjectStore(now: () => Date = () => new Date()): LibraryObjectStore {
  const m = new Map<string, { b: Uint8Array; at: Date }>();
  return {
    kind: "memory",
    async put(bytes) { const k = contentKey(bytes); if (!m.has(k)) m.set(k, { b: Uint8Array.from(bytes), at: now() }); return k; },
    async get(key) { return m.get(key)?.b ?? null; },
    async has(key) { return m.has(key); },
    async delete(key) { m.delete(key); },
    async size(key) { return m.get(key)?.b.length ?? null; },
    async *list() { for (const [key, v] of m) yield { key, size: v.b.length, modifiedAt: v.at }; },
  };
}

