    const { host: _h, ...send } = s.headers;
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), this.cfg.timeoutMs ?? 60000);
    try { return await this.f(url, { method, headers: send, body: body ? new Uint8Array(body) : undefined, signal: ctl.signal }); }
    finally { clearTimeout(t); }
