    const r = await this.send("HEAD", this.url(this.objectKey(key)));
    if (r.status === 404) return null;
    if (r.status !== 200) throw new Error(`S3 HEAD failed: HTTP ${r.status}`);
    const n = Number(r.headers.get("content-length"));
    return Number.isFinite(n) ? n : null;
  }
