// Library DERIVATIVES: deterministic recipes (no model calls), generated lazily on first request and cached as
// content-addressed objects. A recipe id carries its version (`thumb@1`); changing a recipe's output = a new
// version, so cached objects are never silently different. Every recipe has an output cap.
//   thumb@1        PNG <= 256 px edge. PNG sources in-process (pure JS: bounded decode, box-filter downscale,
//                  nearest-neighbour upscale of tiny pixel art to >= 64 px). JPEG sources via Python PIL (pinned
//                  script, version recorded). Sources: the file itself (sprite/texture/decal PNG), a sibling
//                  `<stem>.png` (Poly Haven models), the folder's `<Name>.png` / `*_Color.jpg` / `*_TONEMAPPED.jpg`
//                  (ambientCG sets, HDRIs, decals). A bare .hdr/.exr or a .glb without a sibling image: no thumbnail
//                  (needs a tone-mapper / renderer: not built).
//   preview-ogg@1  audio preview: mono 44.1 kHz Vorbis q3, first 30 s, loudness-normalised (EBU R128 single pass),
//                  bit-exact muxing, metadata stripped (ffmpeg). The ONLY way audio ever leaves the library: the raw
//                  file is never served (and the owner's proprietary library only once it is cleared).
//   glb-opt@1      gltf-transform optimize (weld, dedup, prune, meshopt) on the original .glb.
//   bundle@1       folder kinds (PBR sets, HDRIs, decals): a deterministic zip (sorted names, fixed timestamps) of
//                  the folder's image + material files (.blend / .usdc scene files left out).
// SERVER ONLY (node:child_process for the tool recipes). HOST SEAM: no Nxeon imports.
import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { deflateSync } from "node:zlib";
import { decodePng } from "../png-decode";
import { crc32 } from "../../textures/png";
import { zip } from "../../textures/zip";
import type { CatalogEntry, CatalogKind } from "../v2/entry";

export const RECIPE_IDS = ["thumb@1", "preview-ogg@1", "glb-opt@1", "bundle@1"] as const;
export type RecipeId = (typeof RECIPE_IDS)[number];
export const RECIPE_MIME: Record<RecipeId, string> = { "thumb@1": "image/png", "preview-ogg@1": "audio/ogg", "glb-opt@1": "model/gltf-binary", "bundle@1": "application/zip" };
/** output caps per recipe (bytes) */
export const RECIPE_MAX_BYTES: Record<RecipeId, number> = { "thumb@1": 512 * 1024, "preview-ogg@1": 2 * 1024 * 1024, "glb-opt@1": 48 * 1024 * 1024, "bundle@1": 160 * 1024 * 1024 };
export const THUMB_EDGE = 256;
export const PREVIEW_SECONDS = 30;

const FOLDER_KINDS: readonly CatalogKind[] = ["texture-set", "hdri", "decal"];
export const isFolderEntry = (e: Pick<CatalogEntry, "kind" | "tech">) => FOLDER_KINDS.includes(e.kind) && !/^(png|jpg|jpeg)$/i.test(e.tech.format);
const isAudio = (k: CatalogKind) => k === "sound" || k === "music";

/** Which derivatives an entry can have (the store still answers "not_available" when a source/tool is missing). */
export function recipesFor(e: Pick<CatalogEntry, "kind" | "tech">): RecipeId[] {
  if (isAudio(e.kind)) return ["preview-ogg@1"];
  if (e.kind === "model") return /^glb$/i.test(e.tech.format) ? ["thumb@1", "glb-opt@1"] : ["thumb@1"];
  if (e.kind === "motion") return [];
  return isFolderEntry(e) ? ["thumb@1", "bundle@1"] : ["thumb@1"];
}

export type ToolResult = { status: number | null; stdout: Buffer; stderr: string };
/** argv only (never a shell), stdin in, stdout out, hard timeout + output cap */
export type ToolRunner = (bin: string, args: readonly string[], input: Uint8Array | null, opts: { timeoutMs: number; maxOutput: number }) => ToolResult;
export const spawnTool: ToolRunner = (bin, args, input, opts) => {
  const r = spawnSync(bin, [...args], { input: input ?? undefined, maxBuffer: opts.maxOutput, timeout: opts.timeoutMs, killSignal: "SIGKILL", env: { PATH: "/usr/bin:/bin", LC_ALL: "C" } });
  return { status: r.error ? null : r.status, stdout: r.stdout ?? Buffer.alloc(0), stderr: String(r.error?.message ?? r.stderr ?? "").slice(0, 400) };
};

export type DeriveTools = { ffmpeg: string | null; python: string | null; gltfTransform: string | null; run: ToolRunner };
/** what a recipe may read: the original, the thumbnail source, the folder files (all already path-confined + capped) */
export type DeriveInput = {
  entry: CatalogEntry;
  original(): Promise<Uint8Array | null>;
  thumbSource(): Promise<{ bytes: Uint8Array; ext: "png" | "jpg" } | null>;
  folder(): Promise<{ name: string; bytes: Uint8Array }[] | null>;
};
export type DeriveResult = { ok: true; bytes: Uint8Array; tool: string } | { ok: false; code: "not_available" | "tool_missing" | "tool_failed" | "too_large" | "bad_source"; error: string };

const no = (code: Extract<DeriveResult, { ok: false }>["code"], error: string): DeriveResult => ({ ok: false, code, error });

// ---- pure-JS PNG thumbnail ------------------------------------------------------------------------------------

function pngChunk(type: string, data: Uint8Array): Buffer {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0); out.write(type, 4, "ascii"); Buffer.from(data).copy(out, 8);
  out.writeUInt32BE(crc32(out.subarray(4, 8 + data.length)), 8 + data.length);
  return out;
}
/** RGBA w x h -> PNG (8-bit, filter 0, deflate 9): deterministic for the same pixels. */
export function encodeRgbaPng(w: number, h: number, px: Uint8ClampedArray | Uint8Array): Buffer {
  const raw = Buffer.alloc(h * (w * 4 + 1));
  for (let y = 0; y < h; y++) Buffer.from(px.buffer, px.byteOffset + y * w * 4, w * 4).copy(raw, y * (w * 4 + 1) + 1);
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6;
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), pngChunk("IHDR", ihdr), pngChunk("IDAT", deflateSync(raw, { level: 9 })), pngChunk("IEND", new Uint8Array(0))]);
}

/** Thumbnail of a PNG: fit in `edge` (box filter, alpha-weighted); pixel art <= 64 px is upscaled by an integer factor. */
export function thumbFromPng(bytes: Uint8Array, edge = THUMB_EDGE): { ok: true; png: Buffer; width: number; height: number } | { ok: false; error: string } {
  const d = decodePng(Buffer.from(bytes), { maxBytes: 32 * 1024 * 1024, sizes: [], maxChunks: 4096, anySize: { maxSide: 8192, maxPixels: 40_000_000 } });
  if (!d.ok) return { ok: false, error: `${d.code}: ${d.error}` };
  const { width: w, height: h } = d, src = d.raster.px;
  const big = Math.max(w, h);
  if (big <= 64) {
    const f = Math.max(1, Math.floor(Math.min(edge, 128) / big));
    const W = w * f, H = h * f, out = new Uint8ClampedArray(W * H * 4);
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) { const s = (((y / f) | 0) * w + ((x / f) | 0)) * 4, o = (y * W + x) * 4; out[o] = src[s]; out[o + 1] = src[s + 1]; out[o + 2] = src[s + 2]; out[o + 3] = src[s + 3]; }
    return { ok: true, png: encodeRgbaPng(W, H, out), width: W, height: H };
  }
  const scale = Math.min(1, edge / big);
  const W = Math.max(1, Math.round(w * scale)), H = Math.max(1, Math.round(h * scale));
  const out = new Uint8ClampedArray(W * H * 4);
  for (let y = 0; y < H; y++) {
    const y0 = Math.floor((y * h) / H), y1 = Math.max(y0 + 1, Math.floor(((y + 1) * h) / H));
    for (let x = 0; x < W; x++) {
      const x0 = Math.floor((x * w) / W), x1 = Math.max(x0 + 1, Math.floor(((x + 1) * w) / W));
      let r = 0, g = 0, b = 0, a = 0, n = 0;
      for (let yy = y0; yy < y1; yy++) for (let xx = x0; xx < x1; xx++) { const s = (yy * w + xx) * 4, al = src[s + 3]; r += src[s] * al; g += src[s + 1] * al; b += src[s + 2] * al; a += al; n++; }
      const o = (y * W + x) * 4;
      if (a > 0) { out[o] = Math.round(r / a); out[o + 1] = Math.round(g / a); out[o + 2] = Math.round(b / a); }
      out[o + 3] = Math.round(a / n);
    }
  }
  return { ok: true, png: encodeRgbaPng(W, H, out), width: W, height: H };
}

// ---- tool recipes ---------------------------------------------------------------------------------------------

/** Pinned PIL script: same input + same Pillow version = same bytes (Pillow version goes into the tool string). */
export const PIL_THUMB_SCRIPT = [
  "import io, sys, PIL",
  "from PIL import Image",
  "Image.MAX_IMAGE_PIXELS = 80_000_000",
  "im = Image.open(io.BytesIO(sys.stdin.buffer.read()))",
  `im.draft('RGB', (${THUMB_EDGE * 2}, ${THUMB_EDGE * 2}))`,
  "im = im.convert('RGBA')",
  `im.thumbnail((${THUMB_EDGE}, ${THUMB_EDGE}), Image.Resampling.LANCZOS)`,
  "b = io.BytesIO(); im.save(b, 'PNG', optimize=False, compress_level=9)",
  "sys.stdout.buffer.write(b.getvalue()); sys.stderr.write('pillow ' + PIL.__version__)",
].join("\n");

export const FFMPEG_PREVIEW_ARGS: readonly string[] = [
  "-nostdin", "-v", "error", "-protocol_whitelist", "pipe", "-i", "pipe:0", "-map", "0:a:0", "-t", String(PREVIEW_SECONDS),
  "-af", "loudnorm=I=-16:TP=-1.5:LRA=11", "-ac", "1", "-ar", "44100", "-c:a", "libvorbis", "-q:a", "3",
  "-map_metadata", "-1", "-fflags", "+bitexact", "-flags:a", "+bitexact", "-f", "ogg", "pipe:1",
];

async function thumb(input: DeriveInput, tools: DeriveTools): Promise<DeriveResult> {
  const src = await input.thumbSource();
  if (!src) return no("not_available", "no thumbnail source (a renderer / tone-mapper would be needed)");
  if (src.ext === "png") {
    const t = thumbFromPng(src.bytes);
    return t.ok ? { ok: true, bytes: t.png, tool: "cyrus-thumb-js@1" } : no("bad_source", t.error);
  }
  if (!tools.python) return no("tool_missing", "python3 with Pillow is not configured (CYRUS_LIBRARY_PYTHON)");
  const r = tools.run(tools.python, ["-I", "-c", PIL_THUMB_SCRIPT], src.bytes, { timeoutMs: 30_000, maxOutput: RECIPE_MAX_BYTES["thumb@1"] * 2 });
  if (r.status !== 0 || !r.stdout.length) return no("tool_failed", `pillow: ${r.stderr}`);
  return { ok: true, bytes: r.stdout, tool: `pil-thumb@1 (${r.stderr.match(/pillow [0-9.]+/)?.[0] ?? "pillow ?"})` };
}

async function previewOgg(input: DeriveInput, tools: DeriveTools): Promise<DeriveResult> {
  if (!tools.ffmpeg) return no("tool_missing", "ffmpeg is not configured (CYRUS_LIBRARY_FFMPEG)");
  const b = await input.original();
  if (!b) return no("not_available", "original not readable");
  const r = tools.run(tools.ffmpeg, FFMPEG_PREVIEW_ARGS, b, { timeoutMs: 60_000, maxOutput: RECIPE_MAX_BYTES["preview-ogg@1"] * 2 });
  if (r.status !== 0 || r.stdout.length < 28 || r.stdout.toString("latin1", 0, 4) !== "OggS") return no("tool_failed", `ffmpeg: ${r.stderr}`);
  return { ok: true, bytes: r.stdout, tool: "ffmpeg-preview-ogg@1" };
}

async function glbOpt(input: DeriveInput, tools: DeriveTools): Promise<DeriveResult> {
  if (!tools.gltfTransform) return no("tool_missing", "gltf-transform is not configured (CYRUS_LIBRARY_GLTF_TRANSFORM)");
  const b = await input.original();
  if (!b) return no("not_available", "original not readable");
  const dir = mkdtempSync(path.join(os.tmpdir(), "cyrus-glbopt-"));
  try {
    writeFileSync(path.join(dir, "in.glb"), b);
    const r = tools.run(tools.gltfTransform, ["optimize", path.join(dir, "in.glb"), path.join(dir, "out.glb"), "--compress", "meshopt", "--texture-compress", "false"], null, { timeoutMs: 120_000, maxOutput: 1024 * 1024 });
    if (r.status !== 0) return no("tool_failed", `gltf-transform: ${r.stderr}`);
    const out = readFileSync(path.join(dir, "out.glb"));
    if (out.toString("latin1", 0, 4) !== "glTF") return no("tool_failed", "gltf-transform wrote no glb");
    return { ok: true, bytes: out, tool: "gltf-transform-optimize@1" };
  } finally { rmSync(dir, { recursive: true, force: true }); }
}

/** files a bundle carries (images, EXR/HDR, MaterialX); scene files (.blend/.usdc) stay out */
export const BUNDLE_EXT = /\.(png|jpe?g|exr|hdr|mtlx|tif|tiff)$/i;
async function bundle(input: DeriveInput): Promise<DeriveResult> {
  const files = await input.folder();
  if (!files?.length) return no("not_available", "not a folder entry");
  const keep = files.filter((f) => BUNDLE_EXT.test(f.name));
  if (!keep.length) return no("bad_source", "the folder has no image files");
  return { ok: true, bytes: zip(keep.map((f) => ({ path: f.name, data: Buffer.from(f.bytes) }))), tool: "cyrus-bundle-zip@1" };
}

export async function runRecipe(id: RecipeId, input: DeriveInput, tools: DeriveTools): Promise<DeriveResult> {
  if (!recipesFor(input.entry).includes(id)) return no("not_available", `${id} does not apply to a ${input.entry.kind}`);
  const r = id === "thumb@1" ? await thumb(input, tools) : id === "preview-ogg@1" ? await previewOgg(input, tools) : id === "glb-opt@1" ? await glbOpt(input, tools) : await bundle(input);
  if (r.ok && r.bytes.length > RECIPE_MAX_BYTES[id]) return no("too_large", `${id} output is ${r.bytes.length} bytes (cap ${RECIPE_MAX_BYTES[id]})`);
  return r;
}

