  return { ok: true, png: encodeRgbaPng(W, H, out), width: W, height: H };
}

// ---- tool recipes ---------------------------------------------------------------------------------------------

/** Pinned PIL script: same input + same Pillow version = same bytes (Pillow version goes into the tool string). */
export const PIL_THUMB_SCRIPT = [
  "import io, sys, PIL",
  "from PIL import Image",
  "Image.MAX_IMAGE_PIXELS = 80_000_000",
  "im = Image.open(io.BytesIO(sys.stdin.buffer.read()))",
  `im.draft('RGB', (${THUMB_EDGE * 2}, ${THUMB_EDGE * 2}))`,
  "im = im.convert('RGBA')",
  `im.thumbnail((${THUMB_EDGE}, ${THUMB_EDGE}), Image.Resampling.LANCZOS)`,
  "b = io.BytesIO(); im.save(b, 'PNG', optimize=False, compress_level=9)",
  "sys.stdout.buffer.write(b.getvalue()); sys.stderr.write('pillow ' + PIL.__version__)",
].join("\n");

export const FFMPEG_PREVIEW_ARGS: readonly string[] = [
  "-nostdin", "-v", "error", "-protocol_whitelist", "pipe", "-i", "pipe:0", "-map", "0:a:0", "-t", String(PREVIEW_SECONDS),
  "-af", "loudnorm=I=-16:TP=-1.5:LRA=11", "-ac", "1", "-ar", "44100", "-c:a", "libvorbis", "-q:a", "3",
  "-map_metadata", "-1", "-fflags", "+bitexact", "-flags:a", "+bitexact", "-f", "ogg", "pipe:1",
];

async function thumb(input: DeriveInput, tools: DeriveTools): Promise<DeriveResult> {
  const src = await input.thumbSource();
  if (!src) return no("not_available", "no thumbnail source (a renderer / tone-mapper would be needed)");
  if (src.ext === "png") {
    const t = thumbFromPng(src.bytes);
    return t.ok ? { ok: true, bytes: t.png, tool: "cyrus-thumb-js@1" } : no("bad_source", t.error);
  }
  if (!tools.python) return no("tool_missing", "python3 with Pillow is not configured (CYRUS_LIBRARY_PYTHON)");
  const r = tools.run(tools.python, ["-I", "-c", PIL_THUMB_SCRIPT], src.bytes, { timeoutMs: 30_000, maxOutput: RECIPE_MAX_BYTES["thumb@1"] * 2 });
  if (r.status !== 0 || !r.stdout.length) return no("tool_failed", `pillow: ${r.stderr}`);
  return { ok: true, bytes: r.stdout, tool: `pil-thumb@1 (${r.stderr.match(/pillow [0-9.]+/)?.[0] ?? "pillow ?"})` };
}

async function previewOgg(input: DeriveInput, tools: DeriveTools): Promise<DeriveResult> {
  if (!tools.ffmpeg) return no("tool_missing", "ffmpeg is not configured (CYRUS_LIBRARY_FFMPEG)");
  const b = await input.original();
  if (!b) return no("not_available", "original not readable");
  const r = tools.run(tools.ffmpeg, FFMPEG_PREVIEW_ARGS, b, { timeoutMs: 60_000, maxOutput: RECIPE_MAX_BYTES["preview-ogg@1"] * 2 });
  if (r.status !== 0 || r.stdout.length < 28 || r.stdout.toString("latin1", 0, 4) !== "OggS") return no("tool_failed", `ffmpeg: ${r.stderr}`);
  return { ok: true, bytes: r.stdout, tool: "ffmpeg-preview-ogg@1" };
}

async function glbOpt(input: DeriveInput, tools: DeriveTools): Promise<DeriveResult> {
  if (!tools.gltfTransform) return no("tool_missing", "gltf-transform is not configured (CYRUS_LIBRARY_GLTF_TRANSFORM)");
  const b = await input.original();
  if (!b) return no("not_available", "original not readable");
  const dir = mkdtempSync(path.join(os.tmpdir(), "cyrus-glbopt-"));
  try {
    writeFileSync(path.join(dir, "in.glb"), b);
    const r = tools.run(tools.gltfTransform, ["optimize", path.join(dir, "in.glb"), path.join(dir, "out.glb"), "--compress", "meshopt", "--texture-compress", "false"], null, { timeoutMs: 120_000, maxOutput: 1024 * 1024 });
    if (r.status !== 0) return no("tool_failed", `gltf-transform: ${r.stderr}`);
    const out = readFileSync(path.join(dir, "out.glb"));
    if (out.toString("latin1", 0, 4) !== "glTF") return no("tool_failed", "gltf-transform wrote no glb");
    return { ok: true, bytes: out, tool: "gltf-transform-optimize@1" };
  } finally { rmSync(dir, { recursive: true, force: true }); }
}

/** files a bundle carries (images, EXR/HDR, MaterialX); scene files (.blend/.usdc) stay out */
export const BUNDLE_EXT = /\.(png|jpe?g|exr|hdr|mtlx|tif|tiff)$/i;
async function bundle(input: DeriveInput): Promise<DeriveResult> {
  const files = await input.folder();
  if (!files?.length) return no("not_available", "not a folder entry");
  const keep = files.filter((f) => BUNDLE_EXT.test(f.name));
  if (!keep.length) return no("bad_source", "the folder has no image files");
  return { ok: true, bytes: zip(keep.map((f) => ({ path: f.name, data: Buffer.from(f.bytes) }))), tool: "cyrus-bundle-zip@1" };
}

export async function runRecipe(id: RecipeId, input: DeriveInput, tools: DeriveTools): Promise<DeriveResult> {
  if (!recipesFor(input.entry).includes(id)) return no("not_available", `${id} does not apply to a ${input.entry.kind}`);
  const r = id === "thumb@1" ? await thumb(input, tools) : id === "preview-ogg@1" ? await previewOgg(input, tools) : id === "glb-opt@1" ? await glbOpt(input, tools) : await bundle(input);
  if (r.ok && r.bytes.length > RECIPE_MAX_BYTES[id]) return no("too_large", `${id} output is ${r.bytes.length} bytes (cap ${RECIPE_MAX_BYTES[id]})`);
  return r;
}

