// The library backend's own records (next to the catalog store of record, lib/cyrus/library/v2/pipeline.ts
// CatalogStore): derivative cache rows, "Use in project" dependents, reports, the moderation / takedown log and
// near-duplicate fingerprints. Interfaces + an in-memory implementation (tests, single box); the Postgres one is
// ./pg.ts on the Cyrus-prefixed tables of prisma/manual-migrations/2026-10-10-cyrus-library-backend.sql.
// Ids are opaque: catalog ids are content hashes, contributors/reporters/actors are opaque strings (never an email).
// HOST SEAM: pure, no Nxeon imports.
import { randomBytes } from "node:crypto";
import type { CatalogKind, CatalogStatus } from "../v2/entry";
import type { RecipeId } from "./derive";

export type DerivativeRow = { entryId: string; recipe: RecipeId; objectKey: string; bytes: number; tool: string; createdAt: Date; lastUsedAt: Date };
/** One library asset used by one project slot. copySha256 = the project's OWN copy (CyrusProjectAsset), null when the
 *  asset is rendered from the library at build time (the owner's proprietary sounds, which are never copied raw). */
export type UseRow = { entryId: string; projectId: string; slotId: string; kind: CatalogKind; copySha256: string | null; upstream: CatalogStatus; createdAt: Date; updatedAt: Date };
export const REPORT_REASONS = ["copyright", "trademark", "real-weapon", "mature", "offensive", "broken", "other"] as const;
export type ReportReason = (typeof REPORT_REASONS)[number];
export type ReportRow = { id: string; entryId: string; reporter: string; reason: ReportReason; note: string | null; status: "open" | "actioned" | "dismissed"; createdAt: Date; resolvedAt: Date | null; resolvedBy: string | null };
export const MOD_ACTIONS = ["contribute", "duplicate", "hold", "release", "report", "takedown", "restore", "dismiss"] as const;
export type ModAction = (typeof MOD_ACTIONS)[number];
export type ModerationRow = { id: string; entryId: string; action: ModAction; from: CatalogStatus | null; to: CatalogStatus | null; by: string; reason: string | null; legal: boolean; dependents: number; at: Date };
/** near-duplicate fingerprint: `fp` is a 64-bit hex (images, audio envelopes) or an exact facts key (models, motion) */
export type FingerprintRow = { entryId: string; kind: CatalogKind; method: "dhash64" | "env64" | "facts"; fp: string };

export interface LibraryRecords {
  derivatives: {
    get(entryId: string, recipe: RecipeId): Promise<DerivativeRow | null>;
    put(row: DerivativeRow): Promise<void>;
    touch(entryId: string, recipe: RecipeId, at: Date): Promise<void>;
    unusedSince(cutoff: Date, limit: number): Promise<DerivativeRow[]>;
    forEntry(entryId: string): Promise<DerivativeRow[]>;
    delete(entryId: string, recipe: RecipeId): Promise<void>;
    /** rows still pointing at an object (a derivative object may be shared by identical outputs) */
    refs(objectKey: string): Promise<number>;
  };
  uses: {
    upsert(row: Omit<UseRow, "createdAt" | "updatedAt" | "upstream"> & { upstream?: CatalogStatus }, at: Date): Promise<UseRow>;
    get(projectId: string, slotId: string): Promise<UseRow | null>;
    forEntry(entryId: string): Promise<UseRow[]>;
    /** sets `upstream` on every use of the entry; returns how many dependents were marked */
    markUpstream(entryId: string, status: CatalogStatus, at: Date): Promise<number>;
  };
  reports: {
    /** one open report per (entry, reporter): a second one from the same reporter is not counted again */
    add(r: Omit<ReportRow, "id" | "status" | "resolvedAt" | "resolvedBy">): Promise<{ row: ReportRow; created: boolean }>;
    open(entryId?: string, limit?: number): Promise<ReportRow[]>;
    resolve(entryId: string, status: "actioned" | "dismissed", by: string, at: Date): Promise<number>;
  };
  log: {
    append(r: Omit<ModerationRow, "id">): Promise<ModerationRow>;
    list(q: { actions?: readonly ModAction[]; entryId?: string; limit?: number }): Promise<ModerationRow[]>;
  };
  fingerprints: {
    put(r: FingerprintRow): Promise<void>;
    /** every row of the kind + method whose fp shares at least one 16-bit band with `fp` (hex), or equals it (facts) */
    candidates(kind: CatalogKind, method: FingerprintRow["method"], fp: string): Promise<FingerprintRow[]>;
  };
}

export const newId = (p: string) => `${p}_${randomBytes(9).toString("base64url")}`;
export const bands64 = (fp: string) => (/^[0-9a-f]{16}$/.test(fp) ? [0, 1, 2, 3].map((i) => `${i}:${fp.slice(i * 4, i * 4 + 4)}`) : [`x:${fp}`]);

export function createMemoryLibraryRecords(): LibraryRecords {
  const der = new Map<string, DerivativeRow>();
  const uses = new Map<string, UseRow>();
  const reports: ReportRow[] = [];
  const log: ModerationRow[] = [];
  const fps = new Map<string, FingerprintRow>();
  const band = new Map<string, Set<string>>();
  const dk = (e: string, r: string) => `${e}|${r}`;
  return {
    derivatives: {
      async get(e, r) { return der.get(dk(e, r)) ?? null; },
      async put(row) { der.set(dk(row.entryId, row.recipe), { ...row }); },
      async touch(e, r, at) { const x = der.get(dk(e, r)); if (x) x.lastUsedAt = at; },
      async unusedSince(cutoff, limit) { return [...der.values()].filter((d) => d.lastUsedAt < cutoff).sort((a, b) => +a.lastUsedAt - +b.lastUsedAt).slice(0, limit); },
      async forEntry(e) { return [...der.values()].filter((d) => d.entryId === e); },
      async delete(e, r) { der.delete(dk(e, r)); },
      async refs(k) { return [...der.values()].filter((d) => d.objectKey === k).length; },
    },
    uses: {
      async upsert(row, at) {
        const k = `${row.projectId}|${row.slotId}`;
        const old = uses.get(k);
        const n: UseRow = { ...row, upstream: row.upstream ?? old?.upstream ?? "published", createdAt: old && old.entryId === row.entryId ? old.createdAt : at, updatedAt: at };
        uses.set(k, n); return { ...n };
      },
      async get(p, s) { const u = uses.get(`${p}|${s}`); return u ? { ...u } : null; },
      async forEntry(e) { return [...uses.values()].filter((u) => u.entryId === e).map((u) => ({ ...u })); },
      async markUpstream(e, status, at) { let n = 0; for (const u of uses.values()) if (u.entryId === e) { u.upstream = status; u.updatedAt = at; n++; } return n; },
    },
    reports: {
      async add(r) {
        const dup = reports.find((x) => x.entryId === r.entryId && x.reporter === r.reporter && x.status === "open");
        if (dup) return { row: { ...dup }, created: false };
        const row: ReportRow = { ...r, id: newId("rep"), status: "open", resolvedAt: null, resolvedBy: null };
        reports.push(row); return { row: { ...row }, created: true };
      },
      async open(e, limit = 200) { return reports.filter((r) => r.status === "open" && (!e || r.entryId === e)).slice(0, limit).map((r) => ({ ...r })); },
      async resolve(e, status, by, at) { let n = 0; for (const r of reports) if (r.entryId === e && r.status === "open") { r.status = status; r.resolvedBy = by; r.resolvedAt = at; n++; } return n; },
    },
    log: {
      async append(r) { const row = { ...r, id: newId("mod") }; log.push(row); return { ...row }; },
      async list(q) { return log.filter((r) => (!q.actions || q.actions.includes(r.action)) && (!q.entryId || r.entryId === q.entryId)).slice().reverse().slice(0, q.limit ?? 100); },
    },
    fingerprints: {
      async put(r) { fps.set(r.entryId, { ...r }); for (const b of bands64(r.fp)) { const k = `${r.kind}|${r.method}|${b}`; const s = band.get(k) ?? new Set(); s.add(r.entryId); band.set(k, s); } },
      async candidates(kind, method, fp) {
        const ids = new Set<string>();
