// Catalog quality score `cq-1` (0-100), deterministic, zero tokens. It says how SAFE and USABLE an asset is to
// pick automatically, not how pretty it is (a vision/ear judge calibrated on owner labels is a later stage C item).
//   score = round( 100 * sum(weight * s) / sum(weight of MEASURED checks) * (0.4 + 0.6 * measuredShare) )
//   s: pass 1, warn 0.5, fail 0; skip = not measured (left out of the ratio, but lowers measuredShare)
//   any check marked `hard` that fails caps the score at 20 (corrupt file, silent audio, zero triangles).
// So an asset whose technical facts were never measured stays well below a measured one (licence + metadata alone
// reach ~67), and every number is explainable per check.
import type { CatalogKind, Quality, QualityCheck, Tech } from "./entry";

export const QUALITY_VERSION = "cq-1";
type Status = QualityCheck["status"];
type C = QualityCheck & { hard?: boolean };

export type QualityInput = {
  kind: CatalogKind;
  tech: Tech;
  /** true = licence source recorded; "unverified" = a licence exists but nobody has documented it per file yet */
  licenceDocumented: boolean | "unverified";
  hasThumbnail: boolean;
  /** stage-A confidence that title/category are right */
  metadataConfidence: number;
  /** the decoder/parser failed on the bytes */
  corrupt?: string | null;
  /** category's typical real-world height (m), when known */
  expectedHeightM?: number | null;
};

const c = (id: string, status: Status, weight: number, detail: string, hard = false): C => ({ id, status, weight, detail: detail.slice(0, 160), ...(hard ? { hard } : {}) });
const skip = (id: string, weight: number, why = "not measured") => c(id, "skip", weight, why);
const pow2 = (n: number) => n > 0 && (n & (n - 1)) === 0;
  else out.push(c("sample_rate", t.sampleRate >= 44100 ? "pass" : t.sampleRate >= 22050 ? "warn" : "fail", 1, `${t.sampleRate} Hz`));
  if (t.lufs == null) out.push(skip("loudness", 1));
  else out.push(c("loudness", t.lufs >= -35 && t.lufs <= -6 ? "pass" : "warn", 1, `${t.lufs} LUFS (normalised per role at build time)`));
  return out;
}

export function catalogQuality(q: QualityInput): Quality {
  const t = q.tech;
  const checks: C[] = [];
  if (q.corrupt && q.kind !== "sound" && q.kind !== "music") checks.push(c("parse", "fail", 2, q.corrupt, true));
  else if (q.kind === "model") checks.push(...modelChecks(t, q));
  else if (q.kind === "texture-set") checks.push(...textureSetChecks(t));
  else if (q.kind === "sound" || q.kind === "music") checks.push(...audioChecks(t, q.kind, q.corrupt));
  else checks.push(...imageChecks(t, q.kind));
  checks.push(c("licence", q.licenceDocumented === true ? "pass" : q.licenceDocumented === "unverified" ? "warn" : "fail", 2, q.licenceDocumented === true ? "licence source recorded" : q.licenceDocumented === "unverified" ? "licence held but not documented per file" : "no licence source"));
  checks.push(c("thumbnail", q.hasThumbnail ? "pass" : "warn", 1, q.hasThumbnail ? "preview exists" : "no preview image"));
  checks.push(c("metadata", q.metadataConfidence >= 0.75 ? "pass" : q.metadataConfidence >= 0.45 ? "warn" : "fail", 1, `stage-A confidence ${q.metadataConfidence.toFixed(2)}`));
  const val: Record<Status, number> = { pass: 1, warn: 0.5, fail: 0, skip: 0 };
  const total = checks.reduce((s, x) => s + x.weight, 0);
  const measuredW = checks.filter((x) => x.status !== "skip").reduce((s, x) => s + x.weight, 0);
  const got = checks.filter((x) => x.status !== "skip").reduce((s, x) => s + x.weight * val[x.status], 0);
  const share = total ? measuredW / total : 0;
  let score = measuredW ? Math.round((100 * got / measuredW) * (0.4 + 0.6 * share)) : 0;
  if (checks.some((x) => x.hard && x.status === "fail")) score = Math.min(score, 20);
  return {
    score: Math.max(0, Math.min(100, score)), version: QUALITY_VERSION,
    method: "weighted pass ratio of measured checks x (0.4 + 0.6 x measured share); hard fail caps at 20",
    measured: Math.round(share * 100) / 100,
    checks: checks.map(({ hard: _h, ...rest }) => rest),
  };
}
  if (style) add(style);

  // ---- technical facts ---------------------------------------------------------------------------------------
  const tech: Tech = { format: raw.format, bytes: Math.max(0, Math.floor(raw.sizeBytes || 0)) };
  const g = measured.glb;
  if (kind === "model") {
    tech.triangles = g?.triangles ?? raw.triangles ?? null;
    if (g) { tech.vertices = g.vertices; tech.meshes = g.meshes; tech.materials = g.materials; tech.textures = g.textures; tech.bounds = g.bounds; tech.rigged = g.rigged; tech.animations = g.animations; }
    if (g?.rigged) add("rigged");
    if (g && g.animations > 0) add("animated");
  }
  if (kind === "sprite" || kind === "texture" || kind === "decal" || kind === "hdri" || kind === "texture-set") {
    tech.width = measured.image?.width ?? raw.width ?? resolutionPx(raw.resolution);
    tech.height = measured.image?.height ?? raw.height ?? (raw.resolution ? (kind === "hdri" ? (tech.width ?? 0) / 2 : tech.width) : null);
    if (measured.image) tech.hasAlpha = measured.image.hasAlpha;
    if (side?.files?.length) {
      const maps = new Set<string>();
      for (const f of side.files) for (const [re, m] of MAP_PATTERNS) if (re.test(f.replace(/\.[a-z0-9]+$/i, ""))) maps.add(m);
      if (maps.size) tech.maps = [...maps].sort();
    }
    if (side?.physicalSizeM) tech.physicalSizeM = side.physicalSizeM;
    if (kind === "texture-set") { add("pbr"); tech.tileable = true; add("tileable"); }
  }
  if (audio) {
    Object.assign(tech, { durationS: audio.durationS, sampleRate: audio.sampleRate, channels: audio.channels, bitDepth: audio.bitDepth, peakDb: audio.peakDb, truePeakDb: audio.truePeakDb, lufs: audio.lufs, silenceRatio: audio.silenceRatio, loopable: audio.loopable, centroidHz: audio.centroidHz, character: audio.character });
    add(audio.character);
    if (audio.intensity === "soft" || audio.intensity === "loud") add(audio.intensity);
    if (audio.pitchBand !== "mid") add(`${audio.pitchBand}-pitch`);
    if (audio.loopable) add("loopable"); else add("one-shot");
  } else if (kind === "sound" || kind === "music") gaps.push("audio not measured");
  if (kind === "model" && tech.triangles == null) gaps.push("triangles unknown");

  // ---- useFor ------------------------------------------------------------------------------------------------
  const tagSet = new Set([...tagsC, ...free]);
  // situations come from the primary category; secondaries only when the primary matches none (precision first)
  const matchFor = (cats: string[]) => VOCAB.useFor.filter((u) => {
    if (!u.kinds.includes(kind)) return false;
    const catOk = !u.categoriesAny || u.categoriesAny.some((p) => cats.some((c) => c === p || (p.endsWith("/") && c.startsWith(p))));
    const ucHit = !!u.useCasesAny?.some((x) => soundUseCases.includes(x));
    const tagHit = !!u.tagsAny?.some((t) => tagSet.has(t));
    const allOk = !u.tagsAll || u.tagsAll.every((t) => tagSet.has(t));
    const styleOk = !u.stylesAny || (style != null && u.stylesAny.includes(style));
    if (!catOk || !allOk || !styleOk) return false;
    if (u.useCasesAny && u.tagsAny) return ucHit || tagHit;
    if (u.useCasesAny) return ucHit;
    if (u.tagsAny) return tagHit;
    return true;

