// Postgres backend of the asset library (SERVER ONLY), on the Cyrus-prefixed tables of
// prisma/manual-migrations/2026-10-10-cyrus-catalog-v2.sql (CyrusCatalogEntry, store of record) and
// 2026-10-10-cyrus-library-backend.sql (postings, derivatives, uses, reports, moderation log, fingerprints).
// Opaque ids, no foreign keys into Nxeon tables. Talks to the database only through a 2-method Sql interface
// (prismaSql() adapts the host's CyrusDb raw-query methods), so a standalone Cyrus can pass any Postgres client.
//   PgCatalog.store   CatalogStore (pipeline.ts): batched upserts through jsonb_to_recordset; a row whose entryHash
//                     is unchanged is not rewritten (idempotent re-import)
//   PgCatalog.index   CatalogIndex: the SAME posting-list ranking as the memory / SQLite indexes, in one SQL statement
//                     (window functions), plus an optional trigram fallback (pg_trgm) when a query matches nothing
//   PgCatalog.records LibraryRecords (./records.ts)
//   PgCatalog.admin   the admin read model source (./admin.ts) incl. full-text find (to_tsvector / websearch_to_tsquery)
// HOST SEAM: no Nxeon imports.
import { createHash } from "node:crypto";
import type { CyrusDb } from "../../host/types";
import type { CatalogEntry, CatalogStatus } from "../v2/entry";
import type { CatalogStore } from "../v2/pipeline";
import { effectiveKinds, parseQuery, FIT_WEIGHT, MIN_WORD_SHARE, type CatalogHit, type CatalogIndex, type CatalogQuery } from "../v2/retrieval";
import { postingsOf } from "../v2/sqlite-index";
import type { RecipeId } from "./derive";
import { bands64, newId, type DerivativeRow, type FingerprintRow, type LibraryRecords, type ModerationRow, type ReportRow, type UseRow } from "./records";

export type Sql = { query<T = Record<string, unknown>>(text: string, ...params: unknown[]): Promise<T[]>; exec(text: string, ...params: unknown[]): Promise<number> };
export const prismaSql = (db: Pick<CyrusDb, "$queryRawUnsafe" | "$executeRawUnsafe">): Sql => ({
  query: <T>(t: string, ...p: unknown[]) => db.$queryRawUnsafe(t, ...p) as Promise<T[]>,
  exec: (t: string, ...p: unknown[]) => db.$executeRawUnsafe(t, ...p),
});

const E = `"CyrusCatalogEntry"`, T = `"CyrusCatalogTerm"`;
const num = (v: unknown) => (typeof v === "bigint" ? Number(v) : Number(v ?? 0));
const ts = (d: Date) => d.toISOString();
const TS = (i: number) => `($${i}::timestamptz AT TIME ZONE 'UTC')`;
const asDate = (v: unknown) => (v instanceof Date ? v : new Date(String(v) + (typeof v === "string" && !/[zZ+]/.test(v.slice(-6)) ? "Z" : "")));
const SYN = 0.85;
const GAME_ID = /^[a-z][a-z0-9-]{1,31}$/;

/** sha256 of the canonical entry JSON (key order fixed by the Zod output) */
export const entryHash = (e: CatalogEntry) => createHash("sha256").update(JSON.stringify(e)).digest("hex");
export const searchTextOf = (e: CatalogEntry) =>
  [e.title, e.shortDescription, ...e.tags, ...e.freeTags, e.categories.primary, ...e.categories.secondary, ...e.useFor, e.provenance.pack ?? "", e.style ?? ""].join(" ").toLowerCase().slice(0, 4000);
const rowOf = (e: CatalogEntry) => ({
  id: e.id, sv: e.schemaVersion, kind: e.kind, status: e.status, tier: e.licence.tier, pc: e.categories.primary, q: e.quality.score, eb: e.enrichment.by, cov: e.enrichment.coverage,
  src: e.provenance.source, pack: e.provenance.pack, grp: e.group, dup: e.duplicateOf, cid: e.contributedBy, st: searchTextOf(e), entry: e, sr: e.statusReason, h: entryHash(e),
});

export type UpsertReport = { inserted: number; updated: number; unchanged: number; terms: number };

export function createPgCatalog(sql: Sql, opts: { now?: () => Date; batch?: number; fuzzy?: boolean } = {}) {
  const now = opts.now ?? (() => new Date());
  const batch = Math.max(1, Math.min(2000, opts.batch ?? 500));
  let nCache: { n: number; at: number } | null = null;
  const N = async () => {
    if (nCache && Date.now() - nCache.at < 5000) return nCache.n;
    const n = num((await sql.query<{ n: bigint }>(`SELECT COUNT(*) AS n FROM ${E}`))[0]?.n);
    nCache = { n, at: Date.now() }; return n;
  };
  const parseEntry = (v: unknown) => (typeof v === "string" ? JSON.parse(v) : v) as CatalogEntry;

  /** Upsert entries + their postings; rows whose entryHash did not change are skipped. */
  async function upsertWithReport(es: readonly CatalogEntry[]): Promise<UpsertReport> {
    const rep: UpsertReport = { inserted: 0, updated: 0, unchanged: 0, terms: 0 };
    for (let i = 0; i < es.length; i += batch) {
      const rows = es.slice(i, i + batch).map(rowOf);
      const have = new Map((await sql.query<{ id: string; h: string | null }>(`SELECT id, "entryHash" AS h FROM ${E} WHERE id = ANY($1::text[])`, rows.map((r) => r.id))).map((r) => [r.id, r.h]));
      const changed = rows.filter((r) => have.get(r.id) !== r.h);
      rep.unchanged += rows.length - changed.length;
      for (const r of changed) (have.has(r.id) ? rep.updated++ : rep.inserted++);
      if (!changed.length) continue;
      const at = ts(now());
      await sql.exec(`INSERT INTO ${E} (id, "schemaVersion", kind, status, tier, "primaryCat", quality, "enrichedBy", coverage, source, pack, "groupKey", "duplicateOf", "contributorId", "searchText", entry, "statusReason", "entryHash", "createdAt", "updatedAt")
        SELECT x.id, x.sv, x.kind, x.status, x.tier, x.pc, x.q, x.eb, x.cov, x.src, x.pack, x.grp, x.dup, x.cid, x.st, x.entry, x.sr, x.h, ${TS(2)}, ${TS(2)}
        FROM jsonb_to_recordset($1::jsonb) AS x(id text, sv int, kind text, status text, tier text, pc text, q int, eb text, cov text, src text, pack text, grp text, dup text, cid text, st text, entry jsonb, sr text, h text)
        ON CONFLICT (id) DO UPDATE SET "schemaVersion" = EXCLUDED."schemaVersion", kind = EXCLUDED.kind, status = EXCLUDED.status, tier = EXCLUDED.tier, "primaryCat" = EXCLUDED."primaryCat",
          quality = EXCLUDED.quality, "enrichedBy" = EXCLUDED."enrichedBy", coverage = EXCLUDED.coverage, source = EXCLUDED.source, pack = EXCLUDED.pack, "groupKey" = EXCLUDED."groupKey",
          "duplicateOf" = EXCLUDED."duplicateOf", "contributorId" = EXCLUDED."contributorId", "searchText" = EXCLUDED."searchText", entry = EXCLUDED.entry, "statusReason" = EXCLUDED."statusReason",
          "entryHash" = EXCLUDED."entryHash", "updatedAt" = EXCLUDED."updatedAt"`, JSON.stringify(changed), at);
      const ids = changed.map((r) => r.id);
      await sql.exec(`DELETE FROM ${T} WHERE "entryId" = ANY($1::text[])`, ids);
      const terms: { t: string; e: string; w: number }[] = [];
      for (const r of changed) for (const [t, w] of postingsOf(r.entry)) terms.push({ t, e: r.id, w });
      for (let j = 0; j < terms.length; j += 20000) await sql.exec(`INSERT INTO ${T} (term, "entryId", w) SELECT x.t, x.e, x.w FROM jsonb_to_recordset($1::jsonb) AS x(t text, e text, w float8) ON CONFLICT DO NOTHING`, JSON.stringify(terms.slice(j, j + 20000)));
      rep.terms += terms.length;
      nCache = null;
    }
    return rep;
  }

  const store: CatalogStore = {
    async upsertMany(es) { await upsertWithReport(es); },
    async getMany(ids) { if (!ids.length) return []; return (await sql.query<{ entry: unknown }>(`SELECT entry FROM ${E} WHERE id = ANY($1::text[])`, [...ids])).map((r) => parseEntry(r.entry)); },
    async listByStatus(status, cursor, limit) {
      return (await sql.query<{ entry: unknown }>(`SELECT entry FROM ${E} WHERE status = $1 AND ($2::text IS NULL OR id > $2) ORDER BY id LIMIT $3`, status, cursor, Math.min(1000, Math.max(1, limit)))).map((r) => parseEntry(r.entry));
    },
    async setStatus(id, status, reason) {
      const [e] = await store.getMany([id]);
      if (!e) return null;
      const n: CatalogEntry = { ...e, status, statusReason: reason };
      await upsertWithReport([n]);
      return n;
    },
  };

  async function search(q: CatalogQuery): Promise<{ total: number; hits: CatalogHit[]; expanded: string[][] }> {
    const parsed = parseQuery(q.text ?? "");
    const kinds = effectiveKinds(q.kinds, parsed.kindHints);
    const terms = parsed.terms.slice(0, 24);
    const args: unknown[] = [];
    const p = (v: unknown, cast = "") => { args.push(v); return `$${args.length}${cast}`; };
    const ctes: string[] = [];
    if (terms.length) {
      const total = await N();
      const dfs = new Map((await sql.query<{ term: string; n: bigint }>(`SELECT term, COUNT(*) AS n FROM ${T} WHERE term = ANY($1::text[]) GROUP BY term`, terms.map((a) => a[0]))).map((r) => [r.term, num(r.n)]));
      const idf = (t: string) => Math.log(1 + (total + 1) / ((dfs.get(t) ?? 0) + 0.5));
      const parts = terms.map((alts) => `SELECT "entryId" AS id, MAX(CASE WHEN term = ${p(alts[0])} THEN w ELSE w * ${SYN} END) * ${p(idf(alts[0]), "::float8")} AS s FROM ${T} WHERE term = ANY(${p(alts, "::text[]")}) GROUP BY "entryId"`);
      const n = terms.length;
      ctes.push(`u AS (${parts.join(" UNION ALL ")})`);
      ctes.push(`t AS (SELECT id, SUM(s) * (COUNT(*)::float8 / ${n}) * (COUNT(*)::float8 / ${n}) AS tx FROM u GROUP BY id HAVING COUNT(*)::float8 / ${n} >= ${MIN_WORD_SHARE})`);
    }
    const game = q.game && GAME_ID.test(q.game) ? q.game : null;
    const fw = game ? `(CASE e.entry->'games'->${p(game)}->>'fit' WHEN 'good' THEN ${FIT_WEIGHT.good} WHEN 'ok' THEN ${FIT_WEIGHT.ok} WHEN 'no' THEN 0 ELSE ${FIT_WEIGHT.unknown} END)::float8` : "1.0::float8";
    const where: string[] = [`e."duplicateOf" IS NULL`];
    where.push(`e.status = ANY(${p(q.statuses ?? ["published"], "::text[]")})`);
    if (kinds?.length) where.push(`e.kind = ANY(${p([...kinds], "::text[]")})`);
    if (q.tiers) where.push(`e.tier = ANY(${p([...q.tiers], "::text[]")})`);
    if (q.minQuality != null) where.push(`e.quality >= ${p(q.minQuality, "::int")}`);
    for (const tg of q.tags ?? []) { const x = p(tg); where.push(`(jsonb_exists(e.entry->'tags', ${x}) OR jsonb_exists(e.entry->'freeTags', ${x}))`); }
    if (q.useFor?.length) where.push(`jsonb_exists_any(e.entry->'useFor', ${p([...q.useFor], "::text[]")})`);
    if (q.category) {
      const c = p(q.category.endsWith("/") ? q.category : q.category);
      where.push(q.category.endsWith("/")
        ? `(starts_with(e."primaryCat", ${c}) OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(e.entry->'categories'->'secondary') s WHERE starts_with(s, ${c})))`
        : `(e."primaryCat" = ${c} OR jsonb_exists(e.entry->'categories'->'secondary', ${c}))`);
    }
    if (game && !q.includeNoFit) where.push(`coalesce(e.entry->'games'->${p(game)}->>'fit', '') <> 'no'`);
    const from = terms.length ? `t JOIN ${E} e ON e.id = t.id` : `${E} e`;
    ctes.push(`h AS (SELECT e.id, e.quality, e."groupKey" AS grp, ${terms.length ? "t.tx" : "1.0::float8"} AS tx, ${fw} AS fw FROM ${from} WHERE ${where.join(" AND ")})`);
    ctes.push(`k AS (SELECT id, quality, grp, fw, CASE WHEN MAX(tx) OVER () > 0 THEN tx / MAX(tx) OVER () ELSE 1.0 END AS textn FROM h)`);
    ctes.push(`r AS (SELECT id, quality, grp, textn, textn * (0.6 + 0.4 * fw) * (0.75 + 0.25 * (quality / 100.0)) AS rank FROM k)`);
    const order = "rank DESC, quality DESC, id COLLATE \"C\" ASC";
    ctes.push(q.collapseGroups !== false
      ? `g AS (SELECT id, quality, rank, textn, ROW_NUMBER() OVER (PARTITION BY coalesce(grp, '#' || id) ORDER BY ${order}) AS rn, COUNT(*) OVER (PARTITION BY coalesce(grp, '#' || id)) AS gs FROM r)`
      : `g AS (SELECT id, quality, rank, textn, 1 AS rn, 1 AS gs FROM r)`);
    const off = Math.max(0, Math.floor(q.offset ?? 0)), lim = Math.min(50, Math.max(1, Math.floor(q.limit ?? 8)));
    const text = `WITH ${ctes.join(",\n")}, n AS (SELECT COUNT(*) AS total FROM r)
      SELECT n.total AS total, x.rank::float8 AS rank, x.textn::float8 AS textn, x.gs AS gs, e.entry AS entry
      FROM n LEFT JOIN (SELECT * FROM g WHERE rn = 1 ORDER BY rank DESC, quality DESC, id COLLATE "C" ASC LIMIT ${lim} OFFSET ${off}) x ON true
      LEFT JOIN ${E} e ON e.id = x.id
      ORDER BY x.rank DESC, x.quality DESC, x.id COLLATE "C" ASC`;
    const rows = await sql.query<{ total: bigint; rank: number | null; textn: number | null; gs: bigint | null; entry: unknown }>(text, ...args);
    const total = rows.length ? num(rows[0].total) : 0;
    let hits: CatalogHit[] = rows.filter((r) => r.entry != null).map((r) => ({ entry: parseEntry(r.entry), rank: Number(r.rank), text: Number(r.textn), groupSize: num(r.gs) }));
    if (!total && opts.fuzzy && (q.text ?? "").trim().length >= 3) hits = await fuzzy(q, kinds, lim).catch(() => []);
    return { total: total || hits.length, hits, expanded: parsed.terms };
  }

  /** typo fallback (pg_trgm): titles similar to the query text, same status / kind / tier / quality filters */
  async function fuzzy(q: CatalogQuery, kinds: readonly string[] | undefined, lim: number): Promise<CatalogHit[]> {
    const rows = await sql.query<{ entry: unknown; s: number }>(`SELECT entry, similarity(entry->>'title', $1)::float8 AS s FROM ${E} e
      WHERE e."duplicateOf" IS NULL AND e.status = ANY($2::text[]) AND ($3::text[] IS NULL OR e.kind = ANY($3::text[])) AND ($4::text[] IS NULL OR e.tier = ANY($4::text[])) AND e.quality >= $5
        AND (entry->>'title') % $1 ORDER BY s DESC, e.quality DESC, e.id LIMIT $6`,
      (q.text ?? "").trim().toLowerCase(), q.statuses ?? ["published"], kinds?.length ? [...kinds] : null, q.tiers ? [...q.tiers] : null, q.minQuality ?? 0, lim);
    return rows.map((r) => ({ entry: parseEntry(r.entry), rank: Number(r.s), text: Number(r.s), groupSize: 1 }));
  }

  const index: CatalogIndex = {
    upsert: async (es) => { await upsertWithReport(es); },
    async remove(ids) { await sql.exec(`DELETE FROM ${T} WHERE "entryId" = ANY($1::text[])`, [...ids]); await sql.exec(`DELETE FROM ${E} WHERE id = ANY($1::text[])`, [...ids]); nCache = null; },
    async get(idOrPrefix) {
      const pfx = idOrPrefix.replace(/^(cat:|c:)/, "").toLowerCase();
      if (!/^[0-9a-f]{8,64}$/.test(pfx)) return null;
      const rows = await sql.query<{ entry: unknown }>(pfx.length === 64 ? `SELECT entry FROM ${E} WHERE id = $1` : `SELECT entry FROM ${E} WHERE id >= $1 AND id < $2 ORDER BY id LIMIT 2`, ...(pfx.length === 64 ? [pfx] : [pfx, pfx + "g"]));
      return rows.length === 1 ? parseEntry(rows[0].entry) : null;
    },
    async shortId(id) {
      for (let n = 12; n < 64; n += 2) { const pf = id.slice(0, n); const c = await sql.query<{ n: bigint }>(`SELECT COUNT(*) AS n FROM (SELECT 1 FROM ${E} WHERE id >= $1 AND id < $2 LIMIT 2) x`, pf, pf + "g"); if (num(c[0]?.n) <= 1) return pf; }
      return id;
    },
    size: () => N(),
    search,
  };

  const records: LibraryRecords = {
    derivatives: {
      async get(e, r) { const x = await sql.query<Record<string, unknown>>(`SELECT * FROM "CyrusLibraryDerivative" WHERE "entryId" = $1 AND recipe = $2`, e, r); return x[0] ? derRow(x[0]) : null; },
      async put(d) {
        await sql.exec(`INSERT INTO "CyrusLibraryDerivative" ("entryId", recipe, "objectKey", bytes, tool, "createdAt", "lastUsedAt") VALUES ($1, $2, $3, $4, $5, ${TS(6)}, ${TS(7)})
          ON CONFLICT ("entryId", recipe) DO UPDATE SET "objectKey" = EXCLUDED."objectKey", bytes = EXCLUDED.bytes, tool = EXCLUDED.tool, "lastUsedAt" = EXCLUDED."lastUsedAt"`, d.entryId, d.recipe, d.objectKey, d.bytes, d.tool, ts(d.createdAt), ts(d.lastUsedAt));
      },
      async touch(e, r, at) { await sql.exec(`UPDATE "CyrusLibraryDerivative" SET "lastUsedAt" = ${TS(3)} WHERE "entryId" = $1 AND recipe = $2`, e, r, ts(at)); },
      async unusedSince(cutoff, limit) { return (await sql.query<Record<string, unknown>>(`SELECT * FROM "CyrusLibraryDerivative" WHERE "lastUsedAt" < ${TS(1)} ORDER BY "lastUsedAt" LIMIT $2`, ts(cutoff), limit)).map(derRow); },
      async forEntry(e) { return (await sql.query<Record<string, unknown>>(`SELECT * FROM "CyrusLibraryDerivative" WHERE "entryId" = $1`, e)).map(derRow); },
      async delete(e, r) { await sql.exec(`DELETE FROM "CyrusLibraryDerivative" WHERE "entryId" = $1 AND recipe = $2`, e, r); },
      async refs(k) { return num((await sql.query<{ n: bigint }>(`SELECT COUNT(*) AS n FROM "CyrusLibraryDerivative" WHERE "objectKey" = $1`, k))[0]?.n); },
    },
    uses: {
      async upsert(u, at) {
        const x = await sql.query<Record<string, unknown>>(`INSERT INTO "CyrusLibraryUse" ("projectId", "slotId", "entryId", kind, "copySha256", upstream, "createdAt", "updatedAt") VALUES ($1, $2, $3, $4, $5, $6, ${TS(7)}, ${TS(7)})
          ON CONFLICT ("projectId", "slotId") DO UPDATE SET "entryId" = EXCLUDED."entryId", kind = EXCLUDED.kind, "copySha256" = EXCLUDED."copySha256", upstream = EXCLUDED.upstream,
            "createdAt" = CASE WHEN "CyrusLibraryUse"."entryId" = EXCLUDED."entryId" THEN "CyrusLibraryUse"."createdAt" ELSE EXCLUDED."createdAt" END, "updatedAt" = EXCLUDED."updatedAt" RETURNING *`,
          u.projectId, u.slotId, u.entryId, u.kind, u.copySha256, u.upstream ?? "published", ts(at));
        return useRow(x[0]);
      },
      async get(pj, s) { const x = await sql.query<Record<string, unknown>>(`SELECT * FROM "CyrusLibraryUse" WHERE "projectId" = $1 AND "slotId" = $2`, pj, s); return x[0] ? useRow(x[0]) : null; },
      async forEntry(e) { return (await sql.query<Record<string, unknown>>(`SELECT * FROM "CyrusLibraryUse" WHERE "entryId" = $1 ORDER BY "projectId", "slotId"`, e)).map(useRow); },
      async markUpstream(e, status, at) { return sql.exec(`UPDATE "CyrusLibraryUse" SET upstream = $2, "updatedAt" = ${TS(3)} WHERE "entryId" = $1`, e, status, ts(at)); },
    },
    reports: {
      async add(r) {
        const dup = await sql.query<Record<string, unknown>>(`SELECT * FROM "CyrusLibraryReport" WHERE "entryId" = $1 AND reporter = $2 AND status = 'open' LIMIT 1`, r.entryId, r.reporter);
        if (dup[0]) return { row: repRow(dup[0]), created: false };
        const x = await sql.query<Record<string, unknown>>(`INSERT INTO "CyrusLibraryReport" (id, "entryId", reporter, reason, note, status, "createdAt") VALUES ($1, $2, $3, $4, $5, 'open', ${TS(6)}) RETURNING *`, newId("rep"), r.entryId, r.reporter, r.reason, r.note, ts(r.createdAt));
        return { row: repRow(x[0]), created: true };
      },
      async open(e, limit = 200) { return (await sql.query<Record<string, unknown>>(`SELECT * FROM "CyrusLibraryReport" WHERE status = 'open' AND ($1::text IS NULL OR "entryId" = $1) ORDER BY "createdAt" LIMIT $2`, e ?? null, limit)).map(repRow); },
      async resolve(e, status, by, at) { return sql.exec(`UPDATE "CyrusLibraryReport" SET status = $2, "resolvedBy" = $3, "resolvedAt" = ${TS(4)} WHERE "entryId" = $1 AND status = 'open'`, e, status, by, ts(at)); },
    },
    log: {
      async append(r) {
        const x = await sql.query<Record<string, unknown>>(`INSERT INTO "CyrusLibraryModeration" (id, "entryId", action, "fromStatus", "toStatus", "by", reason, legal, dependents, at) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, ${TS(10)}) RETURNING *`,
          newId("mod"), r.entryId, r.action, r.from, r.to, r.by, r.reason, r.legal, r.dependents, ts(r.at));
        return modRow(x[0]);
      },
      async list(q) {
        return (await sql.query<Record<string, unknown>>(`SELECT * FROM "CyrusLibraryModeration" WHERE ($1::text[] IS NULL OR action = ANY($1::text[])) AND ($2::text IS NULL OR "entryId" = $2) ORDER BY at DESC, id DESC LIMIT $3`,
          q.actions ? [...q.actions] : null, q.entryId ?? null, q.limit ?? 100)).map(modRow);
      },
    },
    fingerprints: {
      async put(r) {
        const b = bands64(r.fp).concat(["-", "-", "-", "-"]).slice(0, 4);
        await sql.exec(`INSERT INTO "CyrusLibraryFingerprint" ("entryId", kind, method, fp, b0, b1, b2, b3) VALUES ($1, $2, $3, $4, $5, $6, $7, $8) ON CONFLICT ("entryId") DO UPDATE SET kind = EXCLUDED.kind, method = EXCLUDED.method, fp = EXCLUDED.fp, b0 = EXCLUDED.b0, b1 = EXCLUDED.b1, b2 = EXCLUDED.b2, b3 = EXCLUDED.b3`, r.entryId, r.kind, r.method, r.fp, ...b);
      },
      async candidates(kind, method, fp) {
        const b = bands64(fp);
        const rows = await sql.query<FingerprintRow>(b.length === 4
          ? `SELECT "entryId", kind, method, fp FROM "CyrusLibraryFingerprint" WHERE kind = $1 AND method = $2 AND (b0 = $3 OR b1 = $4 OR b2 = $5 OR b3 = $6)`
          : `SELECT "entryId", kind, method, fp FROM "CyrusLibraryFingerprint" WHERE kind = $1 AND method = $2 AND fp = $3`, kind, method, ...(b.length === 4 ? b : [fp]));
        return rows.map((r) => ({ entryId: r.entryId, kind: r.kind, method: r.method, fp: r.fp }));
      },
    },
  };

  const admin = {
    async counts(): Promise<{ kind: string; tier: string; status: string; n: number }[]> {
      return (await sql.query<{ kind: string; tier: string; status: string; n: bigint }>(`SELECT kind, tier, status, COUNT(*) AS n FROM ${E} GROUP BY kind, tier, status ORDER BY kind, tier, status`)).map((r) => ({ ...r, n: num(r.n) }));
    },
    async derivativeStats(): Promise<{ recipe: string; n: number; bytes: number }[]> {
      return (await sql.query<{ recipe: string; n: bigint; bytes: bigint }>(`SELECT recipe, COUNT(*) AS n, COALESCE(SUM(bytes), 0) AS bytes FROM "CyrusLibraryDerivative" GROUP BY recipe ORDER BY recipe`)).map((r) => ({ recipe: r.recipe, n: num(r.n), bytes: num(r.bytes) }));
    },
    async openReports(): Promise<number> { return num((await sql.query<{ n: bigint }>(`SELECT COUNT(*) AS n FROM "CyrusLibraryReport" WHERE status = 'open'`))[0]?.n); },
    async usesOfRemoved(): Promise<number> { return num((await sql.query<{ n: bigint }>(`SELECT COUNT(*) AS n FROM "CyrusLibraryUse" WHERE upstream = 'removed'`))[0]?.n); },
    /** admin find: Postgres full text over searchText (simple dictionary) */
    async find(text: string, limit = 50): Promise<CatalogEntry[]> {
      return (await sql.query<{ entry: unknown }>(`SELECT entry FROM ${E} WHERE to_tsvector('simple', "searchText") @@ websearch_to_tsquery('simple', $1) ORDER BY quality DESC, id LIMIT $2`, text.slice(0, 200), Math.min(200, limit))).map((r) => parseEntry(r.entry));
    },
  };

  return { store, index, records, admin, upsertWithReport };
}
export type PgCatalog = ReturnType<typeof createPgCatalog>;

const derRow = (r: Record<string, unknown>): DerivativeRow => ({ entryId: String(r.entryId), recipe: r.recipe as RecipeId, objectKey: String(r.objectKey), bytes: num(r.bytes), tool: String(r.tool), createdAt: asDate(r.createdAt), lastUsedAt: asDate(r.lastUsedAt) });
const useRow = (r: Record<string, unknown>): UseRow => ({ entryId: String(r.entryId), projectId: String(r.projectId), slotId: String(r.slotId), kind: r.kind as UseRow["kind"], copySha256: (r.copySha256 as string | null) ?? null, upstream: r.upstream as CatalogStatus, createdAt: asDate(r.createdAt), updatedAt: asDate(r.updatedAt) });
const repRow = (r: Record<string, unknown>): ReportRow => ({ id: String(r.id), entryId: String(r.entryId), reporter: String(r.reporter), reason: r.reason as ReportRow["reason"], note: (r.note as string | null) ?? null, status: r.status as ReportRow["status"], createdAt: asDate(r.createdAt), resolvedAt: r.resolvedAt ? asDate(r.resolvedAt) : null, resolvedBy: (r.resolvedBy as string | null) ?? null });
const modRow = (r: Record<string, unknown>): ModerationRow => ({ id: String(r.id), entryId: String(r.entryId), action: r.action as ModerationRow["action"], from: (r.fromStatus as CatalogStatus | null) ?? null, to: (r.toStatus as CatalogStatus | null) ?? null, by: String(r.by), reason: (r.reason as string | null) ?? null, legal: r.legal === true, dependents: num(r.dependents), at: asDate(r.at) });

