// Admin READ MODEL of the asset library (read-only JSON; the ops report in lib/cyrus/delivery/admin.ts embeds it as
// `library` when the backend switch is on): counts by kind / licence tier / status, the hold queue (what the owner
// reviews), the takedown log, open reports, derivative cache size and how many project slots still use a removed
// asset (they keep working from their own copy). HOST SEAM: the source is injected (./pg.ts admin + records).
import type { CatalogEntry } from "../v2/entry";
import type { ModerationRow, ReportRow } from "./records";

export type LibraryAdminSource = {
  counts(): Promise<{ kind: string; tier: string; status: string; n: number }[]>;
  held(limit: number): Promise<CatalogEntry[]>;
  openReports(limit: number): Promise<ReportRow[]>;
  log(limit: number): Promise<ModerationRow[]>;
  derivativeStats(): Promise<{ recipe: string; n: number; bytes: number }[]>;
  usesOfRemoved(): Promise<number>;
};
export type LibraryAdminView = {
  total: number;
  byKind: Record<string, number>; byTier: Record<string, number>; byStatus: Record<string, number>;
  matrix: { kind: string; tier: string; status: string; n: number }[];
  holdQueue: { id: string; kind: string; title: string; tier: string; reason: string | null; flags: string[]; contributor: string | null; reports: number }[];
  openReports: number;
  takedownLog: { at: string; entryId: string; action: string; from: string | null; to: string | null; by: string; reason: string | null; legal: boolean; dependents: number }[];
  derivatives: { recipe: string; n: number; bytes: number }[];
  dependentsOfRemoved: number;
};

export async function libraryAdminView(src: LibraryAdminSource, opts: { limit?: number } = {}): Promise<LibraryAdminView> {
  const limit = Math.min(200, Math.max(1, opts.limit ?? 50));
  const [matrix, held, reports, log, der, removedUses] = await Promise.all([src.counts(), src.held(limit), src.openReports(500), src.log(limit), src.derivativeStats(), src.usesOfRemoved()]);
  const sum = (k: "kind" | "tier" | "status") => matrix.reduce<Record<string, number>>((m, r) => { m[r[k]] = (m[r[k]] ?? 0) + r.n; return m; }, {});
  const reportsBy = new Map<string, number>();
  for (const r of reports) reportsBy.set(r.entryId, (reportsBy.get(r.entryId) ?? 0) + 1);
  return {
    total: matrix.reduce((s, r) => s + r.n, 0),
    byKind: sum("kind"), byTier: sum("tier"), byStatus: sum("status"), matrix,
    holdQueue: held.map((e) => ({ id: e.id, kind: e.kind, title: e.title, tier: e.licence.tier, reason: e.statusReason, flags: e.flags, contributor: e.contributedBy, reports: reportsBy.get(e.id) ?? 0 })),
    openReports: reports.length,
    takedownLog: log.filter((r) => ["takedown", "restore", "hold", "release"].includes(r.action)).map((r) => ({ at: r.at.toISOString(), entryId: r.entryId, action: r.action, from: r.from, to: r.to, by: r.by, reason: r.reason, legal: r.legal, dependents: r.dependents })),
    derivatives: der,
    dependentsOfRemoved: removedUses,
  };
}

