    const evade = await contributeAsset(tex("green gem 3", png(64, 64, { seed: 30, tweak: true }).subarray(0) && png(64, 64, { seed: 30 }).map((x, i) => (i === 100 ? x ^ 1 : x)) as unknown as Uint8Array), b.deps);
    // the byte-flipped PNG is corrupt (CRC) -> quality hard fail -> held either way; a clean near copy is tested below
    assert.equal(evade.outcome, "held");
    const clean = png(64, 64, { seed: 30 }); const px2 = png(64, 64, { seed: 30, tweak: true });
