describe("reports, hold queue, takedown (dependents keep working), restore", () => {
  it("one report is noted; a legal report holds at once; N different reporters hold; the same reporter twice counts once", async () => {
    const b = backend();
    const md = { catalog: b.catalog, index: b.index, records: b.records, now: b.now };
    const e1 = (await contributeAsset(tex("star", png(16, 16, { seed: 40 })), b.deps) as { entry: CatalogEntry }).entry;
    const r1 = await report(md, { entryId: e1.id, reporter: "u:aaaa", reason: "broken" });
    assert.ok(r1.ok && !r1.held);
    const r1b = await report(md, { entryId: e1.id, reporter: "u:aaaa", reason: "broken" });
    assert.ok(r1b.ok && !r1b.created);
    await report(md, { entryId: e1.id, reporter: "u:bbbb", reason: "offensive" });
    const r3 = await report(md, { entryId: e1.id, reporter: "u:cccc", reason: "other" });
    assert.ok(r3.ok && r3.held, `held at ${REPORT_HOLD_THRESHOLD} reporters`);
    const e2 = (await contributeAsset(tex("moon", png(16, 16, { seed: 41 })), b.deps) as { entry: CatalogEntry }).entry;
    const legal = await report(md, { entryId: e2.id, reporter: "u:dddd", reason: "copyright" });
    assert.ok(legal.ok && legal.held);
    assert.equal((await report(md, { entryId: e2.id, reporter: "u:dddd", reason: "nope" })).ok, false);
    const q = await holdQueue(md);
    assert.equal(q.length, 2);
    const rel = await release(md, { entryId: e2.id, by: "owner:1", note: "own art, checked" });
    assert.ok(rel.ok && rel.entry.status === "published" && rel.entry.flags.includes("cleared:reports") && validateCatalogEntry(rel.entry).ok);
  });
  it("takedown: removed now, out of search, derivatives purged (410), dependents marked; their mods keep building from their own copy, even after a plan downgrade", async () => {
    const b = backend();
    const md = { catalog: b.catalog, index: b.index, records: b.records, store: b.store, now: b.now };
    const e = (await contributeAsset(tex("sun", png(16, 16, { seed: 50 })), b.deps) as { entry: CatalogEntry }).entry;
    const thumb = await b.store.derivative(e, "thumb@1");
    assert.ok(thumb.ok && thumb.from === "generated");
    assert.equal((await b.store.derivative(e, "thumb@1") as { from: string }).from, "cache");
    const sink = createMemoryProjectSink();
    const used = await useCatalogAsset({ ref: `cat:${e.id}`, projectId: "proj_one", slotId: "sun_icon", plan: "all", proprietaryCleared: false, game: "minecraft" }, { index: b.index, store: b.store, uses: b.records.uses, sink, now: b.now });
    assert.ok(used.ok && used.copy?.sha256 === e.id && used.slot.libraryRef === `cat:${e.id}` && used.slot.source === "library");
    const td = await takedown(md, { entryId: e.id, by: "owner:1", reason: "trademark claim", legal: true });
    assert.ok(td.ok && td.dependents === 1 && td.purged === 1);
    assert.equal((await b.index.search({ text: "sun" })).total, 0);
    assert.equal((await b.records.derivatives.forEntry(e.id)).length, 0);
    assert.equal((canServe(td.ok ? td.entry : e, "thumb@1", { signedIn: true, plan: "all" }, { proprietaryCleared: false }) as { status: number }).status, 410);
    // the existing mod: resolved from its own copy, with a notice, not plan-gated (owner downgraded to free)
    const ctx = { index: b.index, plan: "free", game: "minecraft", proprietaryCleared: false, projectId: "proj_one", uses: b.records.uses };
    const keep = await resolveSlotForBuild({ id: "sun_icon", kind: "texture", source: "library", libraryRef: `cat:${e.id}` }, ctx);
    assert.ok(keep.ok && keep.from === "project-copy" && keep.copySha256 === e.id && keep.upstream === "removed" && keep.notice);
    // a NEW pick of the removed asset (another project) is refused
    const fresh = await resolveSlotForBuild({ id: "sun_icon", kind: "texture", source: "library", libraryRef: `cat:${e.id}` }, { ...ctx, plan: "all", projectId: "proj_two" });
    assert.ok(!fresh.ok && fresh.code === "not_published");
    const log = await takedownLog({ records: b.records });
    assert.ok(log.some((r) => r.action === "takedown" && r.legal && r.dependents === 1));
    const back = await restore(md, { entryId: e.id, by: "owner:1", reason: "claim withdrawn" });
    assert.ok(back.ok && back.entry.status === "held");
  });
});

describe("Use in project (plan gate + licence tiers; never gates keeping)", () => {
  it("sounds Saka+, visuals the top plan, proprietary only when cleared and never copied raw; re-use is idempotent", async () => {
    const b = backend();
    const sound = entry({ path: "kenney/x/beep.ogg", kind: "sound", format: "ogg", bytes: Buffer.from("OggS-beep") });
    const model = entry({ path: "kenney/x/crate.glb", kind: "model", format: "glb", bytes: CRATE });
    const prop = entry({ path: "nxeon-proprietary/p/boom.mp3", kind: "sound", format: "mp3", tier: "proprietary-nxeon", bytes: Buffer.from("ID3-boom") });
    await b.index.upsert([sound, model, prop]); await b.catalog.upsertMany([sound, model, prop]);
    await b.objects.put(Buffer.from("OggS-beep")); await b.objects.put(CRATE);
    const sink = createMemoryProjectSink();
    const deps = { index: b.index, store: b.store, uses: b.records.uses, sink, now: b.now };
    const use = (ref: string, plan: string, slotId: string, cleared = false) => useCatalogAsset({ ref, projectId: "proj_a", slotId, plan, proprietaryCleared: cleared, game: null }, deps);
    assert.equal((await use(`cat:${sound.id}`, "free", "s1") as { code: string }).code, "asset_locked");
    assert.equal((await use(`cat:${sound.id}`, "katara", "s1") as { code: string }).code, "asset_locked");
    const ok = await use(`cat:${sound.id}`, "saka", "s1");
    assert.ok(ok.ok && ok.copy?.sha256 === sound.id && ok.slot.kind === "sound");
    assert.equal((await use(`cat:${model.id}`, "saka", "m1") as { code: string }).code, "asset_locked");
    assert.ok((await use(`cat:${model.id}`, "all", "m1")).ok);
    assert.equal((await use(`cat:${prop.id}`, "all", "p1") as { code: string }).code, "tier_locked");
    const p = await use(`cat:${prop.id}`, "all", "p1", true);
    assert.ok(p.ok && p.copy === null && p.rule?.includes("never copied"));
    const again = await use(`cat:${sound.id}`, "free", "s1");
