    assert.equal((await use("cat:nothex", "all", "x1") as { code: string }).code, "bad_ref");
    // proprietary library render after the clearance is withdrawn: the build says so instead of shipping it
    const r = await resolveSlotForBuild({ id: "p1", kind: "sound", source: "library", libraryRef: `cat:${prop.id}` }, { index: b.index, plan: "all", game: null, proprietaryCleared: false, projectId: "proj_a", uses: b.records.uses });
    assert.ok(!r.ok && r.code === "upstream_unavailable");
  });
});

describe("LibraryStore retention + caps", () => {
  it("unused derivatives expire; a removed community asset's own object goes after the grace period; nothing else", async () => {
    const b = backend();
    const md = { catalog: b.catalog, index: b.index, records: b.records, store: b.store, now: b.now };
    const keepE = (await contributeAsset(tex("keep", png(16, 16, { seed: 60 })), b.deps) as { entry: CatalogEntry }).entry;
    const goneE = (await contributeAsset(tex("gone", png(16, 16, { seed: 61 })), b.deps) as { entry: CatalogEntry }).entry;
    await b.store.derivative(keepE, "thumb@1");
    await takedown(md, { entryId: goneE.id, by: "owner:1", reason: "spam" });
    b.advance((RETENTION.derivativeUnusedDays + 1) * 86_400_000);
    const s = await b.store.sweep({ catalog: b.catalog });
    assert.equal(s.derivativesDropped, 1);
    assert.equal(s.removedOriginalsDeleted, 1);
    assert.equal(await b.objects.has(keyOf(keepE.id)), true);
    assert.equal(await b.objects.has(keyOf(goneE.id)), false);
    assert.equal((await b.store.sweep({ catalog: b.catalog })).removedOriginalsDeleted, 0, "idempotent");
  });
  it("contributions over the per-kind cap are refused", async () => {
    const b = backend();
    const r = await contributeAsset(tex("big", new Uint8Array(9 * 1024 * 1024)), b.deps);
    assert.equal(r.outcome, "too_large");
  });
});

