describe("HTTP handlers (flag-gated, signed, re-checked at fetch time)", () => {
  const secret = "k".repeat(48);
  function httpDeps(over: Partial<LibraryHttpDeps> = {}) {
    const b = backend();
    const deps: LibraryHttpDeps = {
      flags: { ...libraryFlags({ CYRUS_LIBRARY_BACKEND: "1", CYRUS_LIBRARY_STORE: "local", CYRUS_LIBRARY_LOCAL_DIR: "/x", CYRUS_LIBRARY_URL_SECRET: secret }) },
      viewer: async () => ({ userId: "user-1" }), planOf: async () => "all",
      backend: () => ({ index: b.index, catalog: b.catalog, store: b.store, records: b.records }),
      rateLimit: () => ({ ok: true }), now: () => +NOW, ...over,
    };
    return { b, deps };
  }
  const post = (body: unknown) => new Request("http://x/api", { method: "POST", body: JSON.stringify(body) });
  it("off = 404; not a viewer = 404", async () => {
    const { deps } = httpDeps({ flags: libraryFlags({}) });
    assert.equal((await handleSignUrl(post({}), deps)).status, 404);
    assert.equal((await handleSignUrl(post({}), { ...httpDeps().deps, viewer: async () => null })).status, 404);
  });
  it("sign -> fetch serves the thumbnail; another viewer gets 403; a takedown makes the same URL 410", async () => {
    const { b, deps } = httpDeps();
    const e = (await contributeAsset(tex("ruby", png(16, 16, { seed: 80 })), b.deps) as { entry: CatalogEntry }).entry;
    const s = await handleSignUrl(post({ id: e.id, variant: "thumb@1" }), deps);
    assert.equal(s.status, 200);
    const { url } = await s.json() as { url: string };
    const token = url.split("/").pop()!;
    const f = await handleFile(new Request("http://x" + url), { token }, deps);
    assert.equal(f.status, 200);
    assert.equal(f.headers.get("content-type"), "image/png");
    assert.match(f.headers.get("cache-control")!, /^private, max-age=\d+$/);
    assert.equal(f.headers.get("x-content-type-options"), "nosniff");
    assert.equal((await handleFile(new Request("http://x"), { token }, { ...deps, viewer: async () => ({ userId: "user-2" }) })).status, 403);
    assert.equal((await handleFile(new Request("http://x"), { token }, { ...deps, planOf: async () => "saka" })).status, 403, "the plan is re-checked at fetch time");
    await takedown({ catalog: b.catalog, index: b.index, records: b.records, store: b.store, now: b.now }, { entryId: e.id, by: "owner:1", reason: "x" });
    assert.equal((await handleFile(new Request("http://x"), { token }, deps)).status, 410);
    assert.equal((await handleFile(new Request("http://x"), { token }, { ...deps, now: () => +NOW + 3_600_000 })).status, 410, "expired");
  });
  it("a raw audio URL cannot even be signed; reports go through the moderation rules", async () => {
    const { b, deps } = httpDeps();
    const s = entry({ path: "kenney/x/beep.ogg", kind: "sound", format: "ogg" });
    await b.index.upsert([s]); await b.catalog.upsertMany([s]);
    const r = await handleSignUrl(post({ id: s.id, variant: "original" }), deps);
    assert.equal(r.status, 403);
    assert.equal((await r.json() as { code: string }).code, "raw_audio");
    const rep = await handleReport(post({ id: s.id, reason: "copyright", note: "mine" }), deps);
    assert.equal(rep.status, 200);
    assert.equal((await rep.json() as { held: boolean }).held, true);
    assert.equal((await handleReport(post({ id: s.id, reason: "bogus" }), deps)).status, 400);
  });
});

