// Cyrus asset library backend (r26, lib/cyrus/library/backend + the SQLite v2 index): storage (local / S3 / staging,
// content-addressed, caps, retention), deterministic derivatives, signed URLs, the serve rules (raw audio never,
// proprietary only when cleared, plan gate + licence tiers), automatic contribution (eligibility, content filters,
// exact + near dedupe, blocklist), reports / hold queue / takedown that keeps dependent mods working, "Use in
// project", the importer, the admin read model, the HTTP handlers and the SQLite index's exact parity with the memory
// index (+ golden summary). No network, no model, no database (the Postgres store: cyrus-library-backend-db.test.ts).
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { minecraftAssetProfile } from "../lib/cyrus/adapters/minecraft";
import { createMemoryCatalogIndex, type CatalogQuery } from "../lib/cyrus/library/v2/retrieval";
