/** w x h RGBA PNG with a deterministic gradient (+ optional single-pixel change) */
function png(w: number, h: number, opts: { tweak?: boolean; seed?: number } = {}): Buffer {
  const px = new Uint8ClampedArray(w * h * 4);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { const o = (y * w + x) * 4; px[o] = (x * 255) / w; px[o + 1] = (y * 255) / h; px[o + 2] = ((x + y + (opts.seed ?? 0)) * 37) % 256; px[o + 3] = 255; }
  if (opts.tweak) px[0] = 255 - px[0];
  return encodeRgbaPng(w, h, px);
}
function glb(json: object): Uint8Array {
  let j = Buffer.from(JSON.stringify(json));
  if (j.length % 4) j = Buffer.concat([j, Buffer.alloc(4 - (j.length % 4), 0x20)]);
  const h = Buffer.alloc(20);
  h.writeUInt32LE(0x46546c67, 0); h.writeUInt32LE(2, 4); h.writeUInt32LE(20 + j.length, 8); h.writeUInt32LE(j.length, 12); h.writeUInt32LE(0x4e4f534a, 16);
  return new Uint8Array(Buffer.concat([h, j]));
}
const CRATE = glb({ asset: { version: "2.0" }, scene: 0, scenes: [{ nodes: [0] }], nodes: [{ mesh: 0 }], meshes: [{ primitives: [{ attributes: { POSITION: 0 }, indices: 1 }] }], accessors: [{ count: 24, min: [-0.5, 0, -0.5], max: [0.5, 1, 0.5] }, { count: 36 }], materials: [{}] });

/** a published catalog entry of any kind/tier, through stage A (so it is a real, valid entry) */
function entry(over: { path: string; kind: string; format: string; tier?: string; bytes?: Uint8Array; name?: string; status?: CatalogEntry["status"] }): CatalogEntry {
  const b = over.bytes ?? Buffer.from(over.path);
  const r = enrichStageA({ id: sha(b), source: over.path.split("/")[0], pack: over.path.split("/")[1], path: over.path, kind: over.kind, format: over.format, sizeBytes: b.length, tier: over.tier ?? "cc0", licenseSpdx: over.tier === "proprietary-nxeon" ? null : "CC0-1.0", licenseUrl: over.tier === "proprietary-nxeon" ? null : "https://example.org/l", licenceNote: over.tier === "proprietary-nxeon" ? "owner library" : null, retrievedAt: "2026-10-10", name: over.name ?? null },
    { profiles: [minecraftAssetProfile], now: NOW.toISOString() }, undefined, over.kind === "sound" ? { audio: { durationS: 1.2, sampleRate: 44100, channels: 1, bitDepth: 16, peakDb: -3, truePeakDb: -3, lufs: -18, silenceRatio: 0, dcOffset: 0, loopable: false, centroidHz: 2000, character: "transient", durationClass: "short", intensity: "loud", pitchBand: "mid" } } : over.kind === "model" ? { glb: { triangles: 12, vertices: 24, meshes: 1, materials: 1, textures: 0, images: 0, rigged: false, animations: 0, bounds: [1, 1, 1] } } : { image: { width: 16, height: 16, hasAlpha: true } });
  assert.ok(r.entry, JSON.stringify(r.errors));
  return { ...r.entry!, status: over.status ?? "published", statusReason: null, flags: [] };
}

