describe("SQLite index v2: exact parity with the memory index", () => {
  let entries: CatalogEntry[] = [];
  before(async () => {
    const g = loadGoldenSample();
    entries = (await ingestRows(g.rows, { profiles: [minecraftAssetProfile], packs: g.packs, now: "2026-10-10T00:00:00Z" })).entries;
    // add variety the sample lacks: a removed + a held entry, a duplicate, a proprietary sound, groups
    entries.push(entry({ path: "kenney/x/removed_crate.png", kind: "sprite", format: "png", status: "removed" }));
    entries.push(entry({ path: "kenney/x/held_crate.png", kind: "sprite", format: "png", status: "held" }));
    entries.push(entry({ path: "nxeon-proprietary/pack1/gunshot_heavy.mp3", kind: "sound", format: "mp3", tier: "proprietary-nxeon" }));
  });
  const QUERIES: CatalogQuery[] = [
    { text: "crate" }, { text: "wooden door" }, { text: "medieval sword weapon" }, { text: "sound" }, { text: "" }, { text: "stone wall floor texture", limit: 20 },
    { text: "tile", kinds: ["sprite"] }, { text: "crate", game: "minecraft" }, { text: "crate", game: "minecraft", includeNoFit: true },
    { text: "", tiers: ["cc0"], minQuality: 60, limit: 30 }, { text: "", tiers: [] }, { text: "crate", statuses: ["published", "held", "removed"] },
    { text: "", category: "weapons/" }, { text: "", category: "weapons/melee" }, { text: "", tags: ["medieval"] }, { text: "", useFor: ["melee-weapon-prop"] },
    { text: "", offset: 8, limit: 8 }, { text: "", offset: 5000 }, { text: "", collapseGroups: false, limit: 40 }, { text: "gunshot", kinds: ["sound"] },
  ];
  it("same ids, ranks, totals and group sizes for every query shape", async () => {
    const mem = createMemoryCatalogIndex(entries);
    const sql = await createSqliteCatalogIndex(":memory:");
    await sql.upsert(entries);
    assert.equal(await sql.size(), entries.length);
    for (const q of QUERIES) {
      const a = await mem.search(q), b = await sql.search(q);
      const label = JSON.stringify(q);
      assert.equal(b.total, a.total, `total ${label}`);
      assert.deepEqual(b.hits.map((h) => h.entry.id), a.hits.map((h) => h.entry.id), `ids ${label}`);
      assert.deepEqual(b.hits.map((h) => h.groupSize), a.hits.map((h) => h.groupSize), `groups ${label}`);
      a.hits.forEach((h, i) => assert.ok(Math.abs(h.rank - b.hits[i].rank) < 1e-9, `rank ${label}`));
    }
    sql.close();
  });
  it("re-upsert and remove keep it consistent; get by prefix; shortId", async () => {
    const sql = await createSqliteCatalogIndex(":memory:");
    await sql.upsert(entries); await sql.upsert(entries.slice(0, 20));
    assert.equal(await sql.size(), entries.length);
    await sql.remove([entries[0].id]);
    assert.equal(await sql.size(), entries.length - 1);
    assert.equal(await sql.get(entries[0].id), null);
    assert.equal((await sql.get(entries[1].id.slice(0, 16)))?.id, entries[1].id);
    assert.ok((await sql.shortId(entries[1].id)).length >= 12);
    sql.close();
  });
  it("a v1 (FTS5) cache file is detected and emptied, never misread", async () => {
    const f = path.join(tmp, "v1.db");
    const { DatabaseSync } = (await import("node:sqlite" as string)) as { DatabaseSync: new (f: string) => { exec(s: string): void; close(): void } };
    const d = new DatabaseSync(f);
    d.exec("CREATE TABLE entry (rid INTEGER PRIMARY KEY, id TEXT NOT NULL UNIQUE, kind TEXT, status TEXT, tier TEXT, quality INTEGER, dup TEXT, json TEXT NOT NULL); INSERT INTO entry (id, json) VALUES ('x', '{}');");
    d.close();
    const sql = await createSqliteCatalogIndex(f);
    assert.equal(await sql.size(), 0);
    await sql.upsert(entries.slice(0, 5));
    sql.close();
    const again = await createSqliteCatalogIndex(f);
    assert.equal(await again.size(), 5, `persisted at user_version ${SQLITE_INDEX_VERSION}`);
    again.close();
  });
});

describe("object stores", () => {
  it("LocalObjectStore: content-addressed, idempotent, sharded, verified on read", async () => {
    const s = new LocalObjectStore(path.join(tmp, "obj"));
    const b = Buffer.from("hello library");
    const k = await s.put(b);
    assert.equal(k, `sha256/${sha(b)}`);
    assert.equal(await s.put(b), k);
    assert.ok(s.pathFor(k).includes(`/sha256/${sha(b).slice(0, 2)}/`));
    assert.deepEqual(Buffer.from((await s.get(k))!), b);
    assert.equal(await s.size(k), b.length);
    const listed: string[] = []; for await (const o of s.list()) listed.push(o.key);
    assert.deepEqual(listed, [k]);
    fs.writeFileSync(s.pathFor(k), "tampered");
    assert.equal(await s.get(k), null, "a corrupt object reads as missing");
    await s.delete(k);
    assert.equal(await s.has(k), false);
    assert.throws(() => s.pathFor("../etc/passwd"));
  });
  it("S3ObjectStore: signed requests, private keys under the prefix, hash-checked GET, paginated LIST", async () => {
    const bucket = new Map<string, Buffer>();
    const seen: { method: string; url: string; auth: string | null }[] = [];
    const fake = (async (url: string, init: RequestInit) => {
      const u = new URL(url); const key = decodeURIComponent(u.pathname.split("/").slice(2).join("/"));
      seen.push({ method: init.method!, url, auth: (init.headers as Record<string, string>).authorization ?? null });
      if (init.method === "HEAD") return new Response(null, { status: bucket.has(key) ? 200 : 404, headers: bucket.has(key) ? { "content-length": String(bucket.get(key)!.length) } : {} });
      if (init.method === "PUT") { bucket.set(key, Buffer.from(init.body as Uint8Array)); return new Response("", { status: 200 }); }
      if (init.method === "DELETE") { bucket.delete(key); return new Response(null, { status: 204 }); }
      if (u.searchParams.get("list-type") === "2") {
        const keys = [...bucket.keys()].sort(); const tok = u.searchParams.get("continuation-token"); const start = tok ? Number(tok) : 0; const page = keys.slice(start, start + 1);
        const more = start + 1 < keys.length;
        return new Response(`<ListBucketResult>${page.map((k) => `<Contents><Key>${k}</Key><Size>${bucket.get(k)!.length}</Size><LastModified>2026-10-10T00:00:00Z</LastModified></Contents>`).join("")}<IsTruncated>${more}</IsTruncated>${more ? `<NextContinuationToken>${start + 1}</NextContinuationToken>` : ""}</ListBucketResult>`, { status: 200 });
      }
      return bucket.has(key) ? new Response(new Uint8Array(bucket.get(key)!), { status: 200 }) : new Response("", { status: 404 });
    }) as unknown as typeof fetch;
    const s = new S3ObjectStore({ endpoint: "https://s3.example.test", bucket: "cyrus-lib", region: "auto", credentials: { accessKeyId: "AK", secretAccessKey: "SK" }, prefix: "library", fetch: fake, now: () => NOW });
    const a = Buffer.from("one"), b = Buffer.from("two");
    const ka = await s.put(a); await s.put(b); await s.put(a);
    assert.equal(seen.filter((x) => x.method === "PUT").length, 2, "an existing object is not uploaded again");
    assert.ok(seen.every((x) => x.auth?.startsWith("AWS4-HMAC-SHA256 Credential=AK/20261010/auto/s3/aws4_request")));
    assert.ok([...bucket.keys()].every((k) => k.startsWith("library/sha256/")));
    assert.deepEqual(Buffer.from((await s.get(ka))!), a);
    bucket.set(`library/${ka}`, Buffer.from("evil"));
    assert.equal(await s.get(ka), null, "bytes that do not match their key are refused");
    const keys: string[] = []; for await (const o of s.list()) keys.push(o.key);
    assert.equal(keys.length, 2);
    assert.throws(() => new S3ObjectStore({ endpoint: "http://s3.example.test", bucket: "b-1", region: "auto", credentials: { accessKeyId: "a", secretAccessKey: "b" } }));
  });
  it("StagingSource: read-only, path-confined, sha256-checked, capped", async () => {
    const root = path.join(tmp, "staging");
    fs.mkdirSync(path.join(root, "kenney/pack"), { recursive: true });
    fs.writeFileSync(path.join(root, "kenney/pack/a.png"), "AAA");
    fs.writeFileSync(path.join(tmp, "secret.txt"), "SECRET");
    fs.symlinkSync(path.join(tmp, "secret.txt"), path.join(root, "kenney/pack/link.png"));
    const st = new StagingSource(root);
    assert.equal((await st.read("kenney/pack/a.png", sha("AAA"), 10)).ok, true);
    assert.equal((await st.read("kenney/pack/a.png", sha("BBB"), 10) as { code: string }).code, "hash_mismatch");
    assert.equal((await st.read("kenney/pack/a.png", sha("AAA"), 2) as { code: string }).code, "too_large");
    assert.equal((await st.read("../secret.txt", sha("SECRET"), 99) as { code: string }).code, "outside_root");
    assert.equal((await st.read("/etc/passwd", "0".repeat(64), 99) as { code: string }).code, "outside_root");
    assert.equal((await st.read("kenney/pack/link.png", sha("SECRET"), 99) as { code: string }).code, "outside_root", "a symlink out of the root is refused");
    assert.deepEqual(await st.listDir("kenney/pack"), ["a.png", "link.png"]);
    assert.deepEqual(await st.listDir("../"), []);
  });
});

