    const big = thumbFromPng(png(1024, 512));
    assert.ok(big.ok && big.width === 256 && big.height === 128);
    const again = thumbFromPng(png(1024, 512));
    assert.ok(again.ok && big.ok && again.png.equals(big.png));
    assert.equal(sha(thumbFromPng(png(16, 16)).ok ? (thumbFromPng(png(16, 16)) as { png: Buffer }).png : ""), sha((small as { png: Buffer }).png));
    assert.equal(thumbFromPng(Buffer.from("not a png")).ok, false);
