  it("ffmpeg preview: fixed argv (no shell), 30 s mono Vorbis, bit-exact, metadata stripped; output capped", async () => {
    const calls: { bin: string; args: readonly string[] }[] = [];
    const run: ToolRunner = (bin, args) => { calls.push({ bin, args }); return { status: 0, stdout: Buffer.concat([Buffer.from("OggS"), Buffer.alloc(100)]), stderr: "" }; };
    const e = entry({ path: "kenney/x/beep.ogg", kind: "sound", format: "ogg" });
    const r = await runRecipe("preview-ogg@1", { entry: e, original: async () => Buffer.from("x"), thumbSource: async () => null, folder: async () => null }, { ...noTools, ffmpeg: "/usr/bin/ffmpeg", run });
    assert.ok(r.ok);
    assert.deepEqual(calls[0].args, FFMPEG_PREVIEW_ARGS);
    for (const a of ["-t", "30", "-ac", "1", "+bitexact", "-map_metadata", "libvorbis"]) assert.ok(FFMPEG_PREVIEW_ARGS.includes(a), a);
    const huge: ToolRunner = () => ({ status: 0, stdout: Buffer.concat([Buffer.from("OggS"), Buffer.alloc(3 * 1024 * 1024)]), stderr: "" });
    const capped = await runRecipe("preview-ogg@1", { entry: e, original: async () => Buffer.from("x"), thumbSource: async () => null, folder: async () => null }, { ...noTools, ffmpeg: "/x", run: huge });
    assert.equal(!capped.ok && capped.code, "too_large");
