  it("folder bundle: deterministic zip of the image files only", async () => {
    const e = { ...entry({ path: "ambientcg/Material/Wood096", kind: "texture-set", format: "jpg+pbr-maps" }) };
    const files = [{ name: "Wood096_Color.jpg", bytes: Buffer.from("c") }, { name: "Wood096.blend", bytes: Buffer.from("b") }, { name: "Wood096.mtlx", bytes: Buffer.from("m") }];
    const a = await runRecipe("bundle@1", { entry: e, original: async () => null, thumbSource: async () => null, folder: async () => files }, noTools);
    const b = await runRecipe("bundle@1", { entry: e, original: async () => null, thumbSource: async () => null, folder: async () => [...files].reverse() }, noTools);
    assert.ok(a.ok && b.ok && Buffer.from(a.bytes).equals(Buffer.from(b.bytes)));
    assert.ok(a.ok && !Buffer.from(a.bytes).includes(Buffer.from("Wood096.blend")));
  });
});

describe("signed URLs", () => {
  const secret = "s".repeat(40), id = "a".repeat(64), sub = opaqueViewer("user-1", secret);
  it("sign + verify; expiry; tamper; wrong viewer; ttl is capped", () => {
    const t = signLibraryUrl({ id, variant: "thumb@1", sub }, secret, +NOW);
    const ok = verifyLibraryUrl(t, secret, sub, +NOW + 1000);
    assert.ok(ok.ok && ok.claims.id === id && ok.claims.r === "thumb@1");
    assert.equal((verifyLibraryUrl(t, secret, sub, +NOW + 301_000) as { code: string }).code, "expired");
    assert.equal((verifyLibraryUrl(t, secret, opaqueViewer("user-2", secret), +NOW) as { code: string }).code, "wrong_viewer");
    assert.equal((verifyLibraryUrl(t, secret, null, +NOW) as { code: string }).code, "wrong_viewer");
    const [p, s] = t.split(".");
    const forged = Buffer.from(JSON.stringify({ ...JSON.parse(Buffer.from(p, "base64url").toString()), r: "original" })).toString("base64url");
    assert.equal((verifyLibraryUrl(`${forged}.${s}`, secret, sub, +NOW) as { code: string }).code, "bad_signature");
    assert.equal((verifyLibraryUrl(t, "t".repeat(40), sub, +NOW) as { code: string }).code, "bad_signature");
    const long = verifyLibraryUrl(signLibraryUrl({ id, variant: "thumb@1", sub, ttlSec: 99999 }, secret, +NOW), secret, sub, +NOW);
    assert.ok(long.ok && long.claims.exp - long.claims.iat === URL_TTL_MAX_S);
    assert.notEqual(sub, "user-1"); assert.ok(!sub.includes("user"));
    assert.throws(() => signLibraryUrl({ id, variant: "thumb@1", sub }, "short", +NOW));
  });
});

describe("serve rules", () => {
  const sound = entry({ path: "kenney/x/beep.ogg", kind: "sound", format: "ogg" });
  const prop = entry({ path: "nxeon-proprietary/p/boom.mp3", kind: "sound", format: "mp3", tier: "proprietary-nxeon" });
  const sprite = entry({ path: "kenney/x/coin.png", kind: "sprite", format: "png" });
  const set = entry({ path: "ambientcg/Material/Wood096", kind: "texture-set", format: "jpg+pbr-maps" });
  const F = { proprietaryCleared: false };
  const v = (plan: unknown) => ({ signedIn: true, plan });
  it("raw audio is never served; previews follow the plan gate (sounds Saka+)", () => {
    assert.equal((canServe(sound, "original", v("all"), F) as { code: string }).code, "raw_audio");
    assert.equal(canServe(sound, "preview-ogg@1", v("saka"), F).ok, true);
    assert.equal((canServe(sound, "preview-ogg@1", v("katara"), F) as { code: string }).code, "asset_locked");
    assert.equal((canServe(sound, "preview-ogg@1", v("free"), F) as { code: string }).code, "asset_locked");
    assert.equal((canServe(sound, "preview-ogg@1", v(null), F) as { code: string }).code, "plan_unknown");
  });
  it("the proprietary library: never an original, previews only once cleared", () => {
    assert.equal((canServe(prop, "preview-ogg@1", v("all"), F) as { code: string }).code, "not_cleared");
    assert.equal(canServe(prop, "preview-ogg@1", v("all"), { proprietaryCleared: true }).ok, true);
    assert.equal((canServe(prop, "original", v("all"), { proprietaryCleared: true }) as { code: string }).code, "raw_audio");
  });
  it("visuals need the top plan; status rules; folder sets come as bundles", () => {
    assert.equal((canServe(sprite, "thumb@1", v("saka"), F) as { code: string }).code, "asset_locked");
    assert.equal(canServe(sprite, "original", v("all"), F).ok, true);
    assert.equal((canServe({ ...sprite, status: "removed" }, "thumb@1", v("all"), F) as { status: number }).status, 410);
    assert.equal((canServe({ ...sprite, status: "held" }, "thumb@1", v("all"), F) as { status: number }).status, 404);
    assert.equal((canServe(set, "original", v("all"), F) as { code: string }).code, "use_bundle");
    assert.equal(canServe(set, "bundle@1", v("all"), F).ok, true);
    assert.equal((canServe(sprite, "preview-ogg@1", v("all"), F) as { code: string }).code, "no_variant");
    assert.equal((canServe(sprite, "thumb@1", { signedIn: false, plan: "all" }, F) as { code: string }).code, "sign_in");
  });
});

function backend() {
  const objects = createMemoryLibraryObjectStore(() => NOW);
  const records = createMemoryLibraryRecords();
  const catalog = createMemoryCatalogStore();
  const index = createMemoryCatalogIndex();
  let clock = +NOW;
  const now = () => new Date(clock);
  const store = new LibraryStore({ objects, staging: null, records, tools: { ffmpeg: null, python: null, gltfTransform: null, run: () => ({ status: 1, stdout: Buffer.alloc(0), stderr: "" }) }, now });
  const deps: ContributionDeps = { enabled: true, catalog, index, objects, records, profiles: [minecraftAssetProfile], now };
  return { objects, records, catalog, index, store, deps, now, advance: (ms: number) => { clock += ms; } };
}
const manifest = (over: Partial<{ legalClass: string; source: string; derivedFrom: string[] }> = {}) => ({ legalClass: (over.legalClass ?? "user-original") as "user-original", provenance: { source: (over.source ?? "user") as "user", derivedFrom: over.derivedFrom ?? [] } });
const tex = (name: string, bytes: Uint8Array, over: Partial<ContributionInput> = {}): ContributionInput => ({ studio: "texture", kind: "sprite", format: "png", bytes, name, manifest: manifest(), contributorId: "ctr_alpha", ...over });

