const KIND_NOUN: Record<CatalogKind, string> = { model: "3D model", "texture-set": "PBR texture set", texture: "texture", sprite: "sprite", hdri: "HDRI sky", decal: "decal", sound: "sound", music: "music", motion: "motion preset" };

/** Deterministic <= 140-char description: what it is, its category, the key fact, the pack. */
export function describeEntry(kind: CatalogKind, title: string, primary: string, style: string | null, t: Tech, pack: string, useFor: readonly string[]): string {
  const cat = primary.split("/").pop()!.replace(/[-_]/g, " ");
  const st = style ? `${style.replace(/-/g, " ")} ` : "";
  let fact = "";
  if (kind === "model" && t.triangles != null) fact = `${t.triangles.toLocaleString("en-US")} tris${t.animations ? `, ${t.animations} anims` : t.rigged ? ", rigged" : ""}`;
  else if ((kind === "sound" || kind === "music") && t.durationS != null) fact = `${t.durationS < 10 ? t.durationS.toFixed(1) : Math.round(t.durationS)} s${t.loopable ? ", loopable" : ""}`;
  else if (t.width && t.height) fact = `${t.width}x${t.height}${t.maps?.length ? `, ${t.maps.length} maps` : ""}`;
  const use = useFor.length ? `; for ${useForLabel(useFor[0])}` : "";
  const head = `${st}${KIND_NOUN[kind]}: ${title.toLowerCase()} (${cat})`;
  const s = `${head.charAt(0).toUpperCase()}${head.slice(1)}${fact ? `, ${fact}` : ""}${use}. From ${pack}.`;
  return clip(s.length >= 10 ? s : `${s} asset`, 140);
}

