s += '''
// ---- motion / effect kinds (r26) ------------------------------------------------------------------------------------
type EffectRule = { tokensAny: string[]; category: string; useFor?: string };
const EFFECT_RULES = ((VOCAB as unknown as { effectRules?: EffectRule[] }).effectRules ?? []);
const CLIP_TOKENS = ((VOCAB as unknown as { clipTokens?: Record<string, string[]> }).clipTokens ?? {});
const LOOP_WORDS = /(^|[^a-z])(loop|looping|idle|walk|run|swim|fly|cycle)([^a-z]|$)/i;

/** clip-name words -> controlled clip tags (walk -> walk + locomotion; reload -> reload ...) */
export function clipTags(ws: readonly string[]): string[] {
  const out = new Set<string>();
  for (const w of ws) for (const t of CLIP_TOKENS[w.toLowerCase()] ?? []) out.add(t);
  return [...out].filter(isControlled);
}

/** category votes for a motion row: the ingest's own category (same vocabulary) + the effect rules on the words */
function motionVotes(v: Vote, raw: RawAsset, kind: CatalogKind, ws: readonly string[]) {
  const doms = DOMAINS[kind];
  const ok = (id: string | undefined): id is string => !!id && isCategory(id) && doms.includes(id.split("/")[0]);
  if (ok(raw.categories?.primary)) vote(v, raw.categories!.primary!, 6);
  for (const s of raw.categories?.secondary ?? []) if (ok(s)) vote(v, s, 2);
  const bag = new Set(ws.map((w) => w.toLowerCase()));
  for (const r of EFFECT_RULES) if (ok(r.category) && r.tokensAny.some((t) => bag.has(t) || bag.has(t.replace(/-/g, "")))) vote(v, r.category, 3);
  if (kind === "animation-clip" && !v.size) vote(v, "motion/clip", 1);
  if ((kind === "flipbook" || kind === "particle-texture") && !v.size && isCategory("vfx/particles")) vote(v, "vfx/particles", 1);
}

/** technical facts of motion rows: flipbook sidecar (frames, grid, fps, loop, blend), clip (duration, keyframes), clip counts */
function motionTech(raw: RawAsset, measured: Measured, kind: CatalogKind): { tech: Partial<Tech>; tags: string[]; gaps: string[] } {
  const t: Partial<Tech> = {};
  const tags: string[] = [], gaps: string[] = [];
  const int = (n: unknown) => (typeof n === "number" && Number.isFinite(n) && n >= 0 ? Math.round(n) : null);
  if (kind === "flipbook" || kind === "particle-texture") {
    t.width = int(raw.width) ?? measured.image?.width ?? null; t.height = int(raw.height) ?? measured.image?.height ?? null;
    if (measured.image) t.hasAlpha = measured.image.hasAlpha;
    if (kind === "flipbook") {
      t.frames = int(raw.frames);
      t.grid = Array.isArray(raw.grid) && raw.grid.length === 2 && raw.grid.every((x) => Number.isInteger(x) && x >= 1) ? [raw.grid[0], raw.grid[1]] : null;
      t.frameSize = Array.isArray(raw.frameSize) && raw.frameSize.length === 2 && raw.frameSize.every((x) => Number.isInteger(x) && x >= 1) ? [raw.frameSize[0], raw.frameSize[1]] : null;
      t.fps = typeof raw.fps === "number" && raw.fps > 0 && raw.fps <= 240 ? raw.fps : null;
      t.loop = typeof raw.loop === "boolean" ? raw.loop : null;
      if (t.frames == null) gaps.push("frame count unknown");
      if (!t.grid && !/sequence/.test(raw.format)) gaps.push("grid not known");
      if (t.fps == null) gaps.push("fps unknown");
    }
    const b = raw.blendHint?.toLowerCase();
    t.blend = b === "additive" || b === "normal" || b === "opaque" ? b : null;
    if (t.blend) tags.push(t.blend);
  } else if (kind === "animation-clip") {
    t.durationS = typeof raw.durationSec === "number" && raw.durationSec >= 0 ? raw.durationSec : null;
    t.clipName = raw.clip ? raw.clip.slice(0, 80) : null;
    t.keyframes = int(raw.keyframes); t.tracks = int(raw.channels ?? raw.tracks);
    t.loop = raw.clip ? LOOP_WORDS.test(raw.clip) : null;
    if (t.durationS == null) gaps.push("clip duration unknown");
  } else if (kind === "animated-model") {
    const g = measured.glb;
    t.animations = g?.animations ?? int(raw.clipCount) ?? (raw.clips?.length ?? null);
    t.triangles = g?.triangles ?? int(raw.triangles);
    if (g) { t.vertices = g.vertices; t.meshes = g.meshes; t.materials = g.materials; t.bounds = g.bounds; t.rigged = g.rigged; }
    if (raw.format.toLowerCase() === "fbx") gaps.push("fbx: needs conversion to glb");
    tags.push("animated");
  }
  if (t.loop === true) tags.push("loop"); else if (t.loop === false && kind !== "animated-model") tags.push("oneshot");
  return { tech: t, tags: tags.filter(isControlled), gaps };
}
'''
