type EffectRule = { tokensAny: string[]; category: string; useFor?: string };
const EFFECT_RULES = ((VOCAB as unknown as { effectRules?: EffectRule[] }).effectRules ?? []);
const CLIP_TOKENS = ((VOCAB as unknown as { clipTokens?: Record<string, string[]> }).clipTokens ?? {});
const LOOP_WORDS = /(^|[^a-z])(loop|looping|idle|walk|run|swim|fly|cycle)([^a-z]|$)/i;

/** clip-name words -> controlled clip tags (walk -> walk + locomotion; reload -> reload ...) */
export function clipTags(ws: readonly string[]): string[] {
