// Real derivative run over a READ-ONLY copy of staged assets (no model calls, no network):
//   npx tsx scripts/cyrus/library-derive-sample.ts --entries entries.jsonl --ids ids.txt --staging <dir> --store <dir> [--out r.json]
// For each listed entry: every recipe that applies (thumb@1, bundle@1, glb-opt@1, preview-ogg@1), generated through
// LibraryStore (lazy, cached), then a SECOND pass that must be served from the cache. Tools come from
// CYRUS_LIBRARY_FFMPEG / _PYTHON / _GLTF_TRANSFORM (unset = honestly reported as tool_missing).
import { readFileSync, writeFileSync } from "node:fs";
import { validateCatalogEntry, type CatalogEntry } from "../../lib/cyrus/library/v2/entry";
import { recipesFor, spawnTool } from "../../lib/cyrus/library/backend/derive";
import { libraryFlags } from "../../lib/cyrus/library/backend/flags";
import { LibraryStore } from "../../lib/cyrus/library/backend/library-store";
import { LocalObjectStore, StagingSource } from "../../lib/cyrus/library/backend/objects";
import { createMemoryLibraryRecords } from "../../lib/cyrus/library/backend/records";

const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };

async function main() {
  const [file, idsFile, staging, storeDir] = [arg("--entries"), arg("--ids"), arg("--staging"), arg("--store")];
  if (!file || !idsFile || !staging || !storeDir) { console.error("usage: --entries f.jsonl --ids ids.txt --staging dir --store dir [--out r.json]"); process.exit(2); }
  const ids = new Set(readFileSync(idsFile, "utf8").split("\n").filter(Boolean));
  const entries: CatalogEntry[] = [];
  for (const l of readFileSync(file, "utf8").split("\n")) { if (!l) continue; const id = l.slice(l.indexOf('"id":"') + 6, l.indexOf('"id":"') + 70); if (!ids.has(id)) continue; const v = validateCatalogEntry(JSON.parse(l)); if (v.ok) entries.push(v.entry); }
  const f = libraryFlags();
  const store = new LibraryStore({ objects: new LocalObjectStore(storeDir), staging: new StagingSource(staging), records: createMemoryLibraryRecords(), tools: { ...f.tools, run: spawnTool } });
  const rows: Record<string, { ok: number; failed: Record<string, number>; bytes: number; ms: number; cacheHits: number }> = {};
  const t0 = Date.now();
  for (const pass of [1, 2]) {
    for (const e of entries) for (const r of recipesFor(e)) {
      const k = `${e.kind} ${r}`;
      const row = (rows[k] ??= { ok: 0, failed: {}, bytes: 0, ms: 0, cacheHits: 0 });
      const t = Date.now();
      const out = await store.derivative(e, r);
      if (pass === 1) {
        row.ms += Date.now() - t;
        if (out.ok) { row.ok++; row.bytes += out.bytes.length; } else row.failed[out.code] = (row.failed[out.code] ?? 0) + 1;
      } else if (out.ok && out.from === "cache") row.cacheHits++;
    }
  }
  const summary = { entries: entries.length, seconds: (Date.now() - t0) / 1000, tools: f.tools, recipes: rows };
  console.log(JSON.stringify(summary, null, 1));
  if (arg("--out")) writeFileSync(arg("--out")!, JSON.stringify(summary, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });

