import { PrismaClient } from "@prisma/client";
import { createPgCatalog, prismaSql } from "../lib/cyrus/library/backend/pg";
import { createSqliteCatalogIndex } from "../lib/cyrus/library/v2/sqlite-index";
async function main() {
  const prisma = new PrismaClient();
  const pg = createPgCatalog(prismaSql(prisma));
  const sq = await createSqliteCatalogIndex(".data/cyrus-bench/index-v2.db");
  for (const text of ["car", "wooden door"]) {
    const q = { text, minQuality: 40, limit: 50 };
    const a = await pg.index.search(q), b = await sq.search(q);
    console.log(text, a.total, b.total);
    // collect all ids: page through
    const ids = async (ix: typeof sq) => { const s = new Set<string>(); for (let off = 0; off < 20000; off += 50) { const r = await ix.search({ ...q, offset: off, collapseGroups: false }); if (!r.hits.length) break; r.hits.forEach((h) => s.add(h.entry.id)); } return s; };
    const A = await ids(pg.index), B = await ids(sq);
    const onlyB = [...B].filter((x) => !A.has(x)).slice(0, 5);
    for (const id of onlyB) { const e = await sq.get(id); const terms = await prisma.$queryRawUnsafe<{ term: string }[]>(`SELECT term FROM "CyrusCatalogTerm" WHERE "entryId" = $1`, id); const row = await prisma.$queryRawUnsafe<{ q: number; s: string; d: string | null }[]>(`SELECT quality AS q, status AS s, "duplicateOf" AS d FROM "CyrusCatalogEntry" WHERE id = $1`, id); console.log(" only sqlite", id.slice(0, 12), e?.title, e?.quality.score, e?.status, e?.duplicateOf, JSON.stringify(row), terms.length); }
  }
  await prisma.$disconnect(); sq.close();
}
main();
EOF
