15	const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
16	
17	async function main() {
18	  const abs = (p: string | undefined) => (p ? path.resolve(p) : undefined);
19	  const [file, idsFile, staging, storeDir] = [arg("--entries"), arg("--ids"), abs(arg("--staging")), abs(arg("--store"))];
20	  if (!file || !idsFile || !staging || !storeDir) { console.error("usage: --entries f.jsonl --ids ids.txt --staging dir --store dir [--out r.json]"); process.exit(2); }
